-- DE enrichment
UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Delaware uses a per se blood alcohol concentration standard at the legal limit and an aggravated tier at higher concentrations","Per se chemical test results above the legal threshold create a prima facie case without requiring proof of observable impairment","Standardized field sobriety test performance, body camera footage, and officer observations stack into a layered evidentiary case","Implied consent provisions create automatic administrative license consequences for refusal that operate independently of the criminal outcome","Delaware traffic enforcement is concentrated on I-95, Route 1, and the Coastal Highway corridor, generating a steady stream of impairment prosecutions"}',
  defense_opportunities = '{"Challenge the legality of the initial traffic stop — without reasonable suspicion, all subsequent evidence becomes vulnerable to suppression","Examine whether the field sobriety battery was administered according to the standardized federal protocols — deviations are grounds for exclusion","Demand calibration, maintenance, and operator certification records for the breath testing instrument used","Investigate the observation period before breath testing — failures here are common procedural errors that affect reliability","Rising blood alcohol theory — the BAC at the time of driving may have been below the legal threshold and only rose between the stop and the test"}',
  common_defenses = '{"Improper traffic stop — officer lacked reasonable suspicion to initiate the contact","Rising blood alcohol — actual BAC at time of driving was below the legal limit","Mouth alcohol contamination — recent drinking, dental work, or reflux conditions caused a falsely elevated breath reading","Medical condition mimicking impairment — diabetes, neurological conditions, fatigue, or injury explain observed signs","No actual physical control — defendant was not operating the vehicle in the legally relevant sense"}'
WHERE common_charge_slug = 'dui-dwi' AND jurisdiction = 'DE';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Even a first offense in Delaware carries mandatory license consequences, creating significant collateral pressure","Per se chemical test evidence allows conviction without proof of actual driving impairment","Officer observations and field sobriety test performance are typically sufficient for a first-offense conviction","Mandatory minimum penalties for first offenses cannot be fully suspended in most jurisdictions"}',
  defense_opportunities = '{"Negotiate a plea reduction to a lesser driving offense — a common first-offense resolution that avoids the most severe DUI consequences","Explore diversion, treatment court, or deferred prosecution options available to first-time offenders","Delaware uses a sentencing accountability matrix that allows graduated alternatives to incarceration","Challenge breath test reliability through calibration records and operator certification"}',
  common_defenses = '{"Plea reduction to a lesser driving offense as an alternative resolution","Improper field sobriety test administration — deviations from the standardized protocol","Medical condition affecting field sobriety test performance","Insufficient evidence of impairment — driving was lawful and observed signs do not establish intoxication"}'
WHERE common_charge_slug = 'dui-first-offense' AND jurisdiction = 'DE';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Mandatory minimums for repeat offenses cannot be suspended or probated in most cases","Prior convictions are admissible to establish the repeat-offense element","Felony elevation triggers (typically third or fourth offense) dramatically increase sentencing exposure","Delaware uses a long lookback window for prior driving offenses, increasing the stakes of older convictions"}',
  defense_opportunities = '{"Challenge the validity of prior convictions — were procedural rights properly observed","Examine the lookback window — priors outside the window should not count for enhancement","Investigate whether prior convictions actually qualify as DUIs versus plea-reduced offenses","Negotiate for substance abuse treatment court or intensive monitoring as alternatives to incarceration"}',
  common_defenses = '{"Invalid prior convictions — prior conviction was obtained without counsel or with a defective plea","Lookback period challenge — prior conviction falls outside the enhancement window","Prior conviction was a reduced charge that does not qualify as a DUI for enhancement","Independent chemical test denial — defendant requested an independent test and was denied"}'
WHERE common_charge_slug = 'dui-repeat-offense' AND jurisdiction = 'DE';

