UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Florida criminal code covers a wide range of offenses beyond the common categories.","Specific statutory language defines the elements clearly for each unique offense.","Documented evidence specific to the charged offense.","Expert testimony when the offense involves specialized knowledge."}',
