UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"First-offense DUI in Georgia is a misdemeanor of high and aggravated nature with mandatory minimum 24-hour jail or community service.","Mandatory $300-$1,000 fine, 12 months probation, 40 hours community service, and DUI Risk Reduction Program (DUI School)."}',
  defense_opportunities = '{"Georgia first-offenders may petition for limited driving permit allowing work, school, and medical travel.","Pretrial diversion programs in some Georgia counties for first-time offenders.","Challenge ALS suspension separately from criminal proceedings — different burden and different forum."}',
  common_defenses = '{"Improper stop — officer lacked articulable suspicion to initiate the traffic stop.","Faulty field sobriety test administration — NHTSA standards must be strictly followed for HGN, walk-and-turn, and one-leg stand.","Breath test challenges — Intoxilyzer 9000 reliability, calibration records, and operator qualifications."}'
