UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Second DUI within 10 years carries mandatory 72 hours jail; third within 10 years is felony with mandatory 15-day jail.","Mandatory ignition interlock for second and subsequent offenses upon license reinstatement.","License suspension extends to 3 years (second within 5 years) or 5 years (third within 5 years)."}',
  defense_opportunities = '{"Challenge prior DUI convictions for proper Boykin colloquies — uncounseled pleas may not count for enhancement.","Lookback period calculation — Georgia uses dates of offenses, not convictions, providing potential challenges.","Negotiate to lesser charge if priors are weak or invalid."}',
