UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"First-degree vehicular homicide carries 3-15 years prison; second-degree is misdemeanor.","First-degree based on DUI, fleeing, hit and run, reckless driving, or other serious traffic offenses.","Accident reconstruction evidence establishes speed, point of impact, and causation."}',
