UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Hawaii prosecutes operating a vehicle while under the influence of an intoxicant — covering both alcohol and drug impairment under one charging framework","Per se chemical test results above the legal threshold create a prima facie case without requiring proof of observable impairment","Standardized field sobriety test performance, body camera footage, and officer observations stack into a layered evidentiary case","Implied consent provisions create automatic administrative license consequences for refusal that operate independently of the criminal outcome","Hawaii enforcement varies dramatically between Honolulu urban density and rural roads on the neighbor islands, generating a steady stream of impairment prosecutions"}',
  defense_opportunities = '{"Challenge the legality of the initial traffic stop — without reasonable suspicion, all subsequent evidence becomes vulnerable to suppression","Examine whether the field sobriety battery was administered according to the standardized federal protocols — deviations are grounds for exclusion","Demand calibration, maintenance, and operator certification records for the breath testing instrument used","Investigate the observation period before breath testing — failures here are common procedural errors that affect reliability","Rising blood alcohol theory — the BAC at the time of driving may have been below the legal threshold and only rose between the stop and the test"}',
  common_defenses = '{"Improper traffic stop — officer lacked reasonable suspicion to initiate the contact","Rising blood alcohol — actual BAC at time of driving was below the legal limit","Mouth alcohol contamination — recent drinking, dental work, or reflux conditions caused a falsely elevated breath reading","Medical condition mimicking impairment — diabetes, neurological conditions, fatigue, or injury explain observed signs","No actual physical control — defendant was not operating the vehicle in the legally relevant sense"}'
WHERE common_charge_slug = 'dui-dwi' AND jurisdiction = 'HI';

UPDATE jurisdiction_statutes SET
