UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Prior certified convictions within the lookback period are straightforward to prove through court records","Escalating mandatory minimums (7 days second, 30 days third, 120 days fourth) severely limit judicial discretion","Aggravating circumstances double already-significant mandatory minimums for repeat offenders"}',
