UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Wantonness standard requires only awareness of and conscious disregard for a substantial and unjustifiable risk","Applies broadly to deaths resulting from criminal negligence or wanton conduct in various contexts (DUI, workplace, etc.)","Expert testimony on the standard of care and the defendant''s deviation from it supports the prosecution''s case"}',
  defense_opportunities = '{"The line between criminal negligence and civil negligence is frequently blurred — defense can argue the conduct was merely civilly negligent","Class C Felony with probation eligibility means non-incarceration outcomes are possible","Causation challenges — the defendant''s conduct may not have been the proximate cause of death","Involuntary manslaughter is often the result of tragic circumstances rather than malicious conduct, which can influence jury sympathy"}',
  common_defenses = '{"Challenging causation — an intervening cause or the victim''s own conduct caused the death","Arguing the conduct was merely negligent, not wanton — the defendant did not consciously disregard a known risk","Accident defense — the death was an unforeseeable consequence of otherwise lawful conduct","Challenging the prosecution''s expert testimony on the applicable standard of care"}'
