-- MO enrichment
UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Lifetime lookback for prior DWI convictions means every prior counts toward enhanced charges regardless of how old the conviction is.","Standardized field sobriety tests and dashcam/bodycam footage provide strong corroborating evidence beyond chemical testing.","Aggravated offender (BAC .15+) and chronic offender (5+ priors) classifications carry enhanced mandatory penalties."}',
  defense_opportunities = '{"Challenge the legality of the traffic stop — Missouri requires reasonable suspicion, and suppression of the stop eliminates all downstream evidence.","Question the 15-minute observation period required before breath testing under Missouri Department of Health regulations; failure to observe can invalidate the result.","SIS (Suspended Imposition of Sentence) is available for first offenses, meaning no conviction appears on the record if probation is completed — strong incentive for negotiation.","Challenge the accuracy and maintenance records of the breath testing instrument (DataMaster or Intoxilyzer) used by the arresting agency.","Rising blood alcohol defense — argue that BAC was below .08 at the time of driving but rose between the stop and the test."}',
  common_defenses = '{"Improper stop — no reasonable suspicion for the initial traffic stop or checkpoint did not comply with Missouri requirements.","Breath test instrument malfunction or improper calibration as documented in maintenance logs.","Rising BAC defense — alcohol was still absorbing and BAC was below the legal limit at the time of actual driving.","Involuntary intoxication — defendant was unknowingly drugged or consumed a substance without knowledge of its intoxicating properties.","Necessity or duress — defendant drove under emergency circumstances to avoid greater harm."}'
WHERE common_charge_slug = 'dui-dwi' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Standardized field sobriety test results and officer training documentation provide strong testimony even without chemical evidence.","Implied consent penalties for refusal (1-year license revocation) discourage test refusal, ensuring prosecution usually has chemical evidence.","Dashcam and bodycam footage capturing erratic driving, slurred speech, or failed field tests is highly persuasive to juries."}',
  defense_opportunities = '{"SIS (Suspended Imposition of Sentence) availability means a first-time offender can complete probation and have no conviction on their record.","Only a Class B Misdemeanor with no mandatory minimum imprisonment, giving significant room for alternative sentencing negotiations.","Challenge whether the officer had proper training and certification to administer and interpret standardized field sobriety tests.","Medical conditions (GERD, diabetes, certain diets) can produce falsely elevated breath test readings — documented medical history can undermine BAC evidence."}',
  common_defenses = '{"Improper administration of field sobriety tests — failure to follow NHTSA standardized procedures invalidates results.","Medical condition defense — GERD, acid reflux, or diabetes producing mouth alcohol or ketones that inflate breath test readings.","Lack of probable cause — officer observations insufficient to establish impairment beyond the legal threshold.","Chain of custody issues with blood samples, including improper storage, delayed testing, or use of expired collection kits."}'
WHERE common_charge_slug = 'dui-first-offense' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Missouri''s lifetime lookback means every prior DWI conviction counts — even decades-old convictions elevate the current charge classification.","Mandatory minimum incarceration for prior offenders (10 days), persistent offenders (30 days), chronic offenders (60 days), and habitual offenders (2 years) limits judicial discretion.","Progressive felony classification (Class D for third, Class C for fourth, Class B for fifth+) means the stakes escalate dramatically with each prior.","Prior conviction records from Missouri and other states are readily obtainable and difficult to challenge once authenticated.","Court-ordered substance abuse assessments and treatment compliance records from prior offenses can be used to show a pattern."}',
  defense_opportunities = '{"Challenge the validity of prior convictions — if a prior plea was taken without proper advisement of rights or adequate counsel, it may be subject to collateral attack.","Argue for treatment court or drug court diversion where available, especially for third-offense defendants willing to participate in intensive programs.","Negotiate for lower offense classification by challenging the admissibility of one or more prior convictions."}',
  common_defenses = '{"Invalid prior conviction — prior plea was constitutionally deficient (no counsel, no proper waiver, no factual basis).","All standard DWI defenses apply (improper stop, faulty testing, rising BAC) with heightened importance given felony consequences.","Statute of limitations or jurisdictional issues with older prior convictions used for enhancement."}'
WHERE common_charge_slug = 'dui-repeat-offense' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"No per se drug limit in Missouri means prosecution can rely on officer observations and Drug Recognition Expert (DRE) evaluations to prove impairment.","Toxicology results showing presence of any controlled substance, combined with driving behavior, can establish impairment.","DRE-trained officers provide systematic 12-step evaluations that courts have consistently accepted as reliable evidence."}',
  defense_opportunities = '{"Without a per se drug limit, prosecution must prove actual impairment — mere presence of a substance in the bloodstream is insufficient.","Challenge the DRE officer''s qualifications, training currency, and whether the 12-step evaluation was properly administered and documented.","Metabolites of some drugs (especially marijuana) can remain detectable for weeks after use — presence does not equal impairment at the time of driving.","Prescription medication defense — defendant was taking medication as prescribed at therapeutic levels and was not impaired."}',
  common_defenses = '{"Lack of impairment — drug metabolite presence alone does not prove impairment at the time of driving.","Valid prescription defense — medication taken as prescribed by a physician at therapeutic doses.","Flawed DRE evaluation — officer failed to follow the standardized 12-step drug influence evaluation protocol.","Alternative explanation for observed behavior — fatigue, medical condition, or illness caused symptoms mistaken for drug impairment."}'
WHERE common_charge_slug = 'dui-drugs' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Dashcam, bodycam, and civilian witness video evidence of erratic driving is often compelling and difficult to rebut.","If an accident resulted, the physical evidence (damage patterns, skid marks, scene reconstruction) strongly supports the charge.","Officers can testify to observed driving behavior patterns without needing chemical test evidence."}',
  defense_opportunities = '{"Common plea-down destination from DWI charges — defense can negotiate this lesser charge to avoid DWI consequences on the record.","Class B Misdemeanor classification (no accident) carries relatively light penalties — maximum 6 months, $1,000 fine.","Challenge the subjective nature of ''careless and imprudent'' — the statute requires a judgment call about the defendant''s driving manner.","Emergency circumstances or road conditions may explain the driving behavior without establishing culpable negligence."}',
  common_defenses = '{"Emergency defense — defendant was responding to a medical emergency or avoiding a sudden hazard on the roadway.","Insufficient evidence — officer''s subjective assessment of driving behavior does not meet the statutory standard.","Mechanical failure — vehicle malfunction caused the erratic driving behavior, not driver negligence.","Misidentification — the vehicle or driver identified by witnesses was not the defendant."}'
WHERE common_charge_slug = 'reckless-driving' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Section 577.060 requires stopping, providing information, and rendering aid — failure to do any one of these satisfies the offense elements.","Surveillance cameras, cell phone footage, and vehicle identification technology (paint transfer, debris matching) frequently identify the vehicle.","Physical evidence at the scene (vehicle parts, paint transfer, fluid trails) often leads directly to the defendant''s vehicle.","Witness testimony about a vehicle leaving the scene combined with matching vehicle damage is strong circumstantial evidence."}',
  defense_opportunities = '{"Argue the defendant was unaware that a collision occurred — particularly viable in minor contact situations or noisy traffic conditions.","Demonstrate that the defendant did stop and attempt to provide information but the other party had already left the scene.","Challenge identification evidence — prove the defendant''s vehicle was not the one involved through alibi or forensic analysis.","If the defendant returned to the scene or reported the accident within a reasonable time, this mitigates the failure-to-stop element."}',
  common_defenses = '{"Lack of knowledge — defendant genuinely did not know a collision occurred, especially in cases of minor contact.","Voluntary return — defendant left the scene briefly but returned promptly or reported the accident to law enforcement.","Mistaken identity — the vehicle or driver identified was not the defendant.","Duress or safety — defendant left the scene due to a reasonable fear for personal safety and reported the accident promptly."}'
WHERE common_charge_slug = 'hit-and-run' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Toxicology evidence showing intoxication at the time of a fatal crash is devastating to the defense and typically results in enhanced charges.","Accident reconstruction evidence establishing speed, failure to brake, or other negligent driving behavior is highly technical and persuasive.","Victim impact testimony generates strong emotional weight with juries in vehicular death cases."}',
  defense_opportunities = '{"Challenge the causal link between the defendant''s driving and the death — intervening causes (other driver''s negligence, road defects, mechanical failure) may break causation.","Dispute accident reconstruction methodology, assumptions, and conclusions through competing expert analysis.","If intoxication is not involved, the negligence standard requires proof beyond mere accident — not every fatal crash involves criminal culpability.","Argue comparative fault of the victim or a third party in contributing to the collision."}',
  common_defenses = '{"Intervening cause — another driver, road condition, or mechanical failure was the actual proximate cause of the death.","Lack of criminal negligence — the defendant''s conduct, while unfortunate, did not rise to the level of criminal negligence required by statute.","Accident reconstruction challenge — prosecution''s expert methodology or assumptions are flawed or speculative.","Unavoidable accident — sudden emergency or unforeseeable event made the collision unavoidable regardless of the defendant''s conduct."}'
WHERE common_charge_slug = 'vehicular-homicide' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Section 565.027 (involuntary manslaughter, first degree) covers reckless vehicular deaths and carries up to 15 years as a Class B Felony.","Recklessness can be established through evidence of excessive speed, intoxication, distracted driving, or racing.","Physical evidence from the crash scene (lack of braking, high impact speed, cell phone records showing texting) supports recklessness findings.","Prior traffic violations or warnings about specific dangerous driving behavior can establish awareness of risk."}',
  defense_opportunities = '{"Distinguish between ordinary negligence (civil liability) and criminal recklessness — prosecution must prove conscious disregard of a substantial risk.","Challenge whether the defendant''s conduct constituted recklessness versus ordinary negligence, which is not sufficient for criminal liability.","Mechanical inspection evidence showing vehicle defects that contributed to the collision.","Argue sudden medical emergency (seizure, heart attack, loss of consciousness) negating the mental state element."}',
  common_defenses = '{"Lack of recklessness — defendant''s conduct was negligent but did not rise to the level of conscious disregard of a known risk.","Sudden medical emergency — defendant experienced an unforeseeable medical event that caused loss of vehicle control.","Mechanical failure — vehicle defect (brake failure, tire blowout, steering malfunction) caused the fatal collision.","Contributory negligence of the victim — victim''s own conduct (jaywalking, dark clothing at night, intoxication) substantially caused the death."}'
WHERE common_charge_slug = 'vehicular-manslaughter' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Proof of notice of suspension (certified mail receipt or in-court notification) eliminates the defense of lack of knowledge.","Traffic stop records and officer testimony confirming the defendant was operating a motor vehicle are straightforward to establish."}',
  defense_opportunities = '{"Challenge whether the defendant received actual notice of the suspension — defective service or incorrect address may negate the knowledge element.","Argue the defendant had a reasonable belief their license had been reinstated based on compliance with court orders or payment of fines.","First offense is only a Class D Misdemeanor, creating room for diversion or probation.","If the underlying suspension was for failure to pay fines (rather than safety-related), argue for reduction based on indigency."}',
  common_defenses = '{"Lack of knowledge — defendant was never properly notified of the suspension and had no reason to know the license was suspended.","Necessity — defendant drove due to a genuine emergency involving risk to life or safety.","Invalid underlying suspension — the administrative action that led to the suspension was procedurally defective.","Mistaken identity or unauthorized use of vehicle — defendant was not the person driving."}'
WHERE common_charge_slug = 'driving-on-suspended' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Dashcam and helicopter footage clearly documenting the pursuit is highly compelling evidence.","Endangering public safety during the pursuit (high speed, running red lights, wrong-way driving) escalates the severity.","Officer testimony about activating lights and sirens followed by the defendant''s failure to stop is simple and direct."}',
  defense_opportunities = '{"Argue the defendant did not know it was a law enforcement vehicle — unmarked cars, unclear light bars, or confusing circumstances.","Challenge whether the officer had lawful authority to make the stop in the first place — unlawful stop negates the duty to stop.","Safety defense — defendant was attempting to reach a well-lit, populated area before stopping, particularly viable for late-night stops.","Dispute the duration and nature of the alleged flight — brief hesitation or delayed stop may not constitute fleeing."}',
  common_defenses = '{"Lack of knowledge — defendant did not realize a law enforcement officer was attempting a traffic stop.","Unlawful attempted detention — the underlying stop lacked reasonable suspicion or probable cause.","Safety concerns — defendant was seeking a safe location to stop, not attempting to flee.","Momentary non-compliance — brief delay in stopping does not constitute the crime of fleeing."}'
WHERE common_charge_slug = 'fleeing-eluding' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Physical evidence (drugs seized from defendant''s person, vehicle, or residence) combined with field testing and lab confirmation is strong.","Constructive possession doctrine allows conviction even when drugs are not found directly on the defendant''s person."}',
  defense_opportunities = '{"Challenge the search and seizure — Fourth Amendment violations can result in suppression of all physical evidence.","Constructive possession requires proof of both knowledge and control — mere proximity to drugs is insufficient.","Missouri''s 2014 changes reduced penalties and expanded drug court eligibility, providing diversion opportunities.","Lab testing challenges — field tests have known false positive rates, and chain of custody issues can undermine lab results."}',
  common_defenses = '{"Illegal search and seizure — the drugs were discovered during an unconstitutional search without warrant, consent, or valid exception.","Lack of knowledge — defendant did not know the controlled substance was present, especially in shared spaces or borrowed vehicles.","Lack of possession — defendant did not have actual or constructive control over the substance.","Entrapment — law enforcement induced the defendant to possess drugs they would not have otherwise possessed."}'
WHERE common_charge_slug = 'drug-possession' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Despite Missouri''s 2022 legalization of recreational marijuana (Amendment 3), possession exceeding legal limits remains prosecutable.","Packaging, scales, and large quantities can elevate simple possession to distribution charges.","Odor of marijuana still provides probable cause for investigation in certain circumstances."}',
  defense_opportunities = '{"Missouri Amendment 3 legalized possession of up to 3 ounces for adults 21+ — amounts within this threshold are not criminal.","Medical marijuana cardholders have expanded possession limits under Missouri''s medical program.","Weight disputes — challenge whether the amount actually exceeded the legal possession limit when properly weighed (excluding packaging).","Constitutional challenge to any local ordinance that conflicts with the state''s legalization framework."}',
  common_defenses = '{"Legal possession — amount was within the 3-ounce recreational limit for adults 21+ under Amendment 3.","Medical marijuana authorization — defendant held a valid medical marijuana card with higher possession limits.","Illegal search — the marijuana was discovered during an unconstitutional search, and legalization changes the probable cause analysis.","Weight dispute — the actual amount of usable marijuana was below the criminal threshold when properly measured."}'
WHERE common_charge_slug = 'drug-possession-marijuana' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Lab confirmation of cocaine through chemical analysis is reliable and rarely successfully challenged.","Even trace residue amounts in paraphernalia can support a possession charge in Missouri.","Cocaine''s association with distribution activity often leads to additional investigation and charges."}',
  defense_opportunities = '{"Challenge the legality of the search that produced the cocaine — suppression eliminates the prosecution''s case.","Constructive possession defense in multi-occupant settings — prosecution must link the specific defendant to the drugs.","Challenge field test reliability — cocaine field tests have documented false positive rates with certain legal substances."}',
  common_defenses = '{"Illegal search and seizure — cocaine discovered without a valid warrant, consent, or recognized exception to the warrant requirement.","Lack of knowledge — defendant was unaware of the cocaine''s presence in a shared vehicle, residence, or borrowed item.","Constructive possession failure — prosecution cannot prove defendant had dominion and control over the substance.","Lab analysis error — challenge the testing methodology, chain of custody, or qualifications of the analyst."}'
WHERE common_charge_slug = 'drug-possession-cocaine' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Meth-related paraphernalia (pipes, syringes, chemical precursors) provides strong corroborating evidence of possession and use.","Residue testing on paraphernalia can confirm methamphetamine presence even when no usable quantity is found.","Missouri''s history as a major meth production state means law enforcement is experienced and well-resourced for these cases."}',
  defense_opportunities = '{"Drug court programs in Missouri specifically target methamphetamine offenders, offering treatment-based alternatives to incarceration.","Challenge constructive possession in shared living situations or vehicles — mere presence near meth is insufficient.","Suppress evidence from warrantless searches of vehicles, homes, or persons conducted without proper legal justification.","Argue the substance was not methamphetamine — require full lab confirmation rather than relying on field tests."}',
  common_defenses = '{"Illegal search and seizure — evidence obtained through a warrantless search without a valid exception.","Lack of knowledge — defendant did not know the substance was methamphetamine, particularly in shared-space scenarios.","Constructive possession failure — prosecution cannot establish the defendant''s knowledge of and control over the substance.","Substance misidentification — field tests are unreliable, and lab confirmation is required to prove the substance is methamphetamine."}'
WHERE common_charge_slug = 'drug-possession-meth' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Section 579.065 imposes mandatory minimum sentences for trafficking quantities — 10 years for large amounts, limiting judicial discretion.","Weight thresholds for trafficking are clearly defined, making quantity-based prosecution straightforward once drugs are seized and weighed.","Wiretap evidence, confidential informant testimony, and surveillance operations are commonly used in trafficking cases.","Federal adoption of state trafficking cases brings even harsher mandatory minimums and eliminates parole."}',
  defense_opportunities = '{"Challenge the weight calculation — Missouri law may include or exclude packaging and cutting agents depending on the substance.","Scrutinize confidential informant reliability, motives, and whether the informant received benefits for cooperation.","Challenge wiretap authorization — Missouri requires judicial approval and compliance with strict procedural requirements.","Argue mere presence or association — being near trafficking activity does not establish participation without additional evidence."}',
  common_defenses = '{"Illegal search and seizure — the drugs were seized without a valid warrant or recognized exception.","Entrapment — government agents or informants induced the defendant to participate in trafficking they would not have otherwise engaged in.","Weight challenge — dispute the amount by arguing for exclusion of packaging, cutting agents, or unusable material.","Lack of knowledge — defendant was unaware of the drugs'' presence in a vehicle, package, or shipment they were transporting."}'
WHERE common_charge_slug = 'drug-trafficking' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Section 579.020 covers distribution, delivery, and sale — even giving away drugs qualifies as distribution.","Controlled buy operations using confidential informants with audio/video recording provide strong direct evidence.","Text messages, social media communications, and phone records showing drug transaction discussions are admissible.","Packaging consistent with distribution (individual baggies, scales, large cash amounts) supports intent to distribute."}',
  defense_opportunities = '{"Challenge the reliability of confidential informants — criminal history, pending charges, and financial incentives for cooperation undermine credibility.","Argue personal use — the quantity and packaging were consistent with personal consumption rather than distribution.","Challenge the chain of custody for recorded controlled buys — gaps in recording or handling undermine the evidence.","Entrapment defense where law enforcement initiated and facilitated the transaction."}',
  common_defenses = '{"Entrapment — law enforcement or an informant initiated the idea of distribution and the defendant would not have otherwise engaged in it.","Personal use — the amount possessed was consistent with personal consumption, not distribution.","Unreliable informant — the confidential informant fabricated or exaggerated the transaction for personal benefit.","Illegal search or surveillance — evidence was obtained through unconstitutional means."}'
WHERE common_charge_slug = 'drug-distribution' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Section 579.055 covers manufacturing, producing, or creating controlled substances — possession of precursors with manufacturing intent is sufficient.","Chemical evidence (precursors, solvents, equipment) found at the scene is strong circumstantial evidence of manufacturing activity.","Environmental hazards from manufacturing operations (especially meth labs) generate public safety arguments that influence sentencing.","Co-defendant testimony and cooperating witness statements frequently corroborate physical evidence."}',
  defense_opportunities = '{"Challenge the inference of manufacturing from possession of legal household chemicals — many precursors have legitimate uses.","Argue the defendant was merely present at a location where manufacturing occurred but did not participate in the activity.","Suppress evidence from warrantless entry — law enforcement must have a warrant or valid exception even when they suspect a drug lab.","Challenge expert testimony about the manufacturing process and whether the materials found could actually produce the alleged substance."}',
  common_defenses = '{"Illegal search and seizure — law enforcement entered the premises without a valid warrant or applicable exception.","Lack of participation — defendant was present but did not manufacture, assist, or have knowledge of manufacturing activity.","Innocent possession of materials — chemicals or equipment had legitimate household or industrial purposes.","Insufficient evidence — the materials found were not sufficient to actually manufacture the alleged controlled substance."}'
WHERE common_charge_slug = 'drug-manufacturing' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Section 579.074 covers possession of drug paraphernalia with intent to use — a broad definition that includes common items when drug residue is present.","Residue testing on paraphernalia items confirms prior drug use and connects the item to controlled substance activity.","Proximity of paraphernalia to controlled substances strengthens both the paraphernalia and possession charges.","Officer testimony about the nature of items based on training and experience is typically given significant weight."}',
  defense_opportunities = '{"Challenge whether the item is actually paraphernalia — many items (pipes, containers, scales) have legitimate non-drug uses.","First-offense paraphernalia possession is a Class D Misdemeanor in Missouri, one of the lowest-level offenses.","Argue the item belongs to someone else — in shared living spaces, ownership of a specific item must be established.","Challenge residue testing — trace amounts may be below reliable detection thresholds or cross-contaminated."}',
  common_defenses = '{"Legitimate use — the item has a lawful purpose unrelated to drug use (tobacco pipe, kitchen scale, legitimate container).","Lack of knowledge — defendant did not know the item contained drug residue or was associated with drug activity.","Ownership dispute — the paraphernalia belonged to another person in a shared space.","Illegal search — the paraphernalia was found during an unconstitutional search."}'
WHERE common_charge_slug = 'drug-paraphernalia' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Expert testimony from narcotics officers about distribution indicators (baggies, pay-owe sheets, packaging materials) is highly persuasive.","Text messages or social media evidence showing drug transaction negotiations directly support distribution intent.","Possession of multiple types of drugs or drugs plus firearms strengthens the distribution inference."}',
  defense_opportunities = '{"Challenge the intent inference — argue the quantity and packaging are consistent with personal use rather than distribution.","Suppress illegally obtained evidence — if the search producing the drugs was unlawful, the drugs and all inferred intent evidence are excluded.","Contest expert testimony about distribution indicators — these are opinion-based and can be rebutted with alternative explanations.","Argue that co-defendant or another person was the actual distributor and the defendant was merely a user."}',
  common_defenses = '{"Personal use — the amount, packaging, and circumstances are consistent with personal consumption, not distribution.","Illegal search and seizure — the evidence supporting both possession and intent was obtained unconstitutionally.","Lack of intent — no direct evidence of distribution activity (no sales, no communications, no informant testimony).","Third-party responsibility — another person in the same location was responsible for the distribution indicators."}'
WHERE common_charge_slug = 'drug-possession-with-intent' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Forensic evidence (DNA, ballistics, digital forensics, cell tower data) provides strong physical linkage between defendant and crime.","Missouri retains the death penalty for first-degree murder cases with statutory aggravating factors.","Victim impact evidence is admissible during sentencing and carries significant emotional weight with juries.","Co-defendant testimony through cooperation agreements is a powerful prosecution tool."}',
  defense_opportunities = '{"Challenge the deliberation element — argue the killing was impulsive or occurred in the heat of passion, supporting a lesser charge of second-degree murder or manslaughter.","Challenge forensic evidence methodology — DNA mixture interpretation, fingerprint analysis, and digital evidence extraction methods can be contested.","Alibi defense — establish that the defendant was elsewhere when the crime occurred through independent evidence.","Constitutional challenges to the death penalty during sentencing phase, including intellectual disability or age-related factors."}',
  common_defenses = '{"Lack of deliberation — the killing was not premeditated, supporting conviction on a lesser-included offense.","Mistaken identity — the defendant was not the person who committed the killing.","Alibi — independent evidence establishes the defendant was not at the crime scene."}'
WHERE common_charge_slug = 'murder-first-degree' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Section 565.021 requires only that the defendant knowingly caused death — no deliberation or premeditation needed.","Felony murder provision covers deaths occurring during the commission of any felony, even if the death was unintentional.","Class A Felony carrying 10-30 years or life imprisonment provides substantial leverage for plea negotiations.","Lower mental state requirement (knowingly vs. deliberation) makes the prosecution''s burden easier than first-degree murder."}',
  defense_opportunities = '{"Challenge the ''knowingly'' mental state — argue the defendant did not know their actions would cause death.","In felony murder cases, challenge the underlying felony — if the felony charge fails, the felony murder charge falls.","Self-defense and defense of others under Missouri''s Castle Doctrine provisions."}',
  common_defenses = '{"Lack of intent — defendant did not knowingly cause the death; the death was accidental.","Heat of passion — adequate provocation caused the defendant to act in sudden passion, warranting manslaughter.","Diminished capacity — defendant''s mental state prevented the formation of the required ''knowingly'' intent."}'
WHERE common_charge_slug = 'murder-second-degree' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Section 565.023 still requires proof that the defendant knowingly caused the death, even under the influence of sudden passion.","Prosecution can argue the claimed provocation was insufficient to constitute legally adequate provocation.","Physical evidence of the manner of death (excessive force, multiple wounds) can undermine the heat-of-passion narrative.","Time lapse between provocation and killing — even minutes of delay can defeat the sudden passion defense."}',
  defense_opportunities = '{"This charge itself is often the defense goal — reducing from first- or second-degree murder to manslaughter is a significant win.","Provocation evidence from the victim (threats, assault, infidelity discovered in the moment) supports the sudden passion element.","Sentencing range (Class B Felony, 5-15 years) is significantly lower than first-degree or second-degree murder.","Demonstrate the defendant''s emotional state through witness testimony, 911 calls, and immediate post-incident behavior."}',
  common_defenses = '{"Heat of passion — legally adequate provocation caused the defendant to act in sudden passion before a reasonable cooling period.","Self-defense — the defendant''s use of force was a reasonable response to the victim''s aggression, though excessive force reduced the charge.","Imperfect self-defense — the defendant honestly but unreasonably believed deadly force was necessary.","Diminished capacity due to extreme emotional disturbance at the time of the killing."}'
WHERE common_charge_slug = 'voluntary-manslaughter' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Prosecution does not need to prove intent to kill — only that the defendant''s criminally negligent conduct caused death.","Expert testimony establishing the foreseeability of death from the defendant''s conduct is often available and persuasive.","Victim''s death creates inherent emotional weight that influences jury deliberation."}',
  defense_opportunities = '{"Argue ordinary negligence rather than criminal negligence — the statutory standard requires a ''gross deviation'' from reasonable care.","Challenge causation — intervening factors may have contributed to or caused the death independent of the defendant''s conduct.","Class C Felony (maximum 10 years) is significantly less than murder charges, making this a favorable plea target.","The defendant''s lack of intent to harm is the centerpiece of mitigation arguments."}',
  common_defenses = '{"Ordinary negligence — the defendant''s conduct, while careless, did not constitute the gross deviation required for criminal negligence.","Intervening cause — an independent factor (third party, medical error, victim''s own conduct) was the actual cause of death.","Unforeseeable result — the death was not a reasonably foreseeable consequence of the defendant''s conduct.","Accident — the death resulted from a genuine accident without culpable negligence."}'
WHERE common_charge_slug = 'involuntary-manslaughter' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Medical records documenting the victim''s injuries provide compelling evidence of the severity of the assault.","Witness testimony and surveillance footage frequently capture the assault itself.","Use of a weapon during the assault significantly strengthens the prosecution''s case and elevates the charge."}',
  defense_opportunities = '{"Self-defense under Missouri Castle Doctrine — no duty to retreat in your home, vehicle, or any place you have a right to be.","Argue mutual combat — both parties were willing participants, which can reduce the charge or support self-defense.","Challenge witness identification and credibility, especially in chaotic situations with multiple participants."}',
  common_defenses = '{"Defense of others — defendant was protecting a third party from the victim''s aggression.","Lack of intent to cause serious injury — the degree of injury was unintended and the conduct warrants a lesser charge.","Mutual combat — both parties were willing participants in the altercation."}'
WHERE common_charge_slug = 'aggravated-assault' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Section 565.056 (assault in the fourth degree) covers attempts to cause physical injury, recklessly causing injury, or physical contact knowing the other person would find it offensive.","Even minor injuries or offensive physical contact can support this charge.","Victim and witness testimony is often sufficient without physical evidence of injury.","The broad statutory language captures a wide range of conduct."}',
  defense_opportunities = '{"Class C Misdemeanor classification (maximum 15 days) means minimal criminal exposure and strong negotiating position.","Self-defense applies even to misdemeanor assault charges — the right to protect oneself is not limited to felony situations.","Municipal diversion programs in many Missouri jurisdictions can resolve the charge without a conviction.","Challenge whether the contact was truly offensive or injurious — the threshold for physical contact offenses is subjective."}',
  common_defenses = '{"Self-defense — defendant responded reasonably to a threat or aggression from the other party.","Consent — the physical contact occurred in a context where it was implicitly or explicitly consented to (sports, mutual horseplay).","De minimis contact — the physical contact was too minor to constitute a criminal offense.","Lack of intent — the contact was accidental rather than purposeful or reckless."}'
WHERE common_charge_slug = 'simple-assault' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Physical evidence of the weapon (recovery, DNA, fingerprints) directly links the defendant to the assault.","Victim injuries consistent with weapon use (stab wounds, blunt force patterns) corroborate the weapon''s involvement."}',
  defense_opportunities = '{"Self-defense — the defendant armed themselves in response to a perceived deadly threat from the victim.","Challenge the ''deadly weapon'' classification — argue the object used does not qualify as a deadly weapon under the statutory definition.","Argue the weapon was present but not used in the assault — possession alone does not elevate the charge.","Negotiate plea to simple assault by challenging the weapon element."}',
  common_defenses = '{"Self-defense — defendant used a weapon to defend against a perceived deadly threat.","Not a deadly weapon — the object does not meet the statutory definition of a weapon or instrument that could cause death.","Lack of intent to use the weapon — the weapon was present incidentally and not employed in the assault.","Mutual combat with weapon parity — both parties were armed and willing participants."}'
WHERE common_charge_slug = 'assault-with-deadly-weapon' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Surveillance video from retail establishments and banks commonly captures the robbery in progress.","Victim identification of the perpetrator, combined with recovered stolen property, builds a strong case.","Cell phone location data and getaway vehicle identification provide corroborating evidence."}',
  defense_opportunities = '{"Challenge victim identification — stress during the robbery impairs eyewitness accuracy, especially cross-racial identifications.","Argue the force used was insufficient to elevate theft to robbery — mere snatching without additional force may be theft, not robbery.","Alibi defense supported by independent evidence (surveillance footage elsewhere, electronic records, witness testimony).","Challenge the voluntariness of any confession or statement made during interrogation."}',
  common_defenses = '{"Mistaken identification — the victim incorrectly identified the defendant as the perpetrator.","Insufficient force — the taking did not involve force or threat of force sufficient to constitute robbery.","Alibi — defendant was not present at the scene of the robbery.","Duress — defendant was coerced into participating in the robbery under threat of harm."}'
WHERE common_charge_slug = 'robbery' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Even a fake or unloaded weapon satisfies the statutory element if displayed during the robbery.","Forensic evidence (fingerprints on weapon, DNA, gunshot residue) provides strong physical linkage.","Co-defendant cooperation agreements frequently result in testimony against the defendant."}',
  defense_opportunities = '{"Challenge whether a weapon was actually displayed — if no weapon was seen or recovered, the case may reduce to second-degree robbery.","Identification challenges — armed robberies are traumatic, and witnesses under extreme stress make unreliable identifications.","Argue the defendant was present but not a principal actor — challenge the degree of participation.","Suppression of confession or identification obtained through coercive or suggestive procedures."}',
  common_defenses = '{"Mistaken identification — stress and trauma during an armed robbery significantly impair witness accuracy.","No weapon displayed — the element of a dangerous instrument or weapon was not met.","Coerced confession — statements were obtained through improper interrogation techniques.","Duress — defendant participated under credible threat of serious bodily harm."}'
WHERE common_charge_slug = 'armed-robbery' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Victim testimony about the confinement experience is powerful and emotionally compelling to juries.","Electronic evidence (cell phone tracking, surveillance footage, communication records) frequently establishes the movement and confinement.","Physical evidence at the confinement location (restraints, victim''s belongings, DNA) corroborates the victim''s account."}',
  defense_opportunities = '{"Challenge the ''purpose'' element — Missouri kidnapping requires confinement for a specific prohibited purpose, not just any restraint.","Argue consent — the alleged victim voluntarily accompanied the defendant and was not restrained against their will.","If the movement was incidental to another crime (robbery), argue it was insufficient to constitute separate kidnapping.","Challenge the duration and nature of the confinement — brief or minor restriction may not rise to kidnapping."}',
  common_defenses = '{"Consent — the alleged victim voluntarily went with the defendant and was free to leave.","Incidental to another offense — the brief movement or restraint was part of another crime and does not constitute independent kidnapping.","Lack of prohibited purpose — the confinement was not for ransom, shield, hostage, or any other statutory purpose.","Misidentification — the defendant was not the person who committed the kidnapping."}'
WHERE common_charge_slug = 'kidnapping' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Fire investigation experts can determine the origin and cause of the fire, including the use of accelerants.","Accelerant detection through laboratory analysis of fire debris provides strong physical evidence.","Insurance records, financial motive evidence, and prior threats are commonly used to establish motive."}',
  defense_opportunities = '{"Challenge the fire investigator''s methodology — origin and cause determinations are based on NFPA 921 standards, and deviations undermine conclusions.","Argue accidental cause — electrical fault, natural causes, or unintentional ignition may explain the fire without criminal conduct.","Challenge accelerant detection evidence — certain building materials and consumer products can produce false positives for accelerants.","Alibi defense — establish the defendant was elsewhere when the fire was set."}',
  common_defenses = '{"Accidental fire — the fire was caused by electrical malfunction, natural event, or unintentional human activity.","Flawed investigation — the fire investigator''s methodology did not comply with NFPA 921 standards.","False accelerant positive — building materials or products at the scene produced results mistaken for accelerants.","Alibi — defendant was not present when the fire started."}'
WHERE common_charge_slug = 'arson' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"The victim''s survival allows them to testify directly about the attack, providing powerful firsthand evidence.","Medical evidence of injuries consistent with lethal intent (stab wounds to vital areas, gunshot trajectory) supports the attempt element.","Prior threats, communications, and planning evidence establish premeditation and intent to kill."}',
  defense_opportunities = '{"Challenge the intent to kill — argue the conduct, while violent, was not intended to cause death (assault rather than attempted murder).","Self-defense under Castle Doctrine provisions — defendant responded to an imminent threat with proportionate force.","Argue the injuries, while serious, are inconsistent with a genuine intent to kill.","Voluntary intoxication may negate the specific intent required for attempted murder in Missouri."}',
  common_defenses = '{"Lack of intent to kill — the defendant intended to injure, not kill, warranting a lesser assault charge.","Self-defense — defendant was responding to an imminent deadly threat.","Voluntary intoxication — defendant was too intoxicated to form the specific intent to kill.","Insufficient evidence of a ''substantial step'' toward completing the killing."}'
WHERE common_charge_slug = 'attempted-murder' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Surveillance footage, electronic transaction records, and inventory discrepancies provide clear evidence.","Value thresholds determine classification: over $750 is a Class D Felony, creating significant stakes.","Witness testimony from victims and store employees directly establishes the taking."}',
  defense_opportunities = '{"Challenge the value of the stolen property — under $150 is an infraction, $150-$750 is a Class A Misdemeanor, significantly reducing consequences.","Argue claim of right — the defendant had a good-faith belief they were entitled to the property.","Challenge identification — in retail or crowd settings, proving who took the item can be difficult.","Restitution and diversion programs can resolve theft charges without a conviction in many Missouri jurisdictions."}',
  common_defenses = '{"Claim of right — defendant had a good-faith belief in their entitlement to the property.","Mistaken identity — defendant was not the person who committed the theft.","Lack of intent — the taking was accidental or based on a misunderstanding.","Consent — the owner authorized the defendant to take or use the property."}'
WHERE common_charge_slug = 'theft-larceny' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Financial records, appraisals, and receipts establish the value of stolen property with precision.","Electronic evidence trails (credit card transactions, wire transfers, digital records) link the defendant to the theft.","Pattern evidence showing multiple thefts over time can aggregate values to reach felony thresholds."}',
  defense_opportunities = '{"Challenge the valuation — fair market value disputes can reduce the classification below felony thresholds.","Argue the defendant had authorization or a good-faith claim to the property.","Suppress evidence obtained through illegal searches — financial records and physical evidence may be excludable.","Negotiate restitution in exchange for reduced charges."}',
  common_defenses = '{"Valuation dispute — the property''s fair market value is below the felony threshold of $750.","Claim of right — defendant believed in good faith they were entitled to the property.","Authorization — defendant had permission to take or use the property.","Insufficient evidence — circumstantial evidence does not prove the defendant committed the theft beyond a reasonable doubt."}'
WHERE common_charge_slug = 'grand-theft' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Surveillance footage and store employee testimony typically provide straightforward evidence.","Repeat offenders face enhanced classification — prior stealing convictions elevate even small thefts to misdemeanor or felony level.","Loss prevention officers are trained witnesses who document the theft contemporaneously."}',
  defense_opportunities = '{"First-offense petty theft under $150 is only an infraction in Missouri — no jail time, just a fine.","Diversion programs in many jurisdictions allow first-time shoplifters to avoid a conviction entirely.","Challenge the value — if the item''s value is disputed, the classification may change.","Argue lack of intent — absent-mindedness or distraction, not criminal intent."}',
  common_defenses = '{"Lack of intent — defendant did not intend to steal (forgot to pay, distracted, misunderstanding).","Mistaken identity — defendant was not the person observed taking the item.","Value dispute — the item''s actual value is lower than alleged.","Disproportionate response — first-offense infraction does not warrant aggressive prosecution."}'
WHERE common_charge_slug = 'petty-theft' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Loss prevention officers are trained to observe and document theft — their testimony is specific and detailed.","Store surveillance systems capture the concealment and exit in video evidence.","Receipt comparison with merchandise in the defendant''s possession at exit establishes the taking.","Missouri''s civil recovery statute allows stores to pursue civil damages in addition to criminal charges."}',
  defense_opportunities = '{"First-offense shoplifting under $150 is an infraction — no jail, fine only.","Prosecutor diversion programs specifically designed for shoplifting cases are widely available in Missouri.","Challenge the stop — loss prevention must observe the entire sequence (selection, concealment, passing the point of sale).","Argue the defendant intended to pay and had not yet left the store."}',
  common_defenses = '{"Intent to pay — defendant had not yet passed the last point of sale and intended to purchase the item.","Lack of concealment — carrying an item openly in the store is not theft.","Incomplete observation — loss prevention did not observe the entire sequence required to establish theft.","Absent-mindedness — defendant forgot the item was in their cart, bag, or hand."}'
WHERE common_charge_slug = 'shoplifting' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Physical evidence of forced entry (tool marks, broken locks, damaged frames) establishes unauthorized entry.","Forensic evidence (fingerprints, DNA, shoe prints) at the point of entry links the defendant to the scene.","Surveillance footage and alarm system records document the timing and manner of entry."}',
  defense_opportunities = '{"Challenge the intent element — entry into a building without proof of intent to commit a crime inside is trespassing, not burglary.","Argue authorized entry — the defendant had permission or believed they had permission to enter the building.","Challenge forensic evidence — fingerprints or DNA at a scene the defendant had legitimate access to does not prove burglary.","Lack of forced entry raises questions about whether entry was truly unauthorized."}',
  common_defenses = '{"No intent to commit a crime — defendant entered the building for a non-criminal purpose.","Authorized entry — defendant had actual or apparent permission to be in the building.","Mistaken identity — forensic evidence does not conclusively identify the defendant as the person who entered.","Insufficient evidence — circumstantial evidence does not eliminate reasonable alternative explanations."}'
WHERE common_charge_slug = 'burglary' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Victims can testify about their experience, including confrontations with the intruder, which is emotionally compelling.","Physical evidence of entry plus stolen property found in the defendant''s possession creates a strong circumstantial case.","Home security camera footage and doorbell cameras increasingly capture the burglar''s identity."}',
  defense_opportunities = '{"Challenge identification — if the burglar was masked or the footage is poor quality, identity is the primary disputed issue.","Argue the dwelling was not inhabited or the defendant believed it was abandoned — this may affect the charge classification.","Suppress evidence from illegal searches of the defendant''s home or vehicle where stolen property was found.","Challenge the timeline — establish an alibi for the time the burglary occurred."}',
  common_defenses = '{"Mistaken identity — the defendant was not the person who entered the residence.","Alibi — defendant can establish they were elsewhere during the time of the burglary.","Consent or authority — defendant had permission to enter from a co-occupant.","No intent — defendant entered without intent to commit a crime (e.g., looking for someone, intoxicated confusion about address)."}'
WHERE common_charge_slug = 'residential-burglary' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Vehicle identification (VIN, registration, GPS tracking) makes identifying the stolen vehicle straightforward.","Being found in possession of a recently stolen vehicle creates a strong presumption of knowledge.","Surveillance footage from parking lots, traffic cameras, and toll systems tracks vehicle movement."}',
  defense_opportunities = '{"Argue the defendant had permission from the owner or reasonably believed they had permission to use the vehicle.","Challenge the ''taking'' element — if the defendant was a passenger, mere presence in a stolen vehicle is not theft.","Joyriding or unauthorized use (temporary taking with intent to return) may warrant a lesser charge.","Challenge identification — prove the defendant was not the person who took the vehicle."}',
  common_defenses = '{"Permission — defendant believed they had the owner''s authorization to use the vehicle.","Mistaken identity — defendant was not the person who stole the vehicle.","Lack of knowledge — defendant did not know the vehicle was stolen (purchased from third party, borrowed).","Temporary use — defendant intended to return the vehicle, negating the permanent deprivation element."}'
WHERE common_charge_slug = 'motor-vehicle-theft' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Circumstances of acquisition (price far below market value, no documentation, suspicious seller) support knowledge inference.","Serial numbers, ownership documentation, and victim identification of the property establish the stolen status.","Electronic records (marketplace listings, text messages) can show the defendant knew or should have known the property was stolen."}',
  defense_opportunities = '{"Challenge the knowledge element — the defendant genuinely did not know the property was stolen.","Argue the property was purchased in good faith at a price that, while favorable, was not suspiciously low.","Challenge whether the property was actually stolen — ownership disputes do not make property ''stolen.''","Lack of proof that the property in the defendant''s possession is the specific stolen property."}',
  common_defenses = '{"Lack of knowledge — defendant had no reason to believe the property was stolen and purchased in good faith.","Ownership dispute — the property''s ''stolen'' status is contested between parties with competing claims.","Misidentification of property — the item in defendant''s possession is not the same item reported stolen.","Innocent receipt — defendant received the property as a gift or through a legitimate transaction."}'
WHERE common_charge_slug = 'receiving-stolen-property' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Surveillance footage, witness testimony, and physical evidence (paint, tools, DNA) at the damage site link the defendant.","Damage estimates from repair professionals establish the financial impact and determine charge classification.","Social media posts or communications where the defendant discusses or boasts about the damage are admissible."}',
  defense_opportunities = '{"Challenge the value of damage — under $750 is a Class B Misdemeanor, over $750 is a Class D Felony.","Argue the damage was accidental — the defendant did not ''knowingly'' damage the property.","Claim of right — argue the defendant believed they had a right to alter or damage their own property.","Restitution-based resolution — paying for repairs often leads to reduced or dismissed charges."}',
  common_defenses = '{"Accident — the damage was not intentional or knowing; it occurred through inadvertence.","Claim of ownership — defendant believed the property was theirs to alter or damage.","Mistaken identity — defendant was not the person who caused the damage.","Consent — property owner authorized the alteration or removal."}'
WHERE common_charge_slug = 'vandalism' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Posted signs, fences, and verbal warnings to leave provide clear evidence of the property''s off-limits status.","Surveillance footage and witness testimony showing the defendant on the property are straightforward evidence.","Prior trespass warnings to the same defendant elevate the offense and establish knowledge."}',
  defense_opportunities = '{"First-degree trespass is only a Class B Misdemeanor (6 months maximum), providing substantial room for alternative resolutions.","Argue the defendant did not know they were on private property or believed they had permission to be there.","Challenge whether proper notice was given — no-trespassing signs must be posted or the defendant must have been personally warned.","Assert a legal right to be on the property (easement, implied invitation, public access)."}',
  common_defenses = '{"Lack of knowledge — defendant did not realize they were on private property or that entry was prohibited.","Permission or implied invitation — defendant reasonably believed they were authorized to be on the property.","Public access — the property was held open to the public or the defendant was on a public easement.","Necessity — defendant entered the property due to an emergency requiring immediate access."}'
WHERE common_charge_slug = 'trespassing' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Evidence of the specific act (cutting wires, puncturing tires, contaminating substances) clearly demonstrates intent.","Motive evidence from disputes, grudges, or retaliation provides context for the jury.","Multiple incidents in a pattern strengthen the prosecution''s case and may support enhanced charges."}',
  defense_opportunities = '{"Challenge the knowledge element — argue the damage or tampering was accidental or unintentional.","Argue the property was the defendant''s own — co-owned property disputes do not always constitute criminal mischief.","First-offense misdemeanor classification provides room for diversion or alternative sentencing.","Restitution agreement can support negotiated resolution."}',
  common_defenses = '{"Accident — the damage or alteration was not intentional.","Ownership claim — defendant believed they had a right to alter or modify the property.","Lack of knowledge — defendant did not know their actions would cause damage.","Consent — the property owner authorized the conduct that resulted in the damage."}'
WHERE common_charge_slug = 'criminal-mischief' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Victim statements to responding officers (excited utterance exception) are admissible even if the victim later recants.","Physical evidence (injuries, damaged property, 911 recording) corroborates the victim''s initial account.","Missouri''s mandatory arrest policy for probable cause domestic violence means officers must make an arrest, ensuring the case enters the system."}',
  defense_opportunities = '{"Self-defense — the defendant was the one being attacked and acted to protect themselves.","Recantation or inconsistent statements by the complaining witness can create reasonable doubt, though prosecutors may proceed without victim cooperation.","Argue mutual combat — both parties were aggressors, and the evidence does not establish a clear primary aggressor."}',
  common_defenses = '{"Self-defense — defendant was responding to physical aggression from the other party.","False accusation — the allegation was fabricated in connection with a custody dispute, divorce, or personal vendetta.","Lack of physical evidence — no injuries, no property damage, and no corroborating witnesses support the allegation.","Mutual combat — both parties were aggressors and the defendant was wrongly identified as the primary aggressor."}'
WHERE common_charge_slug = 'domestic-violence' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Even minor physical contact (pushing, grabbing, slapping) satisfies the offense element when it occurs in a domestic context.","Bodycam footage of the scene, victim''s emotional state, and any visible injuries provide immediate evidence.","Prior domestic violence incidents and protective order history are sometimes admissible to show pattern."}',
  defense_opportunities = '{"Class A Misdemeanor (first offense) means maximum 1 year — room for diversion and alternative resolution.","Self-defense — the defendant was the victim of the initial aggression.","Challenge the ''offensive contact'' threshold — incidental or reflexive contact during an argument may not meet the statutory standard.","Negotiate for anger management or counseling programs in lieu of criminal conviction."}',
  common_defenses = '{"Self-defense — defendant acted to protect themselves from the other party''s physical aggression.","Accidental contact — the physical contact was incidental during an argument, not purposeful.","False allegation — the accusation was motivated by a custody battle, financial dispute, or personal conflict.","De minimis contact — the physical contact was so minor it does not warrant criminal prosecution."}'
WHERE common_charge_slug = 'domestic-battery' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Testimony from mandated reporters (teachers, doctors, social workers) who observed the child''s condition is credible and specific.","Environmental evidence (unsafe living conditions, drugs in the home, lack of supervision) documents the endangerment.","Children''s statements to forensic interviewers, while hearsay, may be admissible under specific exceptions."}',
  defense_opportunities = '{"Challenge the ''substantial risk'' standard — the prosecution must prove actual substantial risk, not merely imperfect parenting.","Cultural or lifestyle differences in parenting approaches should not be criminalized absent actual danger to the child.","Argue the conditions were temporary and the defendant was actively addressing the situation.","Constitutional parental rights arguments limit state interference in child-rearing decisions."}',
  common_defenses = '{"No substantial risk — the conditions, while not ideal, did not create a substantial risk to the child''s welfare.","Lack of knowledge — defendant was unaware of the dangerous condition affecting the child.","Temporary situation — the circumstance was brief and the defendant took corrective action.","Alternative explanation — the child''s condition was caused by a medical issue, another caretaker, or an accident."}'
WHERE common_charge_slug = 'child-endangerment' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Medical evidence (fractures, bruising patterns inconsistent with accidental injury, old injuries) is highly persuasive.","Expert pediatric testimony about injury patterns distinguishes accidental from inflicted injuries.","The child victim''s statements to forensic interviewers and medical providers are often admissible as hearsay exceptions."}',
  defense_opportunities = '{"Challenge the medical evidence — argue injuries are consistent with accidental causes (falls, rough play, medical conditions).","Identify the actual perpetrator — if the child was in the care of others, the defendant may not be the person who caused the injuries.","Discipline defense — reasonable physical discipline is not criminal abuse under Missouri law, though it must not cause injury.","Medical condition defense — certain medical conditions (osteogenesis imperfecta, bleeding disorders) can mimic abuse injuries."}',
  common_defenses = '{"Accidental injury — the child''s injuries resulted from a fall, accident, or normal childhood activity.","Alternative perpetrator — another caretaker, not the defendant, caused the injuries.","Reasonable discipline — the physical contact was reasonable parental discipline that did not cross into abuse.","Medical condition — a pre-existing condition caused or contributed to the appearance of the injuries."}'
WHERE common_charge_slug = 'child-abuse' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"The protective order itself establishes the prohibited conduct — the defendant knew what they were not allowed to do.","Electronic evidence (phone records, text messages, GPS data, social media contact) frequently proves the violation.","Police reports from protective order service confirm the defendant was properly served and aware of the order''s terms."}',
  defense_opportunities = '{"Challenge service of the order — if the defendant was never properly served, they cannot be held to have knowingly violated it.","Argue the contact was initiated by the protected party — the petitioner invited or initiated the contact.","Challenge the scope of the order — the defendant''s conduct may not fall within the specific prohibitions of the order as written.","Constitutional challenges to overbroad order provisions that restrict protected activity."}',
  common_defenses = '{"Improper service — defendant was never properly served with the protective order and did not know its terms.","Contact initiated by protected party — the person protected by the order invited or initiated the communication.","Conduct outside order scope — the defendant''s actions did not violate the specific terms of the order.","Accidental or unavoidable contact — the encounter was unplanned and the defendant left immediately upon realizing the protected party was present."}'
WHERE common_charge_slug = 'violation-protective-order' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Pattern evidence from multiple contacts, appearances, and communications establishes the course of conduct element.","Electronic evidence (text messages, emails, social media, GPS tracking) creates a detailed record of the stalking behavior.","Victim testimony about the psychological impact and fear created by the defendant''s conduct is compelling."}',
  defense_opportunities = '{"Challenge the ''course of conduct'' element — isolated incidents may not constitute the pattern required by statute.","Argue the conduct was constitutionally protected activity (free speech, peaceful protest, legitimate business contact).","Challenge the ''reasonable person'' standard — argue the victim''s fear was not objectively reasonable given the actual conduct.","Demonstrate the contact was for a legitimate purpose (co-parenting, business, shared social circles)."}',
  common_defenses = '{"Constitutionally protected activity — the defendant''s conduct was lawful speech, petition, or assembly.","No course of conduct — isolated incidents do not meet the pattern requirement for stalking.","Legitimate purpose — the contacts were for co-parenting, business, or other lawful reasons.","Unreasonable fear — a reasonable person would not have felt fear from the defendant''s actual conduct."}'
WHERE common_charge_slug = 'stalking' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Electronic communication records (texts, calls, emails, social media messages) provide documented evidence of the pattern.","Multiple witnesses to harassing behavior corroborate the victim''s account.","Prior warnings or requests to stop communication establish the defendant''s awareness."}',
  defense_opportunities = '{"Class A Misdemeanor classification provides room for diversion programs and alternative resolutions.","Argue the communications had a legitimate purpose (debt collection, co-parenting, business dispute).","Free speech defense — the communications were protected expression, not harassment.","Challenge the ''repeated'' element — a few contacts may not constitute the pattern required."}',
  common_defenses = '{"Legitimate purpose — the communications were for a lawful reason (business, co-parenting, debt).","Protected speech — the communications were constitutionally protected expression.","Not repeated — the number of contacts does not constitute a pattern of harassment.","Mutual communication — both parties were actively communicating, negating the one-sided harassment claim."}'
WHERE common_charge_slug = 'harassment' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Medical evidence of the elderly victim''s injuries, neglect, or exploitation is documented and compelling.","Financial records showing exploitation (unauthorized withdrawals, forged signatures, changed beneficiaries) create clear paper trails.","Testimony from healthcare providers, social workers, and Adult Protective Services investigators is credible."}',
  defense_opportunities = '{"Challenge the causal relationship — the elderly person''s injuries may result from falls, medical conditions, or medication side effects.","Argue the financial transactions were authorized by the elderly person when they had capacity.","Distinguish between imperfect caregiving and criminal abuse — not all substandard care constitutes a crime.","Power of attorney or guardianship authorization for financial decisions the prosecution characterizes as exploitation."}',
  common_defenses = '{"Authorized conduct — the elderly person authorized the financial transactions or care decisions.","Medical explanation — the victim''s injuries are consistent with falls, medical fragility, or medication effects.","Lack of intent — defendant did not knowingly cause injury or exploitation.","Caregiver defense — defendant was providing the best care possible with available resources."}'
WHERE common_charge_slug = 'elder-abuse' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Physical recovery of the weapon from the defendant''s person, vehicle, or residence provides direct evidence.","Witness testimony about the defendant displaying or using the weapon, combined with physical evidence, is strong.","Location-based violations (schools, government buildings, bars while intoxicated) are straightforward to prove."}',
  defense_opportunities = '{"Missouri is a constitutional carry state — most adults can carry concealed weapons without a permit since 2017.","Second Amendment constitutional challenges to specific restrictions.","Argue the defendant was unaware of the weapon''s presence (borrowed vehicle, another person''s belongings)."}',
  common_defenses = '{"Constitutional carry — Missouri permits concealed carry without a permit for qualifying adults.","No prohibited status — defendant is not in a category prohibited from possessing the weapon.","Lack of knowledge — defendant was unaware the weapon was present.","Lawful purpose — the weapon possession was for a constitutionally protected purpose."}'
WHERE common_charge_slug = 'weapons-possession' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"The prior felony conviction is a documented fact — certified court records establish this element conclusively.","Physical recovery of the firearm combined with fingerprints, DNA, or witness testimony links the weapon to the defendant.","Constructive possession (weapon found in defendant''s residence, vehicle, or area of control) can be sufficient."}',
  defense_opportunities = '{"Challenge constructive possession — in multi-person residences or vehicles, linking the specific defendant to the weapon requires more than proximity.","Argue the defendant did not know the firearm was present — especially viable when the weapon was found in a shared space.","Challenge the underlying felony conviction if it was constitutionally deficient (no counsel, defective plea).","Temporary, innocent possession (finding and turning in a weapon) may negate criminal intent."}',
  common_defenses = '{"Lack of possession — defendant did not actually or constructively possess the firearm.","Lack of knowledge — defendant was unaware the firearm was in their vehicle, home, or area of control.","Invalid predicate felony — the underlying felony conviction was constitutionally deficient.","Innocent possession — defendant temporarily possessed the weapon for a lawful purpose (finding and surrendering it)."}'
WHERE common_charge_slug = 'felon-in-possession' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Physical recovery of the concealed weapon and evidence of the prohibited circumstance (intoxication, restricted location) is straightforward.","Officer testimony about discovering the concealed weapon during a lawful encounter is direct evidence.","Video evidence from location security cameras (government buildings, schools) establishes the restricted-zone element."}',
  defense_opportunities = '{"Missouri''s constitutional carry (2017) dramatically narrowed the circumstances under which concealed carry is criminal.","Argue the defendant was not aware they were in a restricted area.","Challenge whether the defendant was actually ''intoxicated'' if that''s the basis for the charge."}',
  common_defenses = '{"Lawful carry — defendant was carrying in a manner and location permitted under Missouri''s constitutional carry law.","Lack of knowledge — defendant was unaware they had entered a restricted zone.","Not intoxicated — defendant''s BAC or impairment level did not meet the threshold for ''intoxicated'' under the statute.","Improper stop — the discovery of the weapon resulted from an unlawful detention or search."}'
WHERE common_charge_slug = 'concealed-carry-violation' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Physical evidence (shell casings, bullet impacts, gunshot residue on the defendant) links the defendant to the discharge.","Witness testimony and surveillance footage capturing the discharge are strong direct evidence.","Ballistic comparison of recovered projectiles to the defendant''s firearm provides forensic linkage."}',
  defense_opportunities = '{"Self-defense — the discharge was in response to an imminent deadly threat.","Lawful discharge — the shooting occurred on private property for legitimate purposes (target practice, pest control) in compliance with local ordinances.","Accidental discharge — the weapon fired unintentionally due to a mechanical malfunction or accidental trigger pull.","Challenge identification — prove the defendant was not the person who discharged the weapon."}',
  common_defenses = '{"Self-defense — discharge was necessary to prevent imminent death or serious injury.","Accidental discharge — the weapon fired unintentionally.","Lawful discharge — occurred on private property for a legitimate purpose.","Misidentification — defendant was not the person who fired the weapon."}'
WHERE common_charge_slug = 'illegal-discharge' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Digital evidence trails (IP addresses, account access logs, transaction records) trace the fraudulent activity to the defendant.","Financial records showing unauthorized transactions using the victim''s identity are clear and compelling.","Victim testimony about the impact of the identity theft is emotionally powerful and establishes the harm."}',
  defense_opportunities = '{"Challenge digital evidence attribution — IP addresses and device identifiers can be spoofed or shared among multiple users.","Argue the defendant had authorization from the identity holder to use their information.","Challenge the chain of custody for digital evidence — improper handling may compromise authenticity.","Argue mistaken identity — someone else used the defendant''s device or network to commit the fraud."}',
  common_defenses = '{"Authorization — defendant had permission from the identity holder to use their personal information.","Mistaken attribution — another person used the defendant''s device, network, or account.","Lack of knowledge — defendant did not know the information they used belonged to another person.","Insufficient evidence — digital evidence does not conclusively link the defendant to the fraudulent activity."}'
WHERE common_charge_slug = 'identity-theft' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Financial records (bank statements, accounting ledgers, audit reports) provide detailed evidence of the misappropriation.","Forensic accounting analysis can trace the flow of funds and identify unauthorized transactions with precision.","Witnesses from the organization (supervisors, accountants, auditors) testify about the defendant''s access and the missing funds."}',
  defense_opportunities = '{"Argue the defendant had authorization for the transactions — business expense, bonus, or informal compensation arrangement.","Challenge the forensic accounting methodology — accounting errors and legitimate business expenses can be mischaracterized.","Argue lack of intent to permanently deprive — the defendant intended to repay or was borrowing against future compensation.","Challenge the valuation — dispute the amount allegedly embezzled to reduce the charge classification."}',
  common_defenses = '{"Authorization — defendant believed the transactions were authorized as part of their compensation or business expenses.","Accounting error — the apparent shortfall is due to accounting mistakes, not criminal conduct.","Intent to repay — defendant intended to return the funds and did not intend permanent deprivation.","Third-party responsibility — another person with access to the accounts committed the misappropriation."}'
WHERE common_charge_slug = 'embezzlement' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Document examination experts can identify forged signatures, alterations, and fabricated documents.","Comparison of the forged document with the defendant''s known handwriting or printing provides forensic evidence.","The forged document itself is the primary evidence — its existence and use in a transaction are straightforward to prove."}',
  defense_opportunities = '{"Argue the defendant had authorization to sign on behalf of the other person (power of attorney, agency relationship).","Challenge the document examiner''s methodology and conclusions — handwriting analysis has known limitations.","Argue lack of intent to defraud — the document was created for a non-fraudulent purpose.","Identity defense — the defendant was not the person who created the forged document."}',
  common_defenses = '{"Authorization — defendant had permission to sign or execute the document on the other person''s behalf.","Lack of fraudulent intent — the document was not created or used with intent to defraud.","Misidentification of author — defendant did not create or alter the document.","Flawed analysis — the document examiner''s opinion is unreliable or inconclusive."}'
WHERE common_charge_slug = 'forgery' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Physical evidence of counterfeiting materials (printers, paper, templates, ink) at the defendant''s location is strong.","Secret Service and forensic analysis of counterfeit bills or documents identifies the production method.","Passing counterfeit currency or instruments to unsuspecting victims is documented through victim testimony and surveillance."}',
  defense_opportunities = '{"Argue the defendant did not know the currency or instrument was counterfeit when they possessed or passed it.","Challenge the search that discovered counterfeiting materials — suppress evidence obtained without a warrant.","Argue the materials found were for legitimate purposes (art, film props, educational display).","Distinguish between possession and production — merely having a counterfeit bill is different from manufacturing."}',
  common_defenses = '{"Lack of knowledge — defendant did not know the item was counterfeit.","Legitimate purpose — materials were for art, props, or educational use, not fraud.","Illegal search — counterfeiting materials were found during an unconstitutional search.","No intent to defraud — defendant had no plan to pass counterfeit items as genuine."}'
WHERE common_charge_slug = 'counterfeiting' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Bank records showing the account balance at the time the check was written provide documentary proof of insufficient funds.","The check itself, endorsed and deposited by the payee, is physical evidence of the transaction.","Notice of dishonor sent to the defendant and failure to make good within 10 days creates a presumption of knowledge."}',
  defense_opportunities = '{"Argue the defendant had a good-faith belief that sufficient funds were available (pending deposit, expected transfer).","Challenge the timing — if the defendant deposited funds to cover the check before it was presented, the knowledge element fails.","Argue the check was post-dated and the payee was aware it was not to be immediately deposited."}',
  common_defenses = '{"Good faith belief — defendant reasonably believed sufficient funds were in the account.","Timely restitution — defendant made good on the check within the statutory 10-day period after notice.","Post-dated check — the payee knew the check was not to be immediately deposited.","Bank error — a bank processing error caused the insufficient funds, not the defendant''s knowledge."}'
WHERE common_charge_slug = 'bad-checks' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Insurance company special investigation units compile comprehensive evidence packages before referring cases for prosecution.","Surveillance footage, social media activity, and medical record inconsistencies contradict the claimed loss or injury.","Expert testimony from insurance investigators and medical professionals undermines the legitimacy of the claim."}',
  defense_opportunities = '{"Challenge the fraud allegation — argue the claim was legitimate and any discrepancies are innocent mistakes or differences of opinion.","Argue the defendant relied on advice from professionals (doctors, adjusters, attorneys) in making the claim.","Challenge surveillance evidence context — selective footage can be misleading about the claimant''s actual condition.","Dispute the insurer''s valuation — disagreement about claim value is not fraud."}',
  common_defenses = '{"Legitimate claim — the insurance claim was genuine and any discrepancies are innocent errors.","Reliance on professional advice — defendant followed guidance from medical providers or advisors in filing the claim.","Lack of intent to defraud — defendant believed the claim was accurate and truthful.","Valuation dispute — disagreement about the value of a loss is a civil matter, not criminal fraud."}'
WHERE common_charge_slug = 'insurance-fraud' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Electronic transaction records trace each fraudulent charge to a specific time, location, and device.","Surveillance footage at point-of-sale locations captures the person making fraudulent purchases.","Digital forensic analysis of devices found in the defendant''s possession can reveal stored card information."}',
  defense_opportunities = '{"Challenge the identification of the person making the transactions — the defendant may not be the user of the card.","Argue authorization — the cardholder gave the defendant permission to use the card.","Challenge digital evidence attribution — devices containing card data may have been accessible to multiple people.","Argue identity theft — the defendant''s identity was used by someone else to commit the fraud."}',
  common_defenses = '{"Authorization — defendant had the cardholder''s permission to use the card for the transactions.","Mistaken identity — defendant was not the person who made the fraudulent transactions.","Lack of knowledge — defendant did not know the card was stolen, expired, or unauthorized.","Third-party perpetrator — another person used the defendant''s device or account to commit the fraud."}'
WHERE common_charge_slug = 'credit-card-fraud' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Financial records, bank records, and transaction analysis provide detailed documentary evidence.","Structuring transactions to avoid reporting requirements (under $10,000) creates additional charges and evidence of knowledge.","Federal-state cooperation brings substantial investigative resources (FBI, IRS, FinCEN) to these cases."}',
  defense_opportunities = '{"Challenge the predicate offense — money laundering requires proof that the funds came from criminal activity.","Argue the defendant did not know the funds were proceeds of criminal activity.","Challenge the financial analysis methodology — complex financial transactions can have innocent explanations.","Argue legitimate business transactions that incidentally involved funds with a criminal origin unknown to the defendant."}',
  common_defenses = '{"Lack of knowledge — defendant did not know the funds were derived from criminal activity.","Legitimate source — the funds came from lawful business activities, not criminal proceeds.","No predicate offense — the prosecution cannot prove the underlying crime that generated the allegedly laundered funds.","Good faith reliance — defendant relied on professional advice (attorneys, accountants) regarding the transactions."}'
WHERE common_charge_slug = 'money-laundering' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Documentary evidence (contracts, communications, financial records) typically provides a clear picture of the fraudulent scheme.","Victim testimony about reliance on the defendant''s misrepresentations establishes the deception and damages.","Pattern evidence showing multiple victims or repeated fraudulent conduct strengthens the case."}',
  defense_opportunities = '{"Challenge the intent element — argue the defendant made good-faith representations that turned out to be inaccurate.","Argue the representations were opinions or puffery, not actionable misstatements of fact.","Challenge the reliance element — argue the victim did not actually rely on the defendant''s statements.","Argue civil dispute — a failed business deal or broken promise is a contract dispute, not criminal fraud."}',
  common_defenses = '{"Good faith — defendant genuinely believed their representations were true at the time.","Civil dispute — the matter is a business disagreement, not criminal fraud.","No reliance — the alleged victim did not actually rely on the defendant''s representations.","Lack of intent to defraud — defendant did not intend to deceive or obtain property through misrepresentation."}'
WHERE common_charge_slug = 'fraud-general' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"DNA evidence from sexual assault kits provides strong forensic identification linking the defendant to the offense.","Victim testimony, particularly when consistent with physical evidence and medical findings, is compelling.","SANE (Sexual Assault Nurse Examiner) documentation of injuries consistent with non-consensual contact supports the victim''s account."}',
  defense_opportunities = '{"Consent defense — argue the sexual contact was consensual between the parties.","Challenge DNA evidence interpretation — the presence of DNA proves contact but not the circumstances of that contact.","Challenge the victim''s credibility through prior inconsistent statements, motive to fabricate, or timeline inconsistencies.","Alibi defense — establish the defendant was not present during the alleged assault."}',
  common_defenses = '{"Consent — the sexual contact was consensual.","Mistaken identity — the defendant was not the perpetrator, and DNA or identification evidence is challenged.","False allegation — the accusation was fabricated for personal motives (revenge, custody, attention).","Alibi — defendant was not at the location of the alleged assault."}'
WHERE common_charge_slug = 'sexual-assault' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"DNA evidence and SANE exam findings provide powerful forensic support for the victim''s account.","Missouri allows expert testimony on rape trauma syndrome to explain victim behavior that might otherwise seem inconsistent."}',
  defense_opportunities = '{"Challenge the consent element — if consent is the defense, focus on communications, behavior patterns, and context before and after the encounter.","Challenge the forensic evidence — DNA presence alone does not establish non-consent.","Scrutinize delayed reporting and inconsistencies in the victim''s account, while respecting that delayed reporting is common."}',
  common_defenses = '{"Consent — the sexual act was consensual.","Misidentification — defendant was not the person who committed the assault.","False accusation — the allegation is fabricated or exaggerated.","Insufficient evidence — the prosecution cannot prove beyond a reasonable doubt that force or incapacity was involved."}'
WHERE common_charge_slug = 'rape' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Victim and witness testimony describing the exposure is often sufficient without physical evidence.","Surveillance footage or photographs capturing the exposure provide definitive evidence.","Repeat offenses elevate to felony status and may trigger sex offender registration."}',
  defense_opportunities = '{"First offense is only a Class B Misdemeanor — maximum 6 months, with diversion possibilities.","Argue the exposure was not ''knowing'' — accidental wardrobe malfunctions, bathroom emergencies, or medical conditions.","Challenge whether the circumstances were ''likely to cause alarm'' — context matters (nudist area, private property visible from distance).","Argue the exposure was not of genitals — the statute specifically requires genital exposure."}',
  common_defenses = '{"Accidental exposure — the exposure was unintentional (wardrobe malfunction, medical necessity).","Not likely to cause alarm — the circumstances did not objectively warrant alarm.","Privacy expectation — the exposure occurred in a context where the defendant expected privacy.","Misidentification — the defendant was not the person who committed the exposure."}'
WHERE common_charge_slug = 'indecent-exposure' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Undercover operations with audio/video recordings capture the solicitation directly.","Text messages, online communications, and payment records documenting the agreement are admissible.","Sting operation details including the specific agreement and exchange of money provide clear evidence."}',
  defense_opportunities = '{"Entrapment defense — law enforcement initiated the transaction and the defendant was not predisposed to commit the offense.","Challenge whether a specific agreement for sexual services in exchange for money was actually reached.","Class B Misdemeanor (first offense) means minimal criminal exposure and diversion may be available.","Challenge the recording quality and interpretation of conversations during sting operations."}',
  common_defenses = '{"Entrapment — law enforcement created the opportunity and persuaded the defendant to commit a crime they were not predisposed to.","No agreement — the conversation did not result in a specific agreement for sexual services in exchange for money.","Misunderstanding — the defendant was seeking companionship or a date, not sexual services for pay.","Constitutionality challenge — challenge to the criminalization of consensual adult sexual conduct."}'
WHERE common_charge_slug = 'solicitation-prostitution' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Digital forensic analysis recovers deleted files, internet history, and metadata linking the material to the defendant.","IP address tracking and internet service provider records identify the subscriber accessing the material.","Federal-state cooperation brings FBI resources and the National Center for Missing and Exploited Children (NCMEC) database."}',
  defense_opportunities = '{"Challenge the search warrant for the defendant''s devices — suppression eliminates the core evidence.","Argue the defendant did not knowingly possess the material — automatic downloads, malware, or shared networks may have placed it on the device.","Challenge IP address attribution — multiple devices and users may share an IP address.","Age of depicted individuals — argue the prosecution has not established that the depicted individuals are actually minors."}',
  common_defenses = '{"Unknowing possession — material was downloaded automatically by malware, shared network, or another user of the device.","Illegal search — the warrant was defective or the search exceeded the warrant''s scope.","IP attribution error — the IP address traces to the network, not specifically to the defendant or their device.","Not a minor — the prosecution has not proven the depicted individual is under 18."}'
WHERE common_charge_slug = 'child-exploitation' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Registration records documenting the defendant''s obligation and failure to comply are straightforward evidence.","Address verification by law enforcement confirms the defendant is not residing at their registered address.","The registration requirement itself and proof of notification to the defendant are easily established through official records."}',
  defense_opportunities = '{"Argue the defendant attempted to register but was turned away or encountered administrative obstacles.","Challenge whether proper notification of registration requirements was provided after the predicate offense.","Argue impossibility — homelessness, travel, or other circumstances made registration at a fixed address impossible.","Challenge the underlying conviction requiring registration if it can be overturned."}',
  common_defenses = '{"Attempted compliance — defendant tried to register but was prevented by administrative error or obstacles.","Lack of notice — defendant was not properly informed of the registration requirement or its terms.","Impossibility — circumstances (homelessness, transient status) made compliance impossible.","Invalid predicate — the conviction requiring registration has been vacated or should be reviewed."}'
WHERE common_charge_slug = 'failure-to-register' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"The victim''s age is an element that is easily proven through birth records and typically undisputed.","Forensic evidence (DNA, SANE exam), electronic communications, and the child''s outcry statements support the charge.","Missouri law provides no consent defense — the child''s agreement is legally irrelevant."}',
  defense_opportunities = '{"Misidentification — the defendant is not the person who committed the act.","Fabrication or coaching — the child''s account was influenced by a parent, therapist, or other adult with an ulterior motive.","Challenge the forensic evidence — DNA presence alone does not establish sexual contact.","Challenge the child forensic interview methodology — suggestive questioning techniques can produce unreliable statements."}',
  common_defenses = '{"Misidentification — defendant was not the perpetrator.","False allegation — the accusation was fabricated or coached by a third party.","No sexual contact — DNA or other evidence does not prove sexual contact occurred.","Flawed forensic interview — the child''s statements were produced through suggestive or leading interview techniques."}'
WHERE common_charge_slug = 'statutory-rape' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Multiple witness accounts of the disorderly behavior provide corroborating testimony.","Officer testimony about the defendant''s conduct and its impact on public order is given significant weight.","Video evidence from bystanders or surveillance cameras captures the conduct directly."}',
  defense_opportunities = '{"Class B Misdemeanor means maximum 6 months and $500 fine — room for diversion and dismissal.","First Amendment defense — speech and expression are constitutionally protected, and mere offensive language may not suffice.","Challenge the ''unreasonable'' standard — what constitutes unreasonable noise or conduct is subjective.","Argue the officer overreacted to lawful conduct that did not actually disturb the peace."}',
  common_defenses = '{"Constitutional protection — the defendant''s speech or expression was protected by the First Amendment.","Not unreasonable — the conduct did not rise to the level of ''unreasonable'' disturbance required by statute.","Self-defense — the physical altercation was defensive in nature.","Overreaction — law enforcement overresponded to a minor disturbance."}'
WHERE common_charge_slug = 'disorderly-conduct' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Bodycam and dashcam footage capturing the defendant''s resistance provides objective evidence.","Officer testimony about the defendant''s physical resistance, flight, or interference is direct evidence.","Injuries to officers during the arrest corroborate the level of resistance."}',
  defense_opportunities = '{"Challenge the lawfulness of the underlying arrest — if the arrest was unlawful, there was no legal duty to submit.","Argue the defendant''s actions were instinctive (pulling away) rather than purposeful resistance.","Challenge the proportionality of force used by officers — excessive force may have provoked the defendant''s reaction.","Medical condition that caused involuntary movements interpreted as resistance."}',
  common_defenses = '{"Unlawful arrest — the underlying arrest lacked probable cause, negating the duty to submit.","Excessive force — the officer used disproportionate force, and the defendant''s actions were a natural response.","No purposeful resistance — the defendant''s movements were instinctive, reflexive, or caused by a medical condition.","Misidentification — the defendant was not the person who resisted."}'
WHERE common_charge_slug = 'resisting-arrest' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Witness testimony from officers about false statements made by the defendant is direct evidence.","Electronic evidence (texts, calls, social media) showing the defendant warned or aided the suspect is compelling.","Physical evidence of concealment (hidden evidence, altered scene) corroborates the obstruction."}',
  defense_opportunities = '{"Challenge the knowledge element — the defendant did not know there was an investigation or that the person was a suspect.","Argue the information provided was true, not false — a mistake or misunderstanding is not obstruction.","Fifth Amendment privilege — the defendant may have a right to remain silent that was exercised, not to actively obstruct.","Challenge whether the defendant''s conduct actually hindered the investigation in any meaningful way."}',
  common_defenses = '{"Lack of knowledge — defendant did not know about the investigation or that their conduct would obstruct it.","Truthful statement — the information provided to law enforcement was accurate.","No interference — the defendant''s conduct did not actually impede the investigation.","Constitutional privilege — defendant exercised their right to remain silent or consult counsel."}'
WHERE common_charge_slug = 'obstruction-justice' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"The court order itself and proof of service establish what the defendant was required to do.","Documentary evidence of non-compliance (missed payments, continued contact, failure to appear) is straightforward.","The judge who issued the order is often the same judge presiding over the contempt proceeding."}',
  defense_opportunities = '{"Argue inability to comply — the defendant could not comply with the order despite good-faith efforts (financial inability, impossibility).","Challenge service — the defendant was not properly served with the order and did not know its requirements.","Argue the order itself is invalid or unconstitutional — compliance with an invalid order is not required.","Demonstrate substantial compliance — the defendant made good-faith efforts to comply."}',
  common_defenses = '{"Inability to comply — defendant could not comply despite good-faith efforts (particularly for financial obligations).","Lack of notice — defendant was not properly notified of the order''s requirements.","Invalid order — the underlying order was defective, overbroad, or unconstitutional.","Substantial compliance — defendant complied with the material terms of the order."}'
WHERE common_charge_slug = 'contempt-of-court' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Officer testimony about the defendant''s visible intoxication (odor, unsteadiness, slurred speech) is direct evidence.","BAC or drug test results confirm intoxication if testing was conducted.","Witness testimony from bystanders disturbed by the defendant''s behavior corroborates the charge."}',
  defense_opportunities = '{"Missouri does not have a standalone public intoxication statute — the charge must be brought under peace disturbance, requiring additional elements.","Argue the defendant was intoxicated but was not disturbing the peace or creating a nuisance.","Medical condition defense — diabetes, medication side effects, or neurological conditions can mimic intoxication.","Challenge whether the location was truly ''public'' — private property or areas with limited public access may not qualify."}',
  common_defenses = '{"No peace disturbance — defendant was intoxicated but not disturbing others or creating a public nuisance.","Medical condition — symptoms interpreted as intoxication were caused by a medical condition.","Not in public — defendant was on private property or in a location that does not qualify as a public place.","Involuntary intoxication — defendant was drugged or consumed an intoxicating substance unknowingly."}'
WHERE common_charge_slug = 'public-intoxication' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Court records documenting the scheduled appearance and the defendant''s absence are conclusive.","Proof of service or in-court notification of the next appearance date establishes the defendant''s knowledge.","Bond forfeiture proceedings create additional financial consequences beyond the criminal charge."}',
  defense_opportunities = '{"Demonstrate the defendant was not properly notified of the court date — address changes, attorney miscommunication.","Argue the failure was involuntary — hospitalization, incarceration in another jurisdiction, emergency circumstances.","Show the defendant surrendered promptly after learning of the missed date — demonstrates lack of willful evasion.","Challenge whether the defendant received the specific notice of the court date through proper channels."}',
  common_defenses = '{"Lack of notice — defendant did not receive notification of the court date.","Involuntary absence — defendant was hospitalized, incarcerated elsewhere, or faced an emergency.","Prompt surrender — defendant appeared voluntarily as soon as they learned of the missed date.","Good cause — legitimate reason for missing the appearance (family emergency, transportation failure, illness)."}'
WHERE common_charge_slug = 'failure-to-appear' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"The false statement is documented in police reports and can be compared with actual evidence.","Witness testimony contradicting the defendant''s reported version of events establishes the falsity.","Electronic evidence (surveillance footage, phone records, GPS data) disproving the report is objective."}',
  defense_opportunities = '{"Argue the defendant genuinely believed their report was accurate — mistaken perception is not a false report.","Challenge the ''knowingly false'' element — the prosecution must prove the defendant knew the statement was false.","Class B Misdemeanor provides room for diversion programs and alternative resolution.","Argue the inconsistencies are due to stress, confusion, or imperfect memory rather than intentional falsity."}',
  common_defenses = '{"Good faith belief — defendant genuinely believed the report was accurate at the time.","Confusion or stress — misstatements were due to emotional distress, not intentional falsification.","Misperception — defendant''s account reflects their honest but mistaken perception of events.","Immaterial inconsistency — the inaccurate details are minor and do not constitute a ''false report.''"}'
WHERE common_charge_slug = 'false-report' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Electronic evidence (text messages, emails, voicemails, social media posts) preserves the exact words of the threat.","Witness testimony from the person threatened and bystanders who heard the threat is direct evidence.","Context evidence (prior conflicts, escalating behavior, weapon access) supports the seriousness of the threat."}',
  defense_opportunities = '{"First Amendment defense — the statement was protected speech (political hyperbole, artistic expression, venting frustration).","Argue the statement was not a ''true threat'' — it would not have been taken seriously by a reasonable person in context.","Challenge the intent element — the defendant did not actually intend to terrorize or instill fear.","Argue the statement was conditional, vague, or made in jest and not a genuine threat."}',
  common_defenses = '{"Protected speech — the statement was constitutionally protected expression, not a true threat.","No intent to terrorize — defendant did not intend the statement to instill fear.","Not a true threat — a reasonable person would not have perceived the statement as a genuine threat.","Context — the statement was made in jest, during an argument, or as hyperbolic expression."}'
WHERE common_charge_slug = 'criminal-threat' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"The sworn testimony or document containing the false statement is a matter of record.","Documentary evidence contradicting the sworn statement proves the falsity objectively.","Witness testimony from others with knowledge of the true facts establishes what the defendant knew."}',
  defense_opportunities = '{"Challenge the materiality of the false statement — perjury requires the statement to be material to the proceeding.","Argue the statement was technically true, ambiguous, or based on the defendant''s honest misrecollection.","Challenge the ''knowingly false'' element — the defendant believed the statement was true when made.","Recantation defense — if the defendant corrected the false statement before the proceeding concluded."}',
  common_defenses = '{"Truth — the statement was actually true, and the prosecution''s evidence to the contrary is incorrect.","Honest mistake — the defendant believed the statement was true and the error was not intentional.","Immateriality — the false statement was not material to the proceeding.","Ambiguity — the question was ambiguous and the answer was literally true."}'
WHERE common_charge_slug = 'perjury' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Recorded conversations or surveillance capturing the bribery offer or payment is powerful direct evidence.","Financial records showing transfers between the defendant and the official create a documentary trail.","Cooperating witness testimony from the public official who reported the bribe attempt is highly credible."}',
  defense_opportunities = '{"Challenge whether the payment was truly intended to influence official action — distinguish between gifts, campaign contributions, and bribes.","Argue entrapment — law enforcement initiated and facilitated the bribery scheme.","Challenge the recording quality and interpretation of conversations — ambiguous statements may not constitute a bribe offer.","Argue the payment was for legitimate services unrelated to official duties."}',
  common_defenses = '{"Legitimate transaction — the payment was for lawful services or a legitimate campaign contribution.","Entrapment — law enforcement or a cooperating witness initiated and induced the bribery.","No intent to influence — the payment was not intended to influence official action.","Ambiguous communication — the conversation does not clearly establish a quid pro quo."}'
WHERE common_charge_slug = 'bribery' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Institutional records documenting the defendant''s custody status and departure from the facility are conclusive.","Surveillance footage from the facility capturing the escape provides objective evidence.","Officer testimony about the circumstances of the escape and the defendant''s return or capture is direct evidence."}',
  defense_opportunities = '{"Argue the custody was not lawful — if the underlying arrest or commitment was illegal, the escape may be justified.","Duress defense — the defendant escaped due to threats to their life or safety within the facility.","Argue the defendant was released through administrative error and reasonably believed they were authorized to leave.","Walkaway from work release or minimum security may be treated less severely than escape from secure confinement."}',
  common_defenses = '{"Unlawful custody — the underlying arrest or detention was not legally valid.","Duress — defendant escaped due to credible threats to their safety within the facility.","Administrative error — defendant reasonably believed they had been released.","Voluntary return — defendant returned to custody voluntarily, mitigating the offense."}'
WHERE common_charge_slug = 'escape-custody' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Veterinary evidence documenting the animal''s injuries, condition, and cause of suffering is compelling and detailed.","Photographs and video of the animal''s condition provide visceral evidence that strongly influences juries.","Witness testimony from neighbors, animal control officers, and veterinarians establishes the pattern of abuse or neglect."}',
  defense_opportunities = '{"Argue the harm was accidental or the result of financial inability to provide care rather than intentional abuse.","Challenge the veterinary expert''s conclusions about the cause and timing of injuries.","Distinguish between neglect due to hardship and purposeful cruelty — the mental state elements differ significantly.","Argue the animal''s condition was pre-existing or caused by a different person or animal."}',
  common_defenses = '{"Accidental harm — the animal''s injuries or condition were not caused intentionally.","Financial hardship — defendant could not afford veterinary care but did not intentionally cause suffering.","Pre-existing condition — the animal''s health issues existed before the defendant''s custody.","Alternative perpetrator — another person or animal caused the injuries."}'
WHERE common_charge_slug = 'animal-cruelty' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Probation officer testimony about specific violations (missed appointments, failed drug tests, new arrests) is direct evidence.","Drug test results documented by the probation office are typically reliable and difficult to challenge.","New arrest reports and conviction records prove violation of the ''no new criminal conduct'' condition."}',
  defense_opportunities = '{"The lower evidentiary standard cuts both ways — the defense needs to raise only a reasonable explanation for the alleged violation.","Courts prefer continued probation over revocation — argue for modified conditions, additional treatment, or sanctions short of revocation.","Challenge the drug test methodology — chain of custody, testing procedures, and confirmation testing may be deficient.","Present mitigation evidence (employment, family support, treatment progress) to support continued probation."}',
  common_defenses = '{"Substantial compliance — defendant complied with the material conditions despite a technical violation.","Good cause — legitimate reason for the violation (medical emergency, employment conflict, miscommunication).","Testing error — drug test results are unreliable due to procedural or methodological issues.","Modified conditions — request amended probation terms rather than revocation."}'
WHERE common_charge_slug = 'probation-violation' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Parole officer documentation of violations is systematic and detailed, covering every missed check-in, failed test, or rule breach.","GPS monitoring and electronic surveillance data can pinpoint the parolee''s location and movements.","New criminal charges, even if not yet convicted, can support revocation based on the conduct itself."}',
  defense_opportunities = '{"Present mitigating factors — employment, treatment compliance, family stability, and community support favor continued parole.","Challenge the reliability of GPS monitoring data — technical malfunctions, dead zones, and calibration issues can produce false readings.","Argue the violation was technical rather than substantive — administrative violations carry less weight than new criminal conduct.","Request graduated sanctions rather than full revocation — Missouri''s parole system recognizes intermediate responses."}',
  common_defenses = '{"Technical violation — the violation was minor and administrative rather than involving new criminal conduct.","Good cause — legitimate excuse for the violation (illness, emergency, equipment malfunction).","Monitoring error — GPS or electronic monitoring data is unreliable.","Disproportionate response — revocation is excessive given the nature of the violation and the parolee''s overall compliance."}'
WHERE common_charge_slug = 'parole-violation' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Statements, communications, and actions showing the defendant assisted or encouraged the principal actor are admissible.","An accomplice is liable for the same offense as the principal — no reduced charge merely for being the helper rather than the doer.","Co-defendant testimony through cooperation agreements frequently implicates accomplices."}',
  defense_opportunities = '{"Challenge the ''purposely'' element — mere presence at the scene or association with the principal is insufficient.","Argue the defendant''s assistance was for a different, innocent purpose and they did not know a crime would occur.","Withdraw defense — the defendant withdrew from the plan before the crime was committed and communicated this withdrawal.","Challenge co-defendant credibility — cooperating witnesses have strong incentives to shift blame."}',
  common_defenses = '{"Mere presence — defendant was present but did not aid, agree, or attempt to aid the principal.","Lack of knowledge — defendant did not know the principal intended to commit a crime.","Withdrawal — defendant withdrew from the criminal plan before it was carried out.","Coerced cooperation — defendant was forced to assist under threat of harm."}'
WHERE common_charge_slug = 'aiding-abetting' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Evidence of planning, preparation, and steps taken toward completing the crime establishes the substantial step element.","Statements of intent combined with overt acts provide strong evidence of the defendant''s purpose.","Abandonment after detection does not constitute a defense — only voluntary abandonment before a substantial step counts."}',
  defense_opportunities = '{"Challenge the ''substantial step'' element — mere preparation or planning may not cross the line into attempt.","Argue impossibility — the crime could not have been completed due to circumstances unknown to the defendant.","The penalty is one classification lower than the completed crime, providing leverage in negotiations."}',
  common_defenses = '{"Voluntary abandonment — defendant voluntarily and completely renounced the criminal purpose before a substantial step.","No substantial step — the defendant''s actions did not progress beyond mere preparation.","Legal impossibility — the defendant''s intended conduct would not have constituted a crime even if completed.","Lack of intent — defendant did not have the specific intent required for the attempted crime."}'
WHERE common_charge_slug = 'attempt' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Co-conspirator statements are admissible against all members of the conspiracy under the co-conspirator exception to hearsay.","Communications evidence (text messages, recorded calls, intercepted messages) documenting the agreement is powerful.","Each co-conspirator is liable for all reasonably foreseeable acts committed by other members in furtherance of the conspiracy."}',
  defense_opportunities = '{"Challenge the existence of an actual agreement — mere association or parallel behavior is insufficient.","Argue the defendant was not a member of the conspiracy — knowledge of others'' plans is not the same as joining them.","Withdrawal defense — the defendant withdrew from the conspiracy before the overt act and communicated this withdrawal.","Challenge the reliability of co-conspirator statements — cooperating witnesses have incentives to exaggerate the defendant''s role."}',
  common_defenses = '{"No agreement — there was no actual agreement between the defendant and others to commit the offense.","Withdrawal — defendant withdrew from the conspiracy before any overt act and communicated the withdrawal.","Not a member — defendant was aware of others'' plans but did not join or participate in the conspiracy.","Unreliable informant — co-conspirator testimony is unreliable due to cooperation deals and bias."}'
WHERE common_charge_slug = 'conspiracy' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Victim testimony about the coercion, deception, or force used is central to the prosecution''s case.","Financial records showing the defendant profited from the trafficking operation provide clear motive evidence.","Electronic communications documenting the recruitment, transport, and exploitation of victims are highly incriminating."}',
  defense_opportunities = '{"Challenge the coercion or deception element — argue the alleged victim participated voluntarily in the activity.","Argue the defendant was a victim themselves, coerced into participating in the trafficking operation.","Challenge victim credibility — inconsistent statements, motive to cooperate for immigration benefits, and reliability.","Suppress evidence obtained through warrantless surveillance or illegal wiretaps."}',
  common_defenses = '{"Voluntary participation — the alleged victim was not coerced, deceived, or forced.","Defendant was a victim — the defendant was themselves a trafficking victim coerced into participation.","Lack of knowledge — defendant did not know the operation involved trafficking or exploitation.","Insufficient evidence of force, fraud, or coercion — the prosecution cannot prove the required element."}'
WHERE common_charge_slug = 'human-trafficking' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Victim testimony about being physically prevented from leaving is direct evidence.","Physical evidence of restraint (locked doors, blocked exits, bound hands) corroborates the victim''s account.","Witness testimony from those who saw or heard the victim''s attempts to leave supports the charge."}',
  defense_opportunities = '{"Class A Misdemeanor classification provides room for negotiation and alternative resolution.","Argue consent — the alleged victim voluntarily remained and was not actually restrained.","Challenge the duration and nature of the restraint — brief or de minimis restraint may not meet the statutory threshold.","Parental authority defense — a parent''s reasonable restraint of a minor child for discipline purposes."}',
  common_defenses = '{"Consent — the alleged victim was not actually restrained against their will.","Brief detention — the restraint was so brief or minor it does not constitute unlawful imprisonment.","Parental authority — the restraint was a reasonable exercise of parental authority over a minor child.","Lawful authority — the defendant had legal authority to restrain (citizen''s arrest, store security detention)."}'
WHERE common_charge_slug = 'unlawful-imprisonment' AND jurisdiction = 'MO';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Lab testing identifies the specific opioid substance and quantity with high reliability.","Fentanyl''s extreme potency means even very small quantities represent a significant amount for charging purposes.","Opioid overdose epidemic context influences jury perception and reduces sympathy arguments."}',
  defense_opportunities = '{"Valid prescription defense — the defendant had a legitimate prescription for the opioid medication.","Drug court eligibility provides treatment-based alternatives specifically designed for opioid addiction cases.","Challenge the search that produced the opioids — suppression eliminates the prosecution''s case.","Argue constructive possession failure in shared spaces — link to the specific defendant must be established."}',
  common_defenses = '{"Valid prescription — defendant possessed the opioid pursuant to a legitimate medical prescription.","Illegal search — the opioids were found during an unconstitutional search.","Lack of knowledge — defendant did not know the substance was an opioid (e.g., counterfeit pills).","Constructive possession failure — prosecution cannot link the defendant to the opioids found in a shared space."}'
WHERE common_charge_slug = 'drug-possession-opioids' AND jurisdiction = 'MO';

-- MT enrichment
UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Section 61-8-401 mandates 24 hours minimum jail for first offense, 7 days for second, 30 days for third — rigid floors that limit judicial discretion.","ACE (Alcohol Compliance Enforcement) compliance is monitored by MDT and tracked across counties for sentencing enhancement."}',
  defense_opportunities = '{"Challenge the 10-year lookback — prior convictions outside the window cannot be used to elevate the current offense.","Question Intoxilyzer maintenance and calibration documentation — Montana requires strict procedural compliance.","Challenge the legality of the traffic stop or DUI checkpoint under Montana''s strict stop-justification standards.","Rising blood alcohol defense — argue that BAC was below .08 at the actual time of driving.","ACE program and 24/7 sobriety alternatives provide non-incarceration paths for first-time offenders."}',
  common_defenses = '{"Improper stop — no reasonable suspicion under Montana law.","Faulty breath test — instrument malfunction or expired calibration.","Rising BAC — alcohol still being absorbed at time of driving.","Involuntary intoxication — unknowing consumption of intoxicating substance.","Necessity — emergency circumstances required driving."}'
WHERE common_charge_slug = 'dui-dwi' AND jurisdiction = 'MT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Section 61-8-401(1) imposes 24 consecutive hours imprisonment as a mandatory floor — courts cannot suspend below this minimum."}',
  defense_opportunities = '{"Court may suspend all but 24 hours of the sentence, providing significant flexibility.","Probationary license available after 45 days, mitigating practical license-loss impact.","Challenge the 24-hour observation period before chemical testing.","Medical conditions (GERD, diabetes, low-carb diet) can produce false breath readings."}',
  common_defenses = '{"Improper FST administration — failure to follow NHTSA standards.","Medical condition explaining apparent impairment.","Lack of probable cause for arrest.","Chain of custody issues with blood samples or breath testing protocols."}'
WHERE common_charge_slug = 'dui-first-offense' AND jurisdiction = 'MT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Fourth or subsequent DUI is a felony with up to 5 years imprisonment.","Vehicle forfeiture is possible for repeat offenders under Montana law.","Prior conviction records are easily authenticated and admitted.","24/7 sobriety program participation may be ordered as a release or sentence condition."}',
  defense_opportunities = '{"Attack validity of prior convictions taken without counsel or proper advisements.","Argue out-of-state priors do not qualify under Montana''s prior DUI definition.","Negotiate for treatment court diversion, particularly for third offense."}',
  common_defenses = '{"Prior conviction outside 10-year lookback.","Constitutionally defective prior plea.","Out-of-state offense does not qualify under Montana definition.","Standard DUI defenses with heightened importance for felony exposure."}'
WHERE common_charge_slug = 'dui-repeat-offense' AND jurisdiction = 'MT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Section 61-8-401(1)(b)-(d) covers driving under the influence of any drug — including legal and prescription medications.","DRE 12-step evaluations have been accepted by Montana courts as reliable evidence.","Toxicology results showing controlled substance presence combined with driving behavior support impairment findings.","No per se drug limit, but officer observations and testing combine to prove impairment."}',
  defense_opportunities = '{"Without per se drug limits, prosecution must prove actual impairment — drug presence alone is insufficient.","Challenge DRE officer''s training currency, certification, and adherence to the 12-step protocol.","Drug metabolites (especially THC) can persist for weeks without indicating current impairment.","Valid prescription defense for medications taken as directed at therapeutic levels."}',
