  defense_opportunities = '{"Challenge the legality of the traffic stop — New Hampshire requires reasonable articulable suspicion; without it, all evidence from the stop may be suppressed.","Challenge field sobriety test administration — deviations from NHTSA standardized protocols can undermine the reliability of observations used to establish impairment.","Challenge the calibration and maintenance records of the Intoxilyzer or blood testing equipment; improper maintenance voids the per se presumption.","Argue rising blood alcohol defense — BAC was below 0.08 at the time of driving but rose between the stop and the chemical test due to absorption timing."}',
  common_defenses = '{"Improper stop — no reasonable articulable suspicion to initiate the traffic stop.","Rising BAC defense — defendant''s blood alcohol was below the legal limit at the time of actual operation.","Involuntary intoxication — defendant was unknowingly drugged or consumed substances without awareness.","Necessity defense — defendant drove under the influence to avoid a greater harm or imminent danger."}'
WHERE common_charge_slug = 'dui-dwi' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Mandatory license revocation of 9 months to 2 years and IDIP completion provide additional leverage for plea negotiations.","Officer testimony regarding driving pattern, odor of alcohol, and failed field sobriety tests can establish impairment even without a chemical test result."}',
  defense_opportunities = '{"Challenge whether the defendant was actually ''operating'' the vehicle under NH law — mere physical control (e.g., sitting in parked car with engine off) may not satisfy the element.","Contest the field sobriety test results by highlighting medical conditions, road conditions, or non-standard administration that could produce false indicators of impairment.","If BAC was borderline (near 0.08), challenge the margin of error inherent in chemical testing equipment.","Seek conditional discharge or alternative sentencing programs available for first-time offenders in New Hampshire."}',
  common_defenses = '{"Not operating — defendant was not driving or attempting to operate the vehicle at the time.","Faulty breathalyzer — challenge calibration records, maintenance logs, and operator certification.","Medical condition defense — physical condition (GERD, diabetes) produced false high BAC reading or mimicked impairment signs.","Rising BAC — blood alcohol was still being absorbed and was below 0.08 at the time of driving."}'
WHERE common_charge_slug = 'dui-first-offense' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"New Hampshire''s 10-year lookback period for prior DWI offenses captures convictions from other states and military courts.","Indefinite license revocation for third offense (minimum 5 years) and fourth+ (minimum 7 years) removes the primary mode of transportation, pressuring plea deals."}',
  defense_opportunities = '{"Challenge whether prior out-of-state convictions qualify as equivalent offenses under New Hampshire''s DWI statute for purposes of enhancement.","Verify that the 10-year lookback calculation is correct — prior convictions outside the window cannot be used for enhancement purposes.","Argue for treatment court or alternative sentencing where the defendant demonstrates substance abuse disorder and willingness to participate in treatment programs.","Challenge the constitutional validity of prior convictions used for enhancement — if the defendant was not represented by counsel in a prior case, that conviction may be invalid."}',
  common_defenses = '{"Invalid prior conviction — challenge the use of a prior DWI that was obtained without proper counsel or constitutional protections.","Lookback period expiration — prior conviction falls outside the 10-year window and cannot be used for enhancement.","Improper stop or search — suppress evidence obtained through an unconstitutional traffic stop.","Faulty chemical testing — challenge equipment maintenance, operator certification, or chain of custody."}'
WHERE common_charge_slug = 'dui-repeat-offense' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Drug Recognition Expert (DRE) testimony is admissible in New Hampshire to establish impairment by specific drug categories.","Positive toxicology results for controlled substances create strong circumstantial evidence of impairment even when physical symptoms are ambiguous.","Legally prescribed medications can still form the basis of a DWI-drugs charge if they impair the defendant''s ability to drive safely."}',
  defense_opportunities = '{"Challenge the DRE officer''s qualifications, protocol compliance, and the scientific reliability of the 12-step DRE evaluation process.","Argue that the presence of drug metabolites in the system does not prove active impairment at the time of driving — metabolites can persist for days or weeks.","Challenge whether the observed driving behavior was actually caused by the drug in question versus fatigue, medical condition, or distraction.","Highlight the lack of a per se threshold for drug impairment, making the prosecution''s burden entirely dependent on subjective officer observations."}',
  common_defenses = '{"No active impairment — drug metabolites were present but the substance was no longer causing impairment at the time of driving.","Legitimate prescription defense — medication was taken as prescribed and defendant was not warned it could impair driving.","Faulty DRE evaluation — officer failed to follow the standardized 12-step protocol or lacked proper certification.","Alternative explanation — observed driving pattern and physical symptoms were caused by fatigue, illness, or other non-drug factors."}'
WHERE common_charge_slug = 'dui-drugs' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Dashcam, bodycam, and civilian video evidence increasingly captures the driving behavior in real time.","Officer testimony about speed, lane changes, and road conditions is typically given substantial weight by juries.","Reckless driving can be charged alongside other offenses (DWI, hit-and-run) to increase plea leverage."}',
  defense_opportunities = '{"Challenge the subjective nature of ''reckless'' — argue that the driving behavior was merely negligent or careless, not rising to the level of recklessness.","Introduce evidence of road conditions, weather, construction, or emergency circumstances that explain the driving behavior.","Challenge officer''s ability to accurately estimate speed or observe driving pattern from their vantage point."}',
  common_defenses = '{"Emergency circumstances — defendant was responding to a medical or safety emergency requiring immediate action.","Not reckless — conduct was negligent or careless but did not rise to the level of conscious disregard for safety.","Inaccurate speed estimate — officer''s visual speed estimation was unreliable or radar/lidar was improperly calibrated.","Private way — driving occurred on private property outside the statute''s jurisdiction."}'
WHERE common_charge_slug = 'reckless-driving' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Forensic evidence from the scene (paint transfer, vehicle debris, surveillance footage) can identify the vehicle even without a witness to the driver''s identity.","Cell phone location data and toll records can place the defendant''s vehicle at the scene at the relevant time.","Leaving the scene creates an inference of consciousness of guilt that is admissible at trial."}',
  defense_opportunities = '{"Argue the defendant was unaware an accident occurred — no impact felt, no visible damage, no indication of injury at the scene.","Challenge the identification of the driver — the vehicle may have been identified but the prosecution must prove who was actually driving.","Demonstrate that the defendant reported the accident within a reasonable time after becoming aware of the incident.","Argue that the defendant left the scene to seek medical assistance for themselves or to call emergency services from a safe location."}',
  common_defenses = '{"Lack of knowledge — defendant did not know an accident had occurred or that it involved injury.","Mistaken identity — defendant was not the driver of the vehicle at the time of the accident.","Timely reporting — defendant reported the accident as soon as they became aware of the incident.","Duress or emergency — defendant left the scene due to threats to personal safety or medical emergency."}'
WHERE common_charge_slug = 'hit-and-run' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Causation is broadly interpreted — prosecution need only show that the defendant''s impaired driving was a contributing cause, not the sole cause of death.","BAC results at the time of the accident create a strong presumption of impairment that is difficult to overcome.","Victim impact evidence at sentencing is highly persuasive and typically results in significant prison time."}',
  defense_opportunities = '{"Challenge causation — argue the victim''s death resulted from an independent intervening cause (victim''s own negligence, road defect, mechanical failure).","Challenge the toxicology evidence and its connection to impairment at the actual time of the collision.","Retain accident reconstruction experts to demonstrate that the accident would have occurred regardless of the defendant''s impairment.","Negotiate for a lesser included offense (negligent homicide without DWI component) where the evidence of impairment is weak."}',
  common_defenses = '{"Independent intervening cause — the death resulted from factors unrelated to the defendant''s driving (victim''s actions, mechanical failure, road defects).","Lack of impairment — BAC was below the legal limit or drug impairment was not established at the time of the accident.","Accident reconstruction — expert testimony showing the collision was unavoidable regardless of impairment.","Contributory negligence of the victim — victim''s own actions (jaywalking, no seatbelt) were the primary cause of death."}'
WHERE common_charge_slug = 'vehicular-homicide' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"The standard for criminal negligence (failure to be aware of substantial and unjustifiable risk) is lower than recklessness.","Physical evidence from the accident scene (skid marks, speed data, phone records) often strongly supports the negligence element.","Expert accident reconstruction testimony typically carries significant weight with juries."}',
  defense_opportunities = '{"Challenge the prosecution''s theory of negligence — argue the defendant exercised reasonable care under the circumstances.","Present evidence of sudden mechanical failure, road hazards, or weather conditions that contributed to the accident.","Retain an independent accident reconstruction expert to offer an alternative explanation for the collision.","Challenge whether the defendant''s conduct rose to the level of ''criminal'' negligence versus ordinary civil negligence."}',
  common_defenses = '{"Reasonable care — defendant was operating the vehicle with due care and the accident was unforeseeable.","Sudden emergency — an unexpected event (tire blowout, animal in road, medical episode) caused the loss of control.","Victim negligence — the deceased''s own conduct was the proximate cause of the fatal outcome.","Not criminally negligent — conduct was ordinary negligence at most, not the gross deviation required for criminal liability."}'
WHERE common_charge_slug = 'vehicular-manslaughter' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"DMV records definitively establish the suspension status, and notice of suspension is presumed if mailed to the defendant''s address of record.","Repeat violations are enhanced: second offense is a Class A Misdemeanor, subsequent offenses within 7 years can be charged as a Class B Felony.","If the underlying suspension was DWI-related, additional mandatory penalties apply including potential vehicle impoundment."}',
  defense_opportunities = '{"Challenge whether the defendant received actual notice of the suspension — the DMV notice may have been sent to an outdated address.","Argue the suspension was improperly imposed by the DMV (administrative error, failure to credit time served, or incorrect computation).","Present evidence that the defendant had a good faith belief their license had been reinstated.","Challenge the identification of the driver — someone else may have been operating the defendant''s vehicle."}',
  common_defenses = '{"Lack of notice — defendant never received notification that their license was suspended or revoked.","Administrative error — DMV records were incorrect and the license should not have been in suspended status.","Good faith belief — defendant reasonably believed the suspension had been lifted or the license reinstated.","Necessity — defendant drove out of urgent necessity (medical emergency, fleeing danger) with no alternative transportation."}'
WHERE common_charge_slug = 'driving-on-suspended' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"The prosecution can introduce the full pursuit footage showing the duration and danger of the flight.","Any injuries or property damage during the pursuit can be charged separately and increase overall exposure.","Consciousness of guilt inference — flight from police suggests the defendant was aware they were committing a crime."}',
  defense_opportunities = '{"Argue the defendant did not see or hear the officer''s signal to stop due to road noise, music, or visual obstructions.","Challenge whether the officer was in a marked vehicle or uniform — defendant must have known it was law enforcement.","Argue the defendant was attempting to reach a safe location to stop (well-lit area, populated area) rather than fleeing.","If the officer''s initial reason for the stop was invalid, the entire encounter may be challenged."}',
  common_defenses = '{"No knowledge of pursuit — defendant did not see or hear the officer''s signals to stop.","Unmarked vehicle — officer was not in a marked police vehicle or identifiable uniform, creating reasonable fear.","Seeking safe location — defendant was driving to a safe, well-lit area before stopping.","Invalid initial stop — the officer lacked legal basis for the traffic stop."}'
WHERE common_charge_slug = 'fleeing-eluding' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Constructive possession doctrine allows conviction even when drugs are found in shared spaces (vehicle, residence) if prosecution shows knowledge and ability to control.","Field test results and laboratory confirmation provide strong physical evidence of the substance''s identity."}',
  defense_opportunities = '{"Challenge the legality of the search — was there probable cause, a valid warrant, or an applicable exception to the warrant requirement?","Challenge constructive possession — if drugs were in a shared space, argue the defendant lacked knowledge of or control over the substance.","Request independent laboratory testing of the substance — field tests have known false positive rates."}',
  common_defenses = '{"Illegal search and seizure — the drugs were obtained through an unconstitutional search without probable cause or valid warrant.","Lack of knowledge — defendant did not know the controlled substance was present (e.g., in a borrowed vehicle or shared residence).","Lack of possession — the substance belonged to another person and was not under the defendant''s control.","Substance identity challenge — the material tested is not actually a controlled substance or the testing was flawed."}'
WHERE common_charge_slug = 'drug-possession' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Possession with intent indicators (packaging, scales, large cash amounts) can elevate a simple possession charge to distribution.","Marijuana odor still provides probable cause for vehicle searches in New Hampshire, unlike some neighboring states."}',
  defense_opportunities = '{"If the amount is 3/4 oz or less, the offense is a violation (not a crime) with a maximum $100 fine — argue for accurate weighing and classification.","Challenge the weight measurement — ensure the marijuana was weighed without packaging, containers, or moisture that inflates the amount.","Challenge the search that produced the marijuana — NH still requires probable cause beyond just odor in many circumstances.","Argue for diversion or treatment alternatives available for first-time marijuana offenses."}',
  common_defenses = '{"Illegal search — the marijuana was discovered through an unconstitutional search.","Inaccurate weight — the substance was weighed improperly, including packaging or non-marijuana material.","Lack of possession — the marijuana belonged to another person and the defendant had no knowledge or control."}'
WHERE common_charge_slug = 'drug-possession-marijuana' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Laboratory analysis definitively identifies cocaine and its purity, providing strong physical evidence.","Possession of cocaine often accompanies other charges (DWI, paraphernalia) that strengthen the overall case."}',
  defense_opportunities = '{"Challenge the search warrant or warrantless search justification — cocaine evidence is frequently suppressed when the search was improper.","Challenge the chain of custody from seizure through laboratory testing.","Challenge constructive possession when cocaine was found in a shared location."}',
  common_defenses = '{"Illegal search and seizure — no valid warrant or exception to the warrant requirement.","Lack of knowledge — defendant was unaware cocaine was present in the location or on their person.","Chain of custody — gaps in evidence handling undermine the reliability of laboratory results.","Entrapment — law enforcement induced the defendant to possess cocaine they would not have otherwise possessed."}'
WHERE common_charge_slug = 'drug-possession-cocaine' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Meth manufacturing evidence (precursors, equipment) found alongside possession dramatically increases charges and sentencing exposure.","The physical effects of methamphetamine use (dilated pupils, agitation, rapid speech) provide observable evidence of recent use."}',
  defense_opportunities = '{"Challenge the laboratory identification of the substance — some field tests produce false positives for methamphetamine.","If manufacturing evidence is also present, challenge whether the defendant was actually involved in production versus being a bystander.","Challenge the constitutionality of the search, particularly if it was based on an anonymous tip."}',
  common_defenses = '{"Illegal search and seizure — evidence obtained without proper warrant or exception.","Substance misidentification — field test was unreliable and laboratory confirmation is needed or was flawed.","Lack of knowledge — defendant did not know the substance was methamphetamine.","Mere presence — defendant was near the substance but did not possess or control it."}'
WHERE common_charge_slug = 'drug-possession-meth' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Quantity-based thresholds create presumptions of trafficking intent without requiring direct evidence of sales.","Wiretap evidence, controlled buys, and cooperating witness testimony are powerful prosecution tools in trafficking cases."}',
  defense_opportunities = '{"Challenge the ''intent to distribute'' inference — argue the quantity was consistent with personal use rather than distribution.","Challenge cooperating witness credibility — these witnesses often have significant incentive (reduced charges) to fabricate or exaggerate.","Challenge the reliability of controlled buy evidence — argue entrapment or procedural irregularities in the buy operation."}',
  common_defenses = '{"Personal use — the quantity possessed was for personal consumption, not distribution.","Entrapment — law enforcement induced the defendant to engage in trafficking they would not have otherwise committed.","Illegal wiretap — electronic surveillance was conducted without proper authorization.","Unreliable informant — cooperating witness testimony is fabricated or exaggerated to secure their own plea deal."}'
WHERE common_charge_slug = 'drug-trafficking' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Text messages, social media communications, and phone records frequently document distribution arrangements.","Co-defendant cooperation and plea agreements often produce testimony against the distribution network."}',
  defense_opportunities = '{"Challenge the identification of the defendant as the person who conducted the transaction — undercover operations can involve mistaken identity.","Argue the defendant was a mere user who shared drugs without profit motive, which may reduce the charge to a lesser offense.","Challenge the school zone measurement — distances must be accurately measured and the zone properly designated.","Challenge the admissibility of electronic communications — authentication and chain of custody issues."}',
  common_defenses = '{"Mistaken identity — the defendant was not the person who conducted the distribution.","Sharing without profit — drugs were shared among users without commercial intent, negating ''sale'' element.","Entrapment — government agent initiated and facilitated the transaction.","Illegal search — evidence of distribution was obtained through an unconstitutional search or surveillance."}'
WHERE common_charge_slug = 'drug-distribution' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Physical evidence of manufacturing (precursors, equipment, chemical residue) is often overwhelming and difficult to explain away.","Environmental hazard from manufacturing operations (especially meth labs) generates additional charges and public sympathy for prosecution.","Testimony from forensic chemists about the manufacturing process and materials found is highly persuasive."}',
  defense_opportunities = '{"Challenge whether the defendant was actually involved in the manufacturing process versus being present at the location.","Argue that the materials found were for lawful purposes and do not constitute manufacturing equipment or precursors.","Challenge the search warrant — manufacturing cases often arise from tips that may not establish sufficient probable cause.","Negotiate for cooperation agreements if the defendant has information about larger manufacturing operations."}',
  common_defenses = '{"Mere presence — defendant was at the location but not involved in the manufacturing process.","Lawful purpose — materials found had legitimate non-drug uses.","Invalid search warrant — the warrant was based on unreliable information or stale probable cause.","Lack of knowledge — defendant did not know that manufacturing was occurring at the location."}'
WHERE common_charge_slug = 'drug-manufacturing' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Drug residue on paraphernalia provides direct evidence linking the item to controlled substance use.","Paraphernalia charges are often added to drug possession charges, increasing the defendant''s total exposure.","Broad statutory definition covers a wide range of items, from traditional pipes to improvised devices."}',
  defense_opportunities = '{"Argue the item has a lawful purpose (tobacco pipe, kitchen scale, plastic bags) and no drug residue was found.","Challenge the ''intent to use'' element — mere possession of a dual-use item is insufficient without additional evidence.","If paraphernalia was found during a search, challenge the legality of the underlying search.","Argue the item belongs to another person in a shared living space or vehicle."}',
  common_defenses = '{"Lawful purpose — the item is commonly used for legal purposes (tobacco, cooking, storage).","Lack of intent — no evidence the item was intended for use with controlled substances.","Illegal search — the paraphernalia was discovered during an unconstitutional search.","Lack of possession — the item belonged to someone else."}'
WHERE common_charge_slug = 'drug-paraphernalia' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Circumstantial evidence of intent (quantity, packaging, scales, cash, multiple phones) creates strong inferences even without direct evidence of sales.","Expert testimony from narcotics officers about distribution indicators is admissible and persuasive.","Text messages and communications referencing drug transactions provide powerful corroborating evidence."}',
  defense_opportunities = '{"Challenge the ''intent'' element — argue the quantity and packaging were consistent with personal use patterns, not distribution.","Challenge the expert opinion on distribution indicators — many items (scales, baggies) have innocent explanations.","Suppress the evidence if the search was unconstitutional, which eliminates the physical evidence of quantity and packaging.","Argue for reduction to simple possession if the intent evidence is weak."}',
  common_defenses = '{"Personal use — the quantity and manner of possession were consistent with personal consumption.","Illegal search and seizure — the evidence was obtained without proper constitutional authority.","No evidence of intent — absence of distribution paraphernalia (scales, baggies, large cash) undermines the prosecution''s intent theory.","Constructive possession challenge — drugs were in a shared space and cannot be attributed solely to the defendant."}'
WHERE common_charge_slug = 'drug-possession-with-intent' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Premeditation evidence (planning, weapon acquisition, prior threats) is often documented through electronic communications and surveillance.","Forensic evidence (DNA, ballistics, digital forensics) in modern investigations provides powerful physical proof.","New Hampshire allows capital punishment for murder of law enforcement officers, creating maximum prosecutorial leverage."}',
  defense_opportunities = '{"Challenge premeditation — argue the killing was impulsive, not planned, potentially reducing the charge to second degree murder.","Challenge the forensic evidence through independent expert analysis — DNA contamination, ballistics matching errors, and digital evidence authentication issues.","Challenge eyewitness identifications using expert testimony on the unreliability of eyewitness memory."}',
  common_defenses = '{"Lack of premeditation — the killing occurred in the heat of the moment without prior planning.","Misidentification — the defendant was not the person who committed the killing.","Defense of others — defendant acted to protect another person from imminent deadly force."}'
WHERE common_charge_slug = 'murder-first-degree' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"A life sentence (with possibility of parole after minimum term) provides significant prosecutorial leverage.","Second degree murder is often charged as an alternative to first degree, giving the jury a compromise verdict option.","Circumstantial evidence of the defendant''s knowledge that their actions would cause death (weapon used, force applied) can satisfy the mens rea."}',
  defense_opportunities = '{"Present evidence of provocation or extreme emotional disturbance to reduce the charge.","Challenge the prosecution''s theory of how the death occurred through independent forensic analysis.","Argue lack of intent — the defendant''s actions were not designed to cause death and the result was accidental."}',
  common_defenses = '{"Self-defense — defendant reasonably believed deadly force was necessary to prevent imminent death or serious harm.","Heat of passion — the killing resulted from adequate provocation, reducing culpability to manslaughter.","Accident — the death was unintended and resulted from lawful activity.","Diminished capacity — mental illness or intoxication prevented the defendant from forming the required mental state."}'
WHERE common_charge_slug = 'murder-second-degree' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Voluntary manslaughter is often a lesser included offense of murder, and juries may convict on this charge as a compromise.","The ''cooling off'' period is factual — prosecution can argue that sufficient time elapsed for passions to cool, supporting murder rather than manslaughter.","Physical evidence of the cause of death (weapon, injuries) directly proves the defendant''s actions caused the fatal outcome."}',
  defense_opportunities = '{"Argue for maximum mitigation — present the full context of provocation to show the killing was a human reaction to extreme circumstances.","Challenge whether the death was actually caused by the defendant''s actions versus an independent factor.","Present character evidence and the defendant''s lack of violent history to support leniency at sentencing.","Argue for further reduction to involuntary manslaughter if the intent to kill was absent."}',
  common_defenses = '{"Self-defense — defendant acted in response to a physical threat, not mere provocation.","Adequate provocation — the provocation was so extreme that a reasonable person would have lost self-control.","Diminished capacity — mental health condition or extreme emotional state impaired the defendant''s judgment.","Accident — the death was an unintended result of a physical confrontation."}'
WHERE common_charge_slug = 'voluntary-manslaughter' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"The recklessness standard is lower than knowing or purposeful, making it easier to secure conviction.","Expert testimony on the foreseeability of death from the defendant''s conduct is highly persuasive.","Involuntary manslaughter serves as a fallback charge when murder or voluntary manslaughter evidence is insufficient."}',
  defense_opportunities = '{"Challenge whether the defendant''s conduct was truly reckless versus merely negligent — the distinction determines criminal versus civil liability.","Present evidence that the risk of death was not foreseeable under the circumstances.","Argue that an independent intervening cause broke the chain of causation between the defendant''s actions and the death."}',
  common_defenses = '{"Ordinary negligence — the defendant''s conduct was careless but did not constitute the gross recklessness required for criminal liability.","Unforeseeable result — the death was not a foreseeable consequence of the defendant''s actions.","Intervening cause — an independent event or the victim''s own actions caused the death.","Accident — the death was a genuine accident without criminal recklessness."}'
WHERE common_charge_slug = 'involuntary-manslaughter' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Medical records documenting the victim''s injuries provide objective evidence of ''serious bodily injury'' (substantial risk of death, protracted impairment).","Victim testimony about the attack, combined with physical evidence, creates a compelling narrative for the jury.","Enhanced penalties apply when the victim is a law enforcement officer, firefighter, or emergency medical worker."}',
  defense_opportunities = '{"Challenge the ''serious bodily injury'' element — argue the injuries did not meet the statutory threshold of substantial risk of death or protracted impairment.","Challenge eyewitness identification and victim credibility, particularly if the assault occurred in chaotic conditions."}',
  common_defenses = '{"Defense of others — defendant intervened to protect a third party from an attack.","Misidentification — defendant was not the person who committed the assault.","Mutual combat — both parties were willing participants in a physical altercation.","Injuries do not meet threshold — the injuries sustained were not ''serious bodily injury'' as defined by statute."}'
WHERE common_charge_slug = 'aggravated-assault' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Victim testimony alone can be sufficient for conviction in simple assault cases.","Photographic evidence of injuries (bruises, cuts, swelling) is compelling and easy to present.","Simple assault is a Class A Misdemeanor (up to 1 year), but prior convictions can enhance sentencing."}',
  defense_opportunities = '{"Challenge the victim''s credibility — inconsistencies in statements, motive to fabricate, or history of false allegations.","Present evidence that the physical contact was accidental or privileged (sports, medical treatment, consensual activity).","Seek dismissal or diversion if the alleged assault involved mutual combat and minor injuries."}',
  common_defenses = '{"Self-defense — defendant responded proportionally to an imminent physical threat.","Consent — the physical contact occurred during a consensual activity.","Accidental contact — the touching was unintentional and not purposeful.","De minimis — the contact was so trivial that it does not warrant criminal prosecution.","False accusation — the alleged victim fabricated the assault."}'
WHERE common_charge_slug = 'simple-assault' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Even minimal physical contact (pushing, grabbing) can support a conviction — no injury is required.","Multiple witnesses to the physical contact, especially in public settings, strengthen the case significantly.","Bodycam or surveillance footage of the incident provides objective evidence of the physical contact."}',
  defense_opportunities = '{"Argue the contact was accidental or incidental in a crowded environment.","Challenge whether the contact was truly ''unprivileged'' — certain contexts (sports, mutual horseplay) imply consent.","Present evidence of self-defense or defense of property.","Argue the contact was so minimal it does not constitute a criminal offense (de minimis defense)."}',
  common_defenses = '{"Self-defense — physical contact was in response to an imminent threat.","Consent — the alleged victim consented to the physical contact.","Accidental — the contact was not intentional.","De minimis — the contact was too trivial to warrant criminal charges."}'
WHERE common_charge_slug = 'battery' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Victim identification of the robber, combined with recovery of stolen property, creates strong evidence.","Surveillance camera footage from retail locations often captures the robbery in progress.","Robbery is a Class A Felony (up to 15 years), giving prosecution significant plea bargaining leverage."}',
  defense_opportunities = '{"Challenge the identification of the defendant as the robber — cross-racial identification, poor lighting, and stress affect eyewitness reliability.","Argue the taking was a theft without force — the defendant took property but did not use or threaten force, reducing the charge to theft.","Challenge whether the force was used ''in the course of'' the theft — force used after the taking may not qualify as robbery.","Present an alibi defense with corroborating evidence (phone records, witnesses, surveillance at another location)."}',
  common_defenses = '{"Misidentification — the defendant was not the person who committed the robbery.","No force or threat — the taking of property occurred without force, making it theft rather than robbery.","Claim of right — defendant had a good faith belief they were entitled to the property.","Alibi — defendant was at a different location when the robbery occurred."}'
WHERE common_charge_slug = 'robbery' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"The mere display of a weapon (even if unloaded or fake) satisfies the ''armed'' element if the victim reasonably believed it was real.","Forensic evidence linking the weapon to the defendant (DNA, fingerprints, ballistics) provides strong physical evidence.","Armed robbery convictions carry significant minimum sentences and collateral consequences."}',
  defense_opportunities = '{"Challenge whether the defendant actually possessed or displayed a weapon during the robbery.","If the weapon was not real (toy gun, imitation), argue for reduction to standard robbery where the law permits.","Challenge the identification evidence, particularly in cases involving disguises or brief encounters.","Argue duress — the defendant was forced to participate in the robbery by a co-defendant."}',
  common_defenses = '{"Misidentification — defendant was not the person who committed the armed robbery.","No weapon — defendant did not possess or display a weapon during the incident.","Duress — defendant was coerced into participating under threat of serious harm.","False accusation — co-defendant or witness is falsely implicating the defendant."}'
WHERE common_charge_slug = 'armed-robbery' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Kidnapping is a Class A Felony (up to 15 years) with potential for extended sentences in cases involving ransom or serious harm.","Victim testimony about the confinement, restraint, and duration is powerful evidence.","Electronic evidence (cell phone location, surveillance footage, GPS data) can corroborate the victim''s account of movement and detention."}',
  defense_opportunities = '{"Challenge the ''purpose'' element — argue the restraint or movement did not serve any of the statutory purposes (ransom, harm, interference).","Argue the movement was incidental to another crime and does not constitute separate kidnapping.","Challenge the victim''s credibility regarding the extent of restraint or the defendant''s intent.","Present evidence that the alleged victim went willingly and was not restrained against their will."}',
  common_defenses = '{"Consent — the alleged victim went with the defendant voluntarily.","No criminal purpose — the restraint or movement did not serve any of the purposes required by the kidnapping statute.","Incidental movement — any movement was merely incidental to another crime and does not support a separate kidnapping charge.","Misidentification — the defendant was not involved in the kidnapping."}'
WHERE common_charge_slug = 'kidnapping' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Fire investigators can determine the origin and cause of a fire, including the use of accelerants, with high reliability.","Insurance records and financial motive evidence (debt, insurance claims) create powerful motive evidence in arson-for-profit cases.","DNA, fingerprints, and surveillance footage at or near the fire scene can link the defendant to the crime."}',
  defense_opportunities = '{"Challenge the fire investigation methodology — argue the fire was accidental (electrical, mechanical, natural) rather than intentionally set.","Retain an independent fire investigation expert to dispute the prosecution''s origin and cause determination.","Challenge the chain of custody for accelerant evidence collected from the scene.","Argue the defendant was present at the scene for innocent reasons unrelated to starting the fire."}',
  common_defenses = '{"Accidental fire — the fire resulted from natural causes, electrical malfunction, or equipment failure.","Misidentification — the defendant did not start the fire.","Faulty investigation — the fire investigator''s methodology was flawed or their conclusions are unreliable.","Lack of intent — the defendant did not knowingly start the fire or cause the explosion."}'
WHERE common_charge_slug = 'arson' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"The victim''s survival allows direct testimony about the attack, providing powerful evidence.","Medical evidence of the injuries (their severity and location) demonstrates intent to kill.","Statements made by the defendant before, during, or after the attack can directly prove intent."}',
  defense_opportunities = '{"Challenge the intent to kill — argue the defendant intended to injure but not to kill, reducing the charge to aggravated assault.","Present evidence of self-defense — the defendant was responding to an imminent threat.","Challenge the identification of the defendant as the attacker."}',
  common_defenses = '{"Lack of intent to kill — defendant intended to harm but not to cause death.","Self-defense — defendant was defending against an imminent threat of death or serious injury.","Voluntary abandonment — defendant voluntarily ceased the attempt before completion.","Misidentification — defendant was not the person who committed the attack."}'
WHERE common_charge_slug = 'attempted-murder' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"The definition of ''deadly weapon'' is broad — any instrument capable of causing death or serious bodily harm in the manner used.","Physical evidence of the weapon (recovery, DNA, fingerprints) combined with victim injuries creates compelling proof.","Medical testimony about the severity of injuries consistent with weapon use strengthens the case."}',
  defense_opportunities = '{"Challenge whether the object used meets the legal definition of a ''deadly weapon'' — context of use matters.","Challenge the victim''s account of the weapon''s use through forensic evidence or witness testimony.","Argue for reduction to simple assault if the weapon evidence is weak."}',
  common_defenses = '{"Self-defense — defendant used the weapon to protect against an imminent threat of serious harm.","Not a deadly weapon — the object used does not qualify as a deadly weapon under the circumstances.","Misidentification — defendant was not the person who committed the assault.","Accidental injury — the weapon was not intentionally used against the victim."}'
WHERE common_charge_slug = 'assault-with-deadly-weapon' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Surveillance footage, possession of stolen property, and witness testimony provide multiple avenues of proof.","Stolen property found in the defendant''s possession creates a rebuttable presumption of theft."}',
  defense_opportunities = '{"Argue claim of right — the defendant had a good faith belief they were entitled to the property.","Challenge the valuation of the property to argue for a lesser grade of offense.","Argue mistaken taking — the defendant took the property by mistake, believing it was their own.","Present evidence that the property was abandoned or given to the defendant."}',
  common_defenses = '{"Claim of right — defendant believed in good faith they had a right to the property.","Mistake — defendant took the wrong item by accident.","Consent — the property owner gave permission for the defendant to take the property.","Abandoned property — the property was abandoned and the defendant reasonably believed it was unclaimed."}'
WHERE common_charge_slug = 'theft-larceny' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Professional appraisals and retail pricing establish the value of stolen property with precision.","For theft of multiple items, aggregation of values can push the total over the felony threshold.","Financial records and forensic accounting can trace stolen funds or property."}',
  defense_opportunities = '{"Challenge the valuation — argue the property''s fair market value is below $1,000, reducing the charge to a misdemeanor.","Argue the property was borrowed with intent to return, negating the ''purpose to deprive'' element.","Challenge whether the prosecution can properly aggregate the value of separately taken items.","Present evidence of claim of right or mistaken ownership."}',
  common_defenses = '{"Valuation dispute — property is worth less than the felony threshold amount.","Claim of right — defendant had a good faith belief they owned the property.","Intent to return — defendant intended to borrow the property temporarily, not deprive the owner permanently.","Mistaken identity — defendant was not the person who took the property."}'
WHERE common_charge_slug = 'grand-theft' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Surveillance footage in retail settings frequently captures the taking with clarity.","Loss prevention officer testimony about observing the theft is typically credible and detailed.","Confession at the scene or during initial questioning is common in petty theft cases."}',
  defense_opportunities = '{"Challenge the intent element — argue the defendant forgot to pay or was distracted.","Challenge the loss prevention officer''s observation — obstructed views, brief timeframes, or confusion with another shopper.","Seek pretrial diversion or alternative resolution, especially for first-time offenders.","Argue the property was already paid for (receipt confusion, self-checkout error)."}',
  common_defenses = '{"Lack of intent — the defendant did not intend to steal (forgot to pay, accidental concealment).","Mistaken identity — defendant was confused with another person.","Already purchased — the item was previously paid for or the defendant believed it was.","De minimis — the value is so small that prosecution is disproportionate."}'
WHERE common_charge_slug = 'petty-theft' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Store surveillance and loss prevention testimony provide direct observation evidence.","Electronic article surveillance (EAS) systems and receipt verification at exits catch shoplifters with physical evidence.","Repeat shoplifting offenders face enhanced penalties under New Hampshire''s habitual offender provisions."}',
  defense_opportunities = '{"Challenge the presumption — argue the concealment was inadvertent (item placed in bag alongside paid items, child placed item in stroller).","Challenge the surveillance evidence — angle, resolution, and continuity of footage may not clearly show concealment.","Argue the defendant intended to pay but was stopped before reaching the register.","Seek restitution-based resolution or diversion program for first offenses."}',
  common_defenses = '{"No intent to steal — defendant planned to pay and had not yet passed all points of sale.","Inadvertent concealment — item was accidentally placed in bag or pocket.","Mistaken identity — loss prevention identified the wrong person.","Payment confusion — defendant believed the item was already paid for or included in another purchase."}'
WHERE common_charge_slug = 'shoplifting' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Forensic evidence (fingerprints, DNA, shoe impressions) at the point of entry directly links the defendant to the scene.","Possession of stolen property from the burglarized premises creates a strong inference of the defendant''s involvement.","Surveillance footage, alarm records, and cellular location data can place the defendant at the scene."}',
  defense_opportunities = '{"Challenge the ''purpose to commit a crime'' element — argue the entry was for an innocent purpose (seeking shelter, confusion about the address).","Challenge the identification evidence linking the defendant to the entry.","Argue authorized entry — the defendant had permission or a reasonable belief they had permission to enter.","Challenge forensic evidence through independent expert analysis."}',
  common_defenses = '{"No criminal purpose — defendant entered the building without intent to commit a crime.","Authorized entry — defendant had permission or believed they had permission to enter.","Misidentification — forensic or eyewitness evidence does not reliably identify the defendant.","Alibi — defendant was elsewhere when the burglary occurred."}'
WHERE common_charge_slug = 'burglary' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Victim impact testimony about the invasion of their home is powerful and generates strong jury sympathy.","Physical evidence from inside the dwelling (fingerprints, DNA, disturbance patterns) specifically connects the defendant to the interior.","The nighttime element increases the perceived danger to occupants, making juries more inclined to convict."}',
  defense_opportunities = '{"Challenge the ''nighttime'' element — if entry occurred outside the statutory nighttime hours, the charge drops to Class B Felony.","Challenge whether the structure qualifies as a ''dwelling'' under the statute.","Present evidence of mistaken address or authorized access to the property.","Challenge the forensic evidence linking the defendant to the interior of the dwelling."}',
  common_defenses = '{"Not a dwelling — the structure does not meet the statutory definition of a dwelling.","Not nighttime — the entry did not occur during nighttime hours as defined by statute.","Authorized access — defendant had permission or a key to the dwelling.","Misidentification — evidence does not reliably place the defendant inside the dwelling."}'
WHERE common_charge_slug = 'residential-burglary' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"VIN tracking, registration records, and LoJack/GPS systems frequently lead to rapid recovery and identification of the thief.","Forensic evidence inside the vehicle (fingerprints, DNA, personal items) directly links the defendant to the theft.","Surveillance footage from parking lots, traffic cameras, and toll systems can track the vehicle''s movement."}',
  defense_opportunities = '{"Argue the defendant had permission to use the vehicle from the owner or a person the defendant believed was the owner.","Challenge the identification of the defendant as the person who took the vehicle.","Argue joyriding (intent to temporarily use, not permanently deprive) which may support a lesser charge.","Present evidence that the defendant purchased the vehicle in good faith and did not know it was stolen."}',
  common_defenses = '{"Permission — defendant had the owner''s consent to use the vehicle.","Mistaken identity — defendant was not the person who took the vehicle.","Joyriding — defendant intended to return the vehicle, negating permanent deprivation intent.","Good faith purchase — defendant acquired the vehicle through what appeared to be a legitimate transaction."}'
WHERE common_charge_slug = 'motor-vehicle-theft' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Purchasing property at far below market value, from an unknown seller, or without documentation creates a strong inference of knowledge.","Recovery of multiple stolen items from the defendant''s possession suggests a pattern of receiving stolen goods.","Statements by co-defendants or the original thief can directly prove the defendant''s knowledge."}',
  defense_opportunities = '{"Challenge the ''knowledge'' element — argue the defendant genuinely did not know the property was stolen.","Present documentation showing a legitimate purchase (receipt, bill of sale, payment records).","Argue the defendant was an innocent recipient who learned the property was stolen only after acquiring it.","Challenge the identification of the property as the specific stolen item."}',
  common_defenses = '{"Lack of knowledge — defendant did not know or have reason to know the property was stolen.","Legitimate purchase — defendant bought the property through normal channels at a reasonable price.","Mistaken identity of property — the property in defendant''s possession is not the stolen item.","Claim of right — defendant believed they had a legitimate claim to the property."}'
WHERE common_charge_slug = 'receiving-stolen-property' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Damage estimates from property owners or professional appraisers establish the value for grading purposes.","Surveillance footage, especially in commercial areas, frequently captures the vandalism.","Value thresholds determine severity: over $1,500 is a Class A Felony; $100-$1,500 is a Class B Felony."}',
  defense_opportunities = '{"Challenge the valuation of the damage to reduce the charge grade.","Argue the damage was accidental, not purposeful or reckless.","Challenge the identification of the defendant as the person who caused the damage.","Argue the defendant had a right to modify the property (tenant, co-owner)."}',
  common_defenses = '{"Accident — the damage was unintentional and not the result of reckless conduct.","Misidentification — defendant was not the person who caused the damage.","Consent or right — defendant had permission or legal authority to alter the property.","Valuation dispute — the actual damage cost is less than alleged, reducing the charge severity."}'
WHERE common_charge_slug = 'vandalism' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Repeat trespassing on the same property after being warned can be enhanced to a Class A Misdemeanor.","Property owner testimony about ''no trespass'' orders and fencing/signage establishes the lack of privilege.","Surveillance footage or witness testimony placing the defendant on the property provides direct evidence."}',
  defense_opportunities = '{"Argue the defendant had a good faith belief they had permission to be on the property.","Challenge whether adequate notice was given — no signs posted, no verbal warning, no fencing.","Argue the property was not clearly marked as private and appeared to be open to the public.","Argue necessity — the defendant entered the property due to an emergency."}',
  common_defenses = '{"Permission — defendant believed they had authorization to be on the property.","Inadequate notice — no signs, warnings, or barriers indicating the property was restricted.","Public access — the property appeared open to the public.","Necessity — defendant entered due to an emergency (weather, medical, safety)."}'
WHERE common_charge_slug = 'trespassing' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Physical evidence of the damage combined with ownership proof provides the core elements.","Professional repair estimates establish the monetary value of the damage for grading purposes.","Witness testimony and surveillance footage often capture the destructive act."}',
  defense_opportunities = '{"Argue the damage was accidental — the defendant did not act purposely or recklessly.","Challenge the repair cost estimates to reduce the charge to a lesser grade.","Present evidence that the defendant was not present when the damage occurred.","Argue the property was jointly owned or the defendant had a right to modify it."}',
  common_defenses = '{"Accident — damage was not intentional or reckless.","Misidentification — defendant was not responsible for the damage.","Ownership or right — defendant had a legal right to the property that was damaged.","Valuation dispute — damage costs are inflated, reducing the offense grade."}'
WHERE common_charge_slug = 'criminal-mischief' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Excited utterance statements (911 calls, initial officer contact) are admissible even if the victim later recants.","Physical evidence (injuries, broken items, displaced furniture) corroborates the victim''s initial account.","Mandatory arrest policies in NH mean officers must arrest the primary aggressor, creating immediate documentation."}',
  defense_opportunities = '{"Challenge the identification of the ''primary aggressor'' — the arrested person may have been the actual victim defending themselves.","Present evidence that the injuries were self-inflicted or caused by an accidental fall.","Challenge recanted statements and highlight the victim''s desire not to prosecute.","Argue mutual combat — both parties engaged in physical contact, and the defendant was not the primary aggressor."}',
  common_defenses = '{"Self-defense — defendant was the actual victim and acted in self-defense.","False accusation — the allegation is fabricated, often in the context of a custody or divorce dispute.","Mutual combat — both parties were equally engaged in the physical altercation.","Accidental injury — the victim''s injuries were caused by accident, not intentional assault."}'
WHERE common_charge_slug = 'domestic-violence' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Evidence-based prosecution (photos, 911 recordings, officer observations) allows cases to move forward despite victim recantation.","Protective orders issued at arrest create additional charges if violated during the case.","Prior domestic violence incidents (even without convictions) may be admissible to show pattern of conduct."}',
  defense_opportunities = '{"Challenge the relationship element — the alleged victim may not qualify as a household member, family member, or intimate partner under the statute.","Present evidence of the victim''s prior false allegations or motive to fabricate.","Argue the physical contact was accidental or resulted from the victim''s own aggressive behavior.","Negotiate for anger management or counseling-based resolutions where appropriate."}',
  common_defenses = '{"Self-defense — defendant was responding to the victim''s physical aggression.","No household member relationship — the parties do not meet the statutory relationship requirement.","False allegation — the victim fabricated the assault for strategic advantage in family court.","Accidental contact — any physical contact was unintentional."}'
WHERE common_charge_slug = 'domestic-battery' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"DCYF (Division for Children, Youth and Families) investigations produce detailed reports that are admissible at trial.","Medical evidence of the child''s condition (malnourishment, untreated injuries, environmental hazards) is compelling.","Testimony from teachers, doctors, neighbors, and family members creates a comprehensive picture of the home environment."}',
  defense_opportunities = '{"Challenge whether the defendant''s conduct actually endangered the child versus was a parenting choice within acceptable bounds.","Present evidence of the defendant''s overall caregiving — one incident does not establish a pattern of endangerment.","Challenge the DCYF investigation process and the reliability of their conclusions.","Argue the endangering condition was temporary and has been fully remediated."}',
  common_defenses = '{"No actual endangerment — the child was not in danger despite the prosecution''s characterization.","Parenting discretion — the defendant''s conduct was a legitimate parenting decision.","Lack of knowledge — defendant was unaware of the dangerous condition.","Remediation — the condition was immediately corrected once discovered."}'
WHERE common_charge_slug = 'child-endangerment' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Medical evidence of injuries inconsistent with accidental causes (patterned bruising, multiple fractures at different healing stages) is devastating.","Expert pediatric testimony about non-accidental trauma carries enormous weight with juries.","Children''s recorded forensic interviews (CAC interviews) provide detailed accounts of abuse."}',
  defense_opportunities = '{"Retain independent medical experts to challenge the prosecution''s injury causation theory — some injuries can have accidental or medical explanations.","Challenge the reliability of the child''s statements — consider suggestibility, coaching, and the forensic interview methodology.","Present evidence of an alternative perpetrator who had access to the child.","Argue the injuries were accidental and consistent with normal childhood activity."}',
  common_defenses = '{"Accidental injury — the child''s injuries resulted from normal childhood activity (falls, play).","Alternative perpetrator — another person with access to the child caused the injuries.","Medical explanation — the injuries have a medical cause (brittle bone disease, bleeding disorder).","Unreliable child statement — the child''s account was influenced by coaching or suggestive interview techniques."}'
WHERE common_charge_slug = 'child-abuse' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"The order itself is documentary evidence that establishes the prohibited conduct with precision.","Electronic evidence (texts, calls, emails, social media contacts) provides objective proof of contact violations.","GPS and cell tower data can prove proximity violations even without direct contact."}',
  defense_opportunities = '{"Challenge whether the defendant was properly served with the protective order.","Argue the contact was initiated by the protected person, not the defendant.","Challenge the scope of the order — argue the defendant''s conduct was not actually prohibited by the specific terms.","Present evidence that the alleged violation was accidental (inadvertent encounter at public location)."}',
  common_defenses = '{"No service — defendant was never properly served with the protective order.","Victim-initiated contact — the protected person initiated the contact.","Accidental encounter — defendant was in a public place and the encounter was coincidental.","Outside scope — the defendant''s conduct was not covered by the specific terms of the order."}'
WHERE common_charge_slug = 'violation-protective-order' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Electronic evidence (texts, emails, social media, location tracking) comprehensively documents the pattern of unwanted contact.","Victim testimony about fear and disruption to daily life is powerful and sympathetic.","Enhanced penalties apply for stalking in violation of a protective order."}',
  defense_opportunities = '{"Challenge the ''reasonable fear'' element — argue the conduct would not cause a reasonable person to fear for their safety.","Argue the contacts were for legitimate purposes (co-parenting communication, business matters).","Challenge whether the conduct constitutes a ''course of conduct'' or was isolated incidents.","Present evidence that the alleged victim encouraged or welcomed some of the contacts."}',
  common_defenses = '{"Legitimate purpose — contacts were made for lawful reasons (custody communication, business).","No reasonable fear — the conduct would not cause a reasonable person to feel afraid.","Isolated incidents — the conduct does not form a course of conduct as required by statute.","Consent — the alleged victim was a willing participant in the communications."}'
WHERE common_charge_slug = 'stalking' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Repeated phone calls, texts, and electronic communications are easily documented and provide objective evidence.","Victim testimony about the emotional impact of the harassment is sympathetic.","Prior incidents between the parties can establish pattern and intent."}',
  defense_opportunities = '{"Challenge the intent element — argue the defendant did not intend to annoy, alarm, or harass.","Assert First Amendment protections — protected speech cannot be criminalized even if offensive.","Argue the communication had a legitimate purpose and was not mere harassment.","Challenge whether the conduct actually meets the statutory definition."}',
  common_defenses = '{"Free speech — the defendant''s communication is protected by the First Amendment.","No intent to harass — defendant''s conduct was not intended to annoy or alarm.","Legitimate purpose — communications were for a lawful reason (dispute resolution, debt collection).","De minimis — the conduct is too trivial to warrant criminal prosecution."}'
WHERE common_charge_slug = 'harassment' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Medical evidence of the victim''s deteriorating condition while in the defendant''s care is compelling.","Financial records showing exploitation (unauthorized withdrawals, property transfers) provide clear documentary proof.","Adult Protective Services reports and expert testimony about the standard of care expected."}',
  defense_opportunities = '{"Challenge the caregiver relationship — argue the defendant was not responsible for the victim''s care.","Present evidence that the victim''s condition was caused by their own decisions or pre-existing medical conditions.","Challenge the definition of ''neglect'' — argue the care provided was adequate under the circumstances.","Present evidence of the victim''s autonomy and decision-making capacity (they chose their own care)."}',
  common_defenses = '{"Not a caregiver — defendant was not responsible for the victim''s care.","Adequate care — the care provided met reasonable standards under the circumstances.","Victim autonomy — the elderly person made their own decisions about their care and lifestyle.","Pre-existing condition — the victim''s condition resulted from prior medical issues, not the defendant''s neglect."}'
WHERE common_charge_slug = 'elder-abuse' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Physical evidence (the firearm itself, ammunition, location of seizure) provides strong proof.","New Hampshire is a constitutional carry state, but prohibited places and prohibited persons restrictions still apply.","Statements made at the time of seizure about ownership and awareness of the weapon are frequently obtained."}',
  defense_opportunities = '{"Argue the defendant did not know the firearm was loaded.","Challenge the search or seizure that led to discovery of the weapon.","New Hampshire''s strong Second Amendment traditions may influence jury disposition."}',
  common_defenses = '{"Not a prohibited circumstance — the defendant was lawfully carrying under New Hampshire''s constitutional carry law.","Lack of knowledge — defendant did not know the weapon was loaded or present.","Illegal search — the weapon was discovered through an unconstitutional search.","Not a firearm — the object does not meet the statutory definition."}'
WHERE common_charge_slug = 'weapons-possession' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"The prior conviction is a matter of public record and easily proved.","Constructive possession (firearm found in defendant''s residence or vehicle) is sufficient for conviction.","This is a Class B Felony (up to 7 years) with potential for extended terms."}',
  defense_opportunities = '{"Challenge constructive possession — argue the firearm belonged to another person in the shared space.","Argue the prior conviction has been annulled or pardoned, restoring firearm rights.","Challenge the search that led to the discovery of the firearm."}',
  common_defenses = '{"No qualifying conviction — the prior offense does not meet the predicate requirements.","Not in possession — the firearm belonged to another person and the defendant did not control it.","Annulment or pardon — the prior conviction has been annulled, restoring firearm rights.","Illegal search — the firearm was discovered through an unconstitutional search."}'
WHERE common_charge_slug = 'felon-in-possession' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Signage and posted notices at prohibited locations establish the defendant''s notice.","Security personnel testimony about discovering the weapon at a prohibited location is straightforward.","The weapon itself is physical evidence directly linking the defendant to the offense."}',
  defense_opportunities = '{"Argue the defendant was unaware they had entered a prohibited area.","Challenge the signage or notice — inadequate posting may negate the knowledge element.","Argue the defendant was in the process of lawfully transporting the weapon and made a brief stop."}',
  common_defenses = '{"Not a prohibited place — the location does not qualify as a restricted area under the statute.","Lack of notice — no signs or warnings indicated the location prohibited firearms.","Transient presence — defendant briefly entered the restricted area while in transit.","Lack of knowledge — defendant did not realize the weapon was on their person."}'
WHERE common_charge_slug = 'concealed-carry-violation' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Physical evidence (spent casings, bullet damage, residue) proves the discharge occurred.","Witness testimony about hearing gunfire and observing the discharge is common.","Property damage from the discharge provides additional evidence and potential charges."}',
  defense_opportunities = '{"Challenge the proximity measurement — argue the discharge occurred outside the prohibited distance.","Argue the discharge was justified (self-defense, defense of property against animal threat).","Challenge whether the area qualifies as a ''compact area'' under the statute.","Argue the defendant was on their own rural property with no buildings within the prohibited distance."}',
  common_defenses = '{"Adequate distance — discharge occurred outside the statutorily prohibited distance from buildings or highways.","Self-defense — discharge was necessary to protect against an imminent threat.","Defense of property — discharge was to protect livestock or property from animal predation.","Not a compact area — the location was rural and did not meet the statutory definition."}'
WHERE common_charge_slug = 'illegal-discharge' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Financial records showing unauthorized transactions in the victim''s name create clear documentary evidence.","IP addresses, device identifiers, and account access logs can link the defendant to the fraudulent activity.","Identity theft investigations often reveal multiple victims, increasing the charges and sentencing exposure."}',
  defense_opportunities = '{"Challenge the identification of the defendant as the person who used the victim''s information — someone else may have used the defendant''s devices.","Argue the defendant had authorization from the victim to use their information.","Challenge the forensic evidence linking the defendant to the fraudulent transactions.","Argue the defendant was a victim of identity theft themselves and did not knowingly use another''s information."}',
  common_defenses = '{"Authorization — the victim gave the defendant permission to use their information.","Mistaken identity — someone else used the defendant''s devices or accounts to commit the fraud.","Lack of fraudulent purpose — the defendant used the information for a non-fraudulent purpose.","Defendant was also a victim — the defendant''s identity was compromised and used by a third party."}'
WHERE common_charge_slug = 'identity-theft' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Employment records, financial access logs, and internal controls documentation establish the defendant''s position of trust.","Pattern evidence (systematic small diversions over time) demonstrates intent rather than mistake.","Cooperating witnesses from the organization provide insider knowledge of the scheme."}',
  defense_opportunities = '{"Argue the defendant had authorization for the transactions — what appears to be embezzlement may have been approved compensation or reimbursement.","Challenge the forensic accounting methodology — errors in accounting can create false appearances of theft.","Present evidence that the funds were intended as a loan to be repaid.","Challenge the valuation to reduce the charge grade."}',
  common_defenses = '{"Authorization — the defendant was authorized to make the transactions in question.","Accounting error — the discrepancy results from bookkeeping errors, not theft.","Intent to repay — the defendant treated the funds as a temporary loan.","Claim of right — the defendant believed they were entitled to the funds (unpaid wages, bonuses)."}'
WHERE common_charge_slug = 'embezzlement' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Comparison of genuine signatures and handwriting with the forged document provides expert testimony.","Financial gain from the forged document traces directly to the defendant.","Digital forensics can identify the creation of forged electronic documents."}',
  defense_opportunities = '{"Challenge the document examiner''s conclusions — handwriting analysis has known limitations in reliability.","Argue authorization — the defendant was authorized to sign on behalf of the person whose signature was used.","Challenge the ''intent to defraud'' element — the document was created for a non-fraudulent purpose.","Argue the document is genuine and the expert''s opinion is incorrect."}',
  common_defenses = '{"Authorization — defendant had permission to sign the document on another''s behalf.","No fraudulent intent — the document was not created for fraudulent purposes.","Genuine document — the writing is authentic, not forged.","Mistaken attribution — someone else created the forged document."}'
WHERE common_charge_slug = 'forgery' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Secret Service involvement in currency cases brings federal forensic resources and expertise.","The quantity of counterfeit items seized demonstrates the scale of the operation.","Expert testimony on the counterfeit nature of the items is highly persuasive."}',
  defense_opportunities = '{"Argue the defendant did not know the items were counterfeit — particularly for currency received in transactions.","Challenge the identification of the defendant as the person who created or distributed the counterfeit items.","Argue the items were novelty or theatrical props not intended for fraudulent use.","Challenge the chain of custody of the seized counterfeit items."}',
  common_defenses = '{"Lack of knowledge — defendant did not know the items were counterfeit.","Novelty items — the items were clearly marked as novelty or were not intended to deceive.","Mistaken identity — defendant was not the person who created or distributed the counterfeits.","No intent to defraud — the items were possessed for a non-fraudulent purpose."}'
WHERE common_charge_slug = 'counterfeiting' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Bank records objectively prove the account balance was insufficient at the time the check was written.","The check itself is physical evidence with the defendant''s signature and account information.","Pattern evidence of multiple bad checks demonstrates intent rather than oversight."}',
  defense_opportunities = '{"Argue the defendant genuinely believed funds were available when the check was written.","Argue a bank error or timing issue caused the check to bounce (deposit was pending).","Challenge whether proper notice of dishonor was sent to the defendant."}',
  common_defenses = '{"Good faith belief — defendant reasonably believed sufficient funds were available.","Timely cure — defendant made the check good within 14 days of notice.","Bank error — the insufficient funds resulted from a bank processing error.","No notice — defendant did not receive proper notice of dishonor."}'
WHERE common_charge_slug = 'bad-checks' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Surveillance evidence contradicting claimed injuries or losses is devastating to the defendant''s credibility.","Expert testimony from medical professionals, engineers, or appraisers can debunk fraudulent claims.","Digital evidence (social media posts contradicting claimed limitations) is increasingly used."}',
  defense_opportunities = '{"Argue the claim was made in good faith based on the defendant''s honest understanding of their loss or injury.","Challenge the surveillance interpretation — brief moments of activity do not disprove legitimate injuries.","Present independent medical evidence supporting the claimed injuries or conditions.","Argue miscommunication between the defendant and their insurance agent led to inaccuracies."}',
  common_defenses = '{"Good faith claim — the defendant genuinely believed their claim was accurate.","Agent error — the insurance agent or adjuster incorrectly documented the defendant''s statements.","Legitimate injury — the medical condition is real despite what surveillance appears to show.","No material misrepresentation — any inaccuracy in the claim was not material to the coverage decision."}'
WHERE common_charge_slug = 'insurance-fraud' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Security cameras at point-of-sale locations frequently capture the person using the card.","IP addresses and device fingerprints link online transactions to the defendant''s devices.","The card owner''s testimony about not authorizing the transactions is straightforward."}',
  defense_opportunities = '{"Argue the cardholder authorized the defendant to use the card.","Challenge the identification of the defendant as the person who conducted the transactions.","Argue the defendant found the card and used it without understanding the legal consequences (reduces culpability).","Challenge the forensic evidence linking specific online transactions to the defendant."}',
  common_defenses = '{"Authorization — the cardholder gave permission to use the card.","Mistaken identity — someone else used the card, not the defendant.","Lack of fraudulent intent — defendant believed they had authorization.","Card found — defendant found an abandoned card and did not intend to defraud the owner."}'
WHERE common_charge_slug = 'credit-card-fraud' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Structured transactions (under $10,000 to avoid reporting) are themselves evidence of concealment intent.","Cooperating witnesses from the drug operation can testify about the flow of proceeds.","Federal-state cooperation brings additional investigative resources and expertise."}',
  defense_opportunities = '{"Challenge the link between the money and the alleged criminal activity — the funds may have legitimate sources.","Argue the defendant did not know the money was proceeds of drug activity.","Challenge the financial analysis methodology used to trace the funds.","Argue the transactions had legitimate business purposes."}',
  common_defenses = '{"Legitimate source — the funds came from lawful income or business activity.","Lack of knowledge — defendant did not know the funds were drug proceeds.","No concealment intent — the financial transactions were for normal business purposes.","Faulty financial analysis — the prosecution''s money trail is based on flawed assumptions."}'
WHERE common_charge_slug = 'money-laundering' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Documentary evidence (emails, contracts, advertisements) showing the false representations is compelling.","Financial records showing the flow of money from victim to defendant trace the fraud.","Pattern evidence of multiple victims demonstrates a scheme rather than a misunderstanding."}',
  defense_opportunities = '{"Argue the representations were truthful or were matters of opinion, not factual misstatements.","Challenge the victim''s reliance — argue they did not actually rely on the defendant''s representations.","Present evidence that the defendant intended to fulfill promises but was unable to due to circumstances beyond their control.","Argue the transaction was a legitimate business deal that went wrong, not a fraud."}',
  common_defenses = '{"Truthful representations — the defendant''s statements were accurate or were opinions.","Good faith — defendant genuinely intended to deliver what was promised.","No reliance — the victim did not actually rely on the defendant''s statements.","Business dispute — the matter is a civil contract dispute, not criminal fraud."}'
WHERE common_charge_slug = 'fraud-general' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"DNA evidence from sexual assault kits provides powerful physical evidence linking the defendant to the victim.","SANE (Sexual Assault Nurse Examiner) testimony about injuries consistent with assault corroborates the victim''s account.","Prompt outcry testimony (the victim''s first report to someone) is admissible in New Hampshire."}',
  defense_opportunities = '{"Challenge the DNA evidence — argue contamination, secondary transfer, or that the DNA proves contact but not the specific conduct alleged.","Present evidence of consent — the sexual contact was consensual.","Challenge the victim''s identification of the defendant, particularly in cases involving strangers or altered consciousness.","Retain independent forensic experts to analyze the physical evidence."}',
  common_defenses = '{"Consent — the sexual contact was consensual between adults.","Misidentification — the defendant was not the person who committed the assault.","False accusation — the allegation is fabricated due to a personal motive.","Insufficient evidence — the physical evidence does not support the specific conduct alleged."}'
WHERE common_charge_slug = 'sexual-assault' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"DNA evidence, SANE examinations, and toxicology results provide comprehensive physical evidence.","Victim testimony about force, coercion, or incapacity is supported by medical findings.","New Hampshire has no statute of limitations for sexual assault, allowing prosecution at any time."}',
  defense_opportunities = '{"Challenge the forensic evidence — DNA proves contact but not the nature of that contact (consensual vs. non-consensual).","Present evidence of prior consensual sexual relationship between the parties.","Challenge the victim''s account through inconsistencies in statements or physical evidence that contradicts the allegations.","Challenge the toxicology evidence if incapacity is alleged — argue the defendant did not know the victim was incapacitated."}',
  common_defenses = '{"Consent — the sexual contact was consensual.","Misidentification — the defendant was not the perpetrator.","False accusation — the allegation is fabricated, often motivated by personal conflict.","No knowledge of incapacity — the defendant did not know and could not reasonably have known the victim was incapacitated."}'
WHERE common_charge_slug = 'rape' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Multiple witness accounts corroborating the exposure strengthen the case significantly.","Surveillance footage in public areas may capture the exposure.","Prior similar incidents are admissible to show pattern and intent."}',
  defense_opportunities = '{"Argue the exposure was accidental (wardrobe malfunction, emergency urination out of view).","Challenge the witness identifications — distance, lighting, and brief duration affect reliability.","Argue the exposure occurred in a place with a reasonable expectation of privacy.","Challenge the ''purpose to arouse or alarm'' element — accidental exposure lacks the required intent."}',
  common_defenses = '{"Accidental exposure — the exposure was unintentional (clothing malfunction).","Privacy — the exposure occurred in a location where the defendant had a reasonable expectation of privacy.","No sexual purpose — the exposure was not motivated by sexual arousal or intent to alarm.","Misidentification — the defendant was not the person who committed the exposure."}'
WHERE common_charge_slug = 'indecent-exposure' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Electronic communications (texts, online posts, app messages) document the solicitation explicitly.","GPS and cell phone records place the defendant at known prostitution locations at relevant times.","Repeat offense enhancements increase penalties for subsequent violations."}',
  defense_opportunities = '{"Argue entrapment — law enforcement initiated the contact and the defendant was not predisposed to commit the offense.","Challenge the interpretation of communications — argue the messages were not soliciting prostitution.","Challenge the identification of the defendant, particularly in online or anonymous contact cases.","Argue the encounter was consensual non-commercial sexual activity."}',
  common_defenses = '{"Entrapment — law enforcement induced the defendant to commit an offense they would not have otherwise committed.","No agreement — the communications did not amount to an agreement to exchange money for sexual services.","Misidentification — the defendant was not the person who made the solicitation.","Ambiguous communication — the messages do not clearly reference commercial sex."}'
WHERE common_charge_slug = 'solicitation-prostitution' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Hash value matching (NCMEC database) definitively identifies known CSAM files found on the defendant''s devices.","IP address and account information link the defendant''s online activity to the illegal material.","Metadata from files (creation date, GPS coordinates, device identifiers) provides additional linking evidence."}',
  defense_opportunities = '{"Challenge the search warrant for the defendant''s devices — constitutional violations can suppress all digital evidence.","Argue the defendant did not knowingly possess the material — it may have been automatically downloaded or planted by malware.","Challenge the forensic examination methodology and chain of custody of digital evidence.","Argue the images do not depict actual minors or do not meet the statutory definition of prohibited material."}',
  common_defenses = '{"Unknowing possession — the material was downloaded automatically through malware or pop-ups without the defendant''s knowledge.","Invalid search warrant — the warrant to search devices was based on insufficient probable cause.","Not a minor — the images do not depict actual minors.","Third-party access — someone else used the defendant''s devices or internet connection."}'
WHERE common_charge_slug = 'child-exploitation' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Registration records maintained by the state provide clear evidence of non-compliance.","The registration requirement and its terms are communicated in writing to the offender at sentencing.","Law enforcement verification checks create a paper trail of non-compliance."}',
  defense_opportunities = '{"Argue the defendant attempted to register but was prevented by administrative obstacles.","Challenge whether the defendant received adequate notice of registration requirements or changes to requirements.","Argue a change in the registration law retroactively imposed new requirements the defendant was unaware of.","Present evidence that the failure was due to homelessness or inability to maintain a stable address."}',
  common_defenses = '{"Attempted compliance — defendant tried to register but was turned away or encountered administrative barriers.","Lack of notice — defendant was not informed of registration requirements or changes.","Homelessness — inability to register a fixed address made compliance impossible.","Constitutional challenge — retroactive application of new registration requirements violates ex post facto protections."}'
WHERE common_charge_slug = 'failure-to-register' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Consent is not a defense — the statute criminalizes sexual contact with persons below the age of consent regardless of willingness.","Electronic communications between the defendant and the minor frequently contain incriminating statements.","DNA evidence and SANE examinations provide physical proof of sexual contact."}',
  defense_opportunities = '{"Challenge the defendant''s knowledge of the victim''s age — though this defense has limited applicability in NH.","Present evidence that no sexual contact occurred despite the relationship.","Challenge the forensic evidence and its interpretation.","Argue the close-in-age exception if applicable under New Hampshire''s law."}',
  common_defenses = '{"No sexual contact — the defendant and the minor did not engage in sexual conduct.","Age defense — the defendant reasonably believed the victim was of legal age (limited applicability).","Misidentification — the defendant is not the person who had sexual contact with the minor.","Close-in-age — the age difference falls within any applicable Romeo and Juliet exception."}'
WHERE common_charge_slug = 'statutory-rape' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Officer testimony about the defendant''s behavior and its effect on public order is typically given significant weight.","Multiple witness accounts corroborating the disorderly behavior strengthen the case.","Video evidence from body cameras or bystander phones captures the conduct in real time."}',
  defense_opportunities = '{"Assert First Amendment protections — mere loud speech or protest activity is constitutionally protected.","Challenge whether the conduct actually created a ''hazardous or physically offensive condition'' as required.","Argue the officer''s subjective determination that the conduct was disorderly was unreasonable.","Present evidence that the defendant''s behavior was a reasonable response to provocation."}',
  common_defenses = '{"Free speech — the defendant''s conduct was protected expression under the First Amendment.","Not disorderly — the conduct did not create a hazardous or physically offensive condition.","Provocation — the defendant was responding to provocative conduct by others.","Officer overreaction — the arrest was based on the officer''s subjective annoyance, not objective disorderly conduct."}'
WHERE common_charge_slug = 'disorderly-conduct' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Bodycam footage captures the physical interaction in detail, providing objective evidence.","Officer testimony about the resistance and the injuries sustained is persuasive.","Resisting arrest is frequently charged alongside the underlying offense, increasing total exposure."}',
  defense_opportunities = '{"Challenge whether the underlying arrest was lawful — resistance to an unlawful arrest may not be criminal in NH.","Argue the defendant''s actions were involuntary reflexive responses, not deliberate resistance.","Challenge the officer''s characterization of the defendant''s behavior — passive non-compliance may not constitute ''resistance.''","Present evidence of excessive force by the officer that provoked the defendant''s physical reaction."}',
  common_defenses = '{"Unlawful arrest — the underlying arrest was without probable cause, making resistance justified.","Involuntary reaction — the defendant''s physical movements were reflexive, not intentional resistance.","Excessive force — the officer used disproportionate force that provoked a defensive response.","Passive non-compliance — the defendant did not actively resist but merely failed to assist."}'
WHERE common_charge_slug = 'resisting-arrest' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Bodycam and surveillance footage often captures the obstructive conduct.","Witness testimony from officers and other government officials about the interference is credible.","Obstruction charges are frequently added to other charges, creating plea negotiation leverage."}',
  defense_opportunities = '{"Argue the defendant''s conduct did not actually obstruct any government function.","Assert First Amendment protections — verbal protests and criticism of officers are protected speech.","Challenge whether the government function being ''obstructed'' was being lawfully conducted.","Argue the defendant was exercising a legal right (filming police, declining consent to search)."}',
  common_defenses = '{"No obstruction — the defendant''s conduct did not actually interfere with any government function.","Exercising legal rights — the defendant was exercising constitutional rights (filming, refusing consent).","Free speech — verbal criticism or protests directed at officers are protected.","Unlawful government action — the official conduct being obstructed was itself unlawful."}'
WHERE common_charge_slug = 'obstruction-justice' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Court records and transcripts objectively document the contemnor''s conduct.","The judge''s direct observation of the contemptuous behavior eliminates witness credibility issues.","Both criminal and civil contempt are available, with different burdens and remedies."}',
  defense_opportunities = '{"Challenge whether the conduct actually constitutes contempt versus vigorous advocacy or protected speech.","Argue the court order that was violated was ambiguous, unconstitutional, or improperly issued.","Present evidence of good faith compliance efforts despite the alleged violation.","Argue inability to comply — the defendant could not perform what the court ordered."}',
  common_defenses = '{"Ambiguous order — the court order was unclear and the defendant''s interpretation was reasonable.","Inability to comply — the defendant was unable to perform what was ordered.","Good faith effort — the defendant made genuine efforts to comply with the order.","Protected conduct — the alleged contempt was protected advocacy or speech."}'
WHERE common_charge_slug = 'contempt-of-court' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Public intoxication is a violation (not a crime) in NH, meaning the standard of proof may be lower for disposition.","Bodycam footage objectively documents the defendant''s condition.","Repeat intoxication incidents can support intervention through the drug courts."}',
  defense_opportunities = '{"Argue the defendant was not intoxicated — signs attributed to intoxication had medical explanations.","Challenge whether the defendant was in a ''public place'' as defined by the statute.","Argue the defendant was in the process of getting home safely (walking from a bar, waiting for a ride).","Present medical evidence of a condition that mimics intoxication (diabetes, neurological conditions)."}',
  common_defenses = '{"Medical condition — symptoms attributed to intoxication were caused by a medical condition.","Not public — the defendant was in a private location, not a public place.","Not intoxicated — the defendant was not actually intoxicated despite the officer''s observations.","Seeking safety — the defendant was in the process of traveling home safely."}'
WHERE common_charge_slug = 'public-intoxication' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Bail conditions signed by the defendant establish knowledge of the court date.","The failure to appear itself creates a presumption of flight risk, making bail on new charges more difficult.","FTA charges are easily proved and provide additional leverage for plea negotiations on the underlying case."}',
  defense_opportunities = '{"Present evidence of a legitimate reason for missing the appearance (medical emergency, incarceration in another jurisdiction, natural disaster).","Argue the defendant did not receive adequate notice of the court date, particularly if the date was changed.","Show the defendant voluntarily surrendered promptly after learning of the missed appearance.","Challenge whether the defendant was actually required to appear (clerical error in scheduling)."}',
  common_defenses = '{"Legitimate excuse — medical emergency, incarceration elsewhere, or emergency prevented appearance.","Lack of notice — defendant was not properly notified of the court date.","Prompt surrender — defendant voluntarily turned themselves in as soon as they learned of the missed date.","Scheduling error — the court date was changed and the defendant was not informed."}'
WHERE common_charge_slug = 'failure-to-appear' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Resource expenditure by law enforcement investigating the false report demonstrates the harm caused.","Inconsistencies between the defendant''s report and objective evidence (surveillance, forensics, witnesses) prove the falsity.","Motive evidence (insurance fraud, revenge, alibi creation) strengthens the case."}',
  defense_opportunities = '{"Argue the defendant genuinely believed their report was true — mistake or misperception is not a false report.","Challenge the prosecution''s evidence that the report was false — the underlying facts may be disputed.","Argue the defendant reported accurately but some details were confused due to stress or trauma.","Present evidence of the defendant''s state of mind at the time of the report."}',
  common_defenses = '{"Good faith belief — the defendant genuinely believed the information they reported was true.","Confusion — the defendant was mistaken about details due to stress, trauma, or confusion.","Report was accurate — the prosecution has not established that the report was actually false.","No intent to deceive — the defendant did not intend to mislead law enforcement."}'
WHERE common_charge_slug = 'false-report' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Text messages, voicemails, social media posts, and recorded statements provide objective evidence of the threat.","Context evidence (prior conflicts, escalating behavior, weapon access) makes the threat more credible.","Multiple victims or repeated threats demonstrate a pattern that supports the charges."}',
  defense_opportunities = '{"Argue the statement was protected speech — not a ''true threat'' under constitutional standards.","Challenge whether the statement was actually threatening versus venting, joking, or hyperbolic.","Present context showing the recipient would not reasonably have felt threatened.","Argue the threat was conditional and the condition was lawful (e.g., ''I''ll sue you if you don''t pay'')."}',
  common_defenses = '{"Protected speech — the statement was not a ''true threat'' and is protected by the First Amendment.","Not threatening — the statement was a joke, hyperbole, or expression of frustration, not a genuine threat.","No reasonable fear — a reasonable person in the recipient''s position would not have been afraid.","Conditional statement — the statement was a conditional warning about lawful action."}'
WHERE common_charge_slug = 'criminal-threat' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Objective evidence contradicting the sworn statement (documents, forensics, other testimony) proves the falsity.","The materiality element is often clear — the false statement was on a point that mattered to the proceeding.","Prior inconsistent statements by the defendant provide direct proof of knowing falsity."}',
  defense_opportunities = '{"Argue the statement was literally true even if misleading — perjury requires an actually false statement.","Challenge the materiality — argue the false statement was not material to the proceeding.","Argue confusion or misunderstanding of the question — the defendant did not intentionally lie.","Present evidence that the defendant believed their statement was true at the time."}',
  common_defenses = '{"Literally true — the statement, while possibly misleading, was technically accurate.","Not material — the false statement was not material to the proceeding.","Mistake or confusion — the defendant misunderstood the question or was confused about the facts.","Good faith belief — the defendant genuinely believed the statement was true."}'
WHERE common_charge_slug = 'perjury' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Financial records tracing payments to public officials provide documentary proof.","Cooperating witnesses who participated in the bribery scheme provide insider testimony.","Official actions taken after the bribe payment create circumstantial evidence of the corrupt agreement."}',
  defense_opportunities = '{"Argue the payment was a lawful campaign contribution, gift, or business transaction, not a bribe.","Challenge the cooperating witness''s credibility — they are testifying to receive favorable treatment.","Argue the defendant did not intend to influence official action — the payment was for unrelated services.","Challenge the wiretap or undercover operation for legal and procedural deficiencies."}',
  common_defenses = '{"Lawful payment — the payment was a legitimate campaign contribution, gift, or business transaction.","No corrupt intent — the defendant did not intend the payment to influence official action.","Entrapment — law enforcement induced the defendant to participate in a bribery scheme.","Unreliable cooperator — the cooperating witness fabricated or exaggerated the bribery allegations."}'
WHERE common_charge_slug = 'bribery' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Surveillance footage from the correctional facility captures the escape in progress.","The fact of escape is often undisputed — the defendant was in custody and then was not.","Additional charges may apply for any offenses committed during the escape."}',
  defense_opportunities = '{"Argue duress — the defendant escaped to avoid imminent threats to their life or safety within the facility.","Challenge whether the defendant was actually in ''official custody'' at the time (e.g., released on their own recognizance).","Argue the defendant promptly returned to custody, demonstrating lack of intent to permanently evade.","Present evidence of conditions in the facility that motivated the escape (threats, abuse)."}',
  common_defenses = '{"Duress — defendant faced imminent threats to life or safety that compelled the escape.","Not in custody — defendant was not in lawful custody at the time of the alleged escape.","Prompt return — defendant voluntarily returned to custody, negating intent to permanently evade.","Conditions defense — intolerable conditions in the facility necessitated the escape for survival."}'
WHERE common_charge_slug = 'escape-custody' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Photographic and video evidence of the animal''s condition at the time of rescue is emotionally compelling.","Animal control records documenting the history of conditions at the defendant''s property establish a pattern.","Public sympathy for animal cruelty victims increases the likelihood of conviction."}',
  defense_opportunities = '{"Argue the defendant was unaware of the animal''s condition due to absence, delegation of care to another person, or mental health issues.","Present evidence that the animal''s condition was caused by illness or injury, not neglect or abuse.","Challenge the veterinary expert''s conclusions with independent veterinary testimony.","Argue cultural or agricultural practices that are lawful under NH law (farm animal husbandry)."}',
  common_defenses = '{"Lack of knowledge — defendant was unaware of the animal''s deteriorating condition.","Medical cause — the animal''s condition resulted from illness or genetic condition, not abuse.","Proper care — defendant provided adequate food, shelter, and medical care.","Agricultural exemption — the conduct is within accepted animal husbandry practices."}'
WHERE common_charge_slug = 'animal-cruelty' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Probation officer testimony about the violation and the defendant''s overall compliance history carries significant weight.","Drug test results, missed appointments, and new arrests provide objective evidence of violations.","The original sentence can be imposed upon revocation, giving the court substantial sentencing authority."}',
  defense_opportunities = '{"Present evidence of substantial compliance with probation terms despite the alleged violation.","Argue the violation was minor and technical, not warranting revocation.","Present evidence of circumstances that made compliance impossible (homelessness, medical emergency, transportation issues).","Negotiate for graduated sanctions or modified conditions rather than revocation."}',
  common_defenses = '{"Substantial compliance — defendant has largely followed probation conditions and the violation was minor.","Inability to comply — circumstances beyond the defendant''s control prevented compliance.","Technical violation — the violation was minor and does not warrant revocation.","Inaccurate report — the probation officer''s report of the violation is incorrect."}'
WHERE common_charge_slug = 'probation-violation' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Parole officer testimony and documentation of violations are the primary evidence.","GPS monitoring data, drug tests, and curfew violations provide objective evidence.","New criminal conduct while on parole is particularly strong grounds for revocation."}',
  defense_opportunities = '{"Present evidence of overall compliance and rehabilitation progress despite the alleged violation.","Challenge the factual basis for the violation — was the positive drug test accurate? Was the GPS data reliable?","Argue circumstances that made compliance impossible or extremely difficult.","Seek graduated sanctions or modified conditions as an alternative to revocation."}',
  common_defenses = '{"Substantial compliance — defendant has largely complied with parole conditions.","Inaccurate evidence — drug test results or GPS data are unreliable.","Circumstances beyond control — compliance was impossible due to external factors.","Rehabilitation progress — defendant has made significant progress and revocation would be counterproductive."}'
WHERE common_charge_slug = 'parole-violation' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Evidence of planning, assistance, or encouragement (communications, actions) establishes accomplice liability.","Co-defendant testimony about the defendant''s role in the crime is a primary prosecution tool.","The defendant''s conduct before, during, and after the crime can all demonstrate aiding and abetting."}',
  defense_opportunities = '{"Argue mere presence at the scene — being present during a crime does not establish accomplice liability without active participation.","Challenge the co-defendant''s testimony — they have incentive to minimize their own role and exaggerate the defendant''s involvement.","Argue the defendant withdrew from the criminal enterprise before the crime was completed.","Challenge the evidence of intent — argue the defendant did not know a crime was being planned or committed."}',
  common_defenses = '{"Mere presence — defendant was present but did not actively participate in or encourage the crime.","Withdrawal — defendant withdrew from the criminal plan before the crime was committed.","Lack of knowledge — defendant did not know criminal activity was planned or occurring.","Unreliable co-defendant testimony — the testifying co-defendant is fabricating or exaggerating the defendant''s role."}'
WHERE common_charge_slug = 'aiding-abetting' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Evidence of planning, preparation, and the substantial step taken provides a narrative of intent and action.","Attempt carries the same penalty as the completed offense in many cases, giving prosecution significant leverage.","Statements made by the defendant about their intentions are direct evidence of criminal purpose."}',
  defense_opportunities = '{"Challenge whether the defendant''s actions constituted a ''substantial step'' — mere preparation is not attempt.","Challenge the intent element — argue the defendant never actually intended to complete the crime.","Argue the actions were equivocal and do not strongly corroborate criminal purpose."}',
  common_defenses = '{"No substantial step — the defendant''s actions were mere preparation, not a step strongly corroborative of criminal intent.","Voluntary abandonment — the defendant voluntarily and completely renounced the criminal purpose.","No intent — the defendant did not actually intend to commit the underlying crime.","Impossibility — the crime was impossible to complete under the circumstances (limited applicability in NH)."}'
WHERE common_charge_slug = 'attempt' AND jurisdiction = 'NH';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Communications between co-conspirators (texts, calls, meetings) document the agreement.","Co-conspirator statements made in furtherance of the conspiracy are admissible against all members.","Each member of the conspiracy is liable for reasonably foreseeable acts of other members."}',
  defense_opportunities = '{"Challenge the existence of an agreement — parallel conduct does not prove a conspiracy without evidence of coordination.","Argue the defendant withdrew from the conspiracy before any overt act was committed.","Challenge the admissibility of co-conspirator statements — the prosecution must independently prove the conspiracy exists.","Argue the defendant was not a knowing participant in the alleged conspiracy."}',
  common_defenses = '{"No agreement — there was no actual agreement between the parties to commit a crime.","Withdrawal — the defendant withdrew from the conspiracy and took affirmative steps to prevent the crime.","Lack of knowledge — the defendant was unaware of the criminal nature of the agreement.","No overt act — no member of the alleged conspiracy took an overt act in furtherance of the plan."}'
WHERE common_charge_slug = 'conspiracy' AND jurisdiction = 'NH';

-- NJ enrichment
UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"New Jersey''s per se BAC standard of 0.08 allows conviction without proving actual impairment if chemical test results are properly obtained.","There is no jury trial right for DWI in NJ — cases are tried in municipal court before a judge, typically resulting in faster convictions."}',
  defense_opportunities = '{"Challenge the legality of the traffic stop — without reasonable articulable suspicion, all evidence from the stop may be suppressed.","Challenge the 20-minute observation period before breath testing — any deviation can render results inadmissible.","Challenge field sobriety test administration under standardized NHTSA protocols."}',
  common_defenses = '{"Improper stop — the officer lacked reasonable articulable suspicion to initiate the traffic stop.","Faulty Alcotest — the breath testing device was not properly calibrated, maintained, or operated.","Observation period violation — the mandatory 20-minute observation period before breath testing was not properly conducted.","Rising BAC defense — defendant''s blood alcohol was below 0.08 at the time of actual operation.","Medical condition — GERD, diabetes, or other medical conditions produced false high BAC readings."}'
WHERE common_charge_slug = 'dui-first-offense' AND jurisdiction = 'NJ';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"New Jersey has no statute of limitations on prior DWI offenses for enhancement purposes — convictions from any time prior count.","Step-down provisions only allow leniency if 10+ years pass between convictions, making most repeat cases ineligible for relief.","IDRC (Intoxicated Driver Resource Center) attendance is mandatory and adds significant burden beyond direct penalties."}',
  defense_opportunities = '{"Challenge whether 10 years have passed since the prior conviction to invoke step-down provisions.","Challenge the chemical test results following the same Chun protocol attacks available for first offense.","Argue for inpatient or outpatient treatment in lieu of certain jail components."}',
  common_defenses = '{"Laurick challenge — prior DWI conviction was obtained without counsel and cannot be used for enhancement.","Step-down eligibility — more than 10 years have passed since the prior conviction, allowing first-offense treatment.","Improper stop or observation period violation."}'
WHERE common_charge_slug = 'dui-second-offense' AND jurisdiction = 'NJ';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"License revocation of 8 years and ignition interlock requirement create severe long-term consequences.","Third offense is still a traffic violation in NJ (not a criminal offense), but the jail sentence is mandatory and cannot be suspended.","Prior DWI convictions from any state with equivalent statutes count for enhancement purposes."}',
  defense_opportunities = '{"Challenge prior convictions through Laurick — uncounseled priors cannot enhance the current offense.","Challenge the equivalency of out-of-state DWI priors used for enhancement.","Argue for the maximum 90 days of inpatient treatment in lieu of jail time.","Challenge the chemical test results and the legality of the stop under the same standards as first offense."}',
  common_defenses = '{"Laurick challenge — prior conviction was uncounseled and invalid for enhancement purposes.","Out-of-state prior not equivalent — the prior conviction does not meet New Jersey''s statutory equivalency standard.","Faulty Alcotest under Chun protocol.","Illegal stop — no reasonable articulable suspicion to initiate the traffic stop."}'
WHERE common_charge_slug = 'dui-third-offense' AND jurisdiction = 'NJ';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Positive toxicology for any prohibited substance combined with observed impairment supports conviction.","Even legally prescribed medications can form the basis of a DWI-drugs charge if they impair driving ability."}',
  defense_opportunities = '{"Challenge the DRE officer''s qualifications and protocol compliance under the 12-step DRE evaluation standard.","Argue that drug metabolites in the system do not prove active impairment at the time of driving.","Challenge the connection between observed driving and the alleged drug impairment.","Highlight the lack of a per se threshold, making the case dependent on subjective officer observations."}',
  common_defenses = '{"No active impairment — drug metabolites were present but not causing impairment at the time of driving.","Legitimate prescription — medication was taken as prescribed without warning of impairment.","Faulty DRE evaluation — protocol was not properly followed or officer lacked certification.","Alternative explanation — observed symptoms were caused by fatigue, illness, or medical condition."}'
WHERE common_charge_slug = 'dui-drugs' AND jurisdiction = 'NJ';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"No Early Release Act (NERA) requires 85% of the sentence to be served for vehicular homicide convictions.","Reckless driving causing death satisfies the elements — proof of recklessness is the key contested issue.","Toxicology evidence linking impairment to the accident creates powerful circumstantial proof."}',
  defense_opportunities = '{"Challenge whether the defendant''s conduct rose to the level of recklessness rather than mere negligence.","Retain accident reconstruction experts to demonstrate alternative causes of the collision.","Challenge the toxicology evidence and its connection to actual impairment at the time of the accident.","Negotiate for downgraded charges (assault by auto) where causation evidence is weak."}',
