UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"NC''s Controlled Substance Reporting System (CSRS) provides a comprehensive database of prescription records","Schedule II-III possession without a prescription is a Class I felony","Doctor shopping patterns are easily documented through CSRS records","Expired prescriptions eliminate the valid-prescription defense"}',
  defense_opportunities = '{"Schedule IV-VI substances are only Class 1 misdemeanors, significantly reducing exposure","A valid, current prescription is a complete defense — the State bears the burden of proving it was lacking","CSRS records may contain errors or fail to account for out-of-state prescriptions","Medical necessity and legitimate treatment can complicate the prosecution''s narrative"}',
  common_defenses = '{"Valid prescription — defendant had a current, valid prescription from a licensed practitioner","CSRS error — prescription database records were incomplete or inaccurate","Lack of knowledge — defendant believed their prescription was still valid or covered the substance","Medical necessity — defendant possessed the substance in the course of legitimate medical treatment"}'
