UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Intent can be inferred from circumstantial evidence: quantity, packaging, scales, cash, and communications","Same penalty as actual delivery (Class G for Schedule I-II), creating strong plea pressure","School zone enhancement elevates the offense by two felony classes","Text messages and social media evidence increasingly support intent allegations"}',
