UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"North Carolina involuntary manslaughter requires only criminal negligence, a lower mental state than recklessness","Class F felony (up to 41 months) requires only culpable negligence — no intent to kill needed","Culpable negligence is a lower standard than malice, making the charge easier to prove than murder"}',
  defense_opportunities = '{"Culpable negligence must be more than ordinary negligence — the defense can argue the conduct did not rise to that level","The lawful-act theory (culpably negligent during a lawful act) requires the State to prove a gross deviation from reasonable care","No mandatory minimum and relatively lower exposure compared to murder charges"}',
  common_defenses = '{"Ordinary negligence — defendant''s conduct was negligent but did not rise to culpable negligence","Accident — the death was an unforeseeable accident without criminal negligence","No proximate cause — the defendant''s negligence was not the proximate cause of death"}'
