UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Common law robbery is a Class G felony (up to 47 months) with a clear statutory framework","The force or intimidation element is broadly interpreted — snatching property from someone can qualify","Victim identification evidence and surveillance footage are frequently available in robbery cases"}',
  defense_opportunities = '{"The distinction between robbery (force/intimidation) and larceny from the person (no force) is significant — larceny from the person is Class H, one level lower","Identification challenges are common in robbery cases, particularly when the perpetrator was masked or the encounter was brief","Intent to permanently deprive must be proven — taking property with intent to return it is not robbery"}',
  common_defenses = '{"Misidentification — the victim or witnesses incorrectly identified the defendant as the perpetrator","No force or intimidation — the taking was by stealth rather than force, reducing the charge to larceny","Alibi — defendant was elsewhere when the robbery occurred","Claim of right — defendant believed they had a legal right to the property"}'
