UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Class D felony (up to 204 months) with presumptive active sentence — one of NC''s most serious property crimes","The weapon need not be used — mere display or threatened use of a firearm, knife, or other dangerous weapon is sufficient","Any object capable of threatening life qualifies as a dangerous weapon under the statute","Multiple victims or incidents can result in consecutive sentences"}',
