UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"First-degree kidnapping is a Class C felony (up to 231 months) when the victim is not released in a safe place or is sexually assaulted or seriously injured","The statute covers multiple theories: ransom, facilitating felony, terrorizing, or serious harm","Children under 16 can be kidnapped by deception alone, without force or threat"}',
  defense_opportunities = '{"Second-degree kidnapping (Class E, 88 months max) applies when the victim is released in a safe place without serious injury — a critical distinction","Kidnapping charges are often challenged when they are incidental to another crime (robbery, assault) — the restraint or movement must be separate from and exceed what is inherent in the other crime","The consent of the victim (or parent/guardian for minors) negates the charge"}',
  common_defenses = '{"Consent — the victim voluntarily went with the defendant","Incidental to another offense — the movement or confinement was inherent in the commission of the underlying crime, not separate kidnapping","Release in safe place — victim was released unharmed, reducing to second-degree","Parental right — parent moved their own child without criminal purpose"}'
WHERE common_charge_slug = 'kidnapping' AND jurisdiction = 'NC';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"First-degree arson (occupied dwelling) is a Class D felony carrying up to 204 months","Physical and forensic evidence of fire origin and cause is typically strong when an accelerant is used","Insurance fraud motive provides a comprehensible theory for juries","Occupied structure at the time of the fire creates a threat-to-life narrative"}',
