UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Attempted first-degree murder is a Class B1 felony (same as second-degree murder) carrying 484+ months","Specific intent to kill can be inferred from the defendant''s actions (e.g., shooting at close range, stabbing vital areas)","The victim does not need to be injured — a substantial step toward killing with intent is sufficient"}',
