UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Felony larceny at $1,000+ is a Class I felony; larceny from the person or of a firearm is Class H regardless of value","Value over $100,000 escalates to Class C felony with exposure up to 231 months","NC allows aggregation of thefts in a scheme to reach felony thresholds"}',
  defense_opportunities = '{"Value of the property is the critical threshold issue — defense appraisals and depreciation can reduce the assessed value below $1,000","Class I felony (max 24 months) is at the lower end of NC''s felony range","Restitution and first-time offender provisions can mitigate the outcome"}',
  common_defenses = '{"Value dispute — the property is worth less than the felony threshold when properly valued","Claim of right — defendant believed they had a legal claim to the property","Lack of intent — defendant did not intend to permanently deprive the owner","Misidentification — someone else committed the theft"}'
