UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"North Carolina retail theft prosecutions are supported by store loss prevention testimony and surveillance","Class 1 misdemeanor (120 days max) is straightforward to prosecute with evidence of the taking","Surveillance and store loss prevention evidence are commonly available"}',
  defense_opportunities = '{"First-offense misdemeanor larceny carries relatively low penalties and is often suitable for diversion or plea alternatives","Deferred prosecution or conditional discharge programs are available in many NC counties","Value disputes can sometimes reduce the charge to an infraction or result in dismissal"}',
