UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"First-degree burglary is a Class D felony (204 months max) requiring occupied dwelling and nighttime entry","The breaking-and-entering element is interpreted broadly — pushing open an unlocked door qualifies","Physical evidence (tool marks, DNA, fingerprints) and surveillance footage connect defendants to the scene"}',
  defense_opportunities = '{"The distinction between first degree (Class D, occupied, nighttime) and second degree (Class G, 47 months max) is enormous","Daytime entry into an unoccupied dwelling is second-degree burglary — a major reduction","Intent to commit a felony or larceny therein must be proven — entry for other purposes is not burglary"}',
  common_defenses = '{"No intent to commit crime — defendant entered the dwelling for an innocent purpose","Consent or authorization — defendant had permission to enter the premises","Dwelling not occupied — no one was present, reducing to second-degree","Misidentification — defendant was not the person who entered the dwelling"}'
WHERE common_charge_slug = 'burglary' AND jurisdiction = 'NC';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Class D felony for first-degree (occupied nighttime) carries up to 204 months","Uninvited entry through an open door still constitutes ''breaking'' under NC common law","Victim testimony about the trauma of home invasion resonates strongly with juries"}',
  defense_opportunities = '{"Second-degree residential burglary (Class G, 47 months max) is available when the dwelling was unoccupied or it was daytime","Consent to enter eliminates the breaking-and-entering element entirely","The intent element must have existed at the time of entry, not after"}',
  common_defenses = '{"Consent — defendant had permission or an invitation to enter the residence","No criminal intent at time of entry — defendant entered with innocent purpose; any criminal act was an afterthought","Misidentification — physical or forensic evidence does not conclusively link defendant to the entry","Dwelling was not occupied — reducing the charge from first to second degree"}'
