-- SD enrichment
UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Officers in South Dakota are trained on standardized NHTSA field sobriety testing, and courts give significant weight to the HGN (horizontal gaze nystagmus) test as a scientific indicator.","Prosecutors may charge based solely on actual physical control (engine off, keys in pocket can suffice) — the state need not prove the vehicle was in motion."}',
  defense_opportunities = '{"Attack chemical test foundation: South Dakota requires a 20-minute observation period before breath testing under SD Admin Rules 64:37, and any contamination invalidates results.","Source code/maintenance records for the Intoxilyzer 8000 are discoverable in South Dakota and can reveal calibration issues.","Question whether the defendant was in ''actual physical control'' if the vehicle was parked, off, and the defendant was not in the driver''s seat.","Review the dashcam and bodycam footage against the officer''s report — discrepancies in recorded driving patterns versus narrative reports often produce suppression motions."}',
  common_defenses = '{"Lack of reasonable suspicion for the initial stop (Fourth Amendment suppression).","Improper administration of field sobriety tests (medical conditions, footwear, surface, lighting).","Rising blood alcohol defense — BAC was below limit while driving and rose during the delay before testing.","Medical conditions mimicking intoxication (diabetes, GERD/acid reflux causing mouth alcohol, neurological conditions).","Chain of custody or calibration failures with the breath or blood testing instrument."}'
WHERE common_charge_slug = 'dui-dwi' AND jurisdiction = 'SD';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"First-offense DUI in South Dakota requires no proof of prior history, simplifying the prosecution''s case.","Class 1 Misdemeanor classification allows prosecution in magistrate court with streamlined procedures.","Prosecutors can use the implied consent advisory and refusal as substantive evidence.","Courts routinely admit BAC evidence with minimal foundational challenges in first-offense cases."}',
  defense_opportunities = '{"Negotiation toward reckless driving (a ''wet reckless'') is possible when chemical test results are weak.","Challenge the 20-minute observation rule for breath testing — common compliance failures.","Invoke administrative hearing rights within 30 days to contest license revocation separately from criminal case."}',
  common_defenses = '{"Insufficient probable cause for arrest.","Breath test machine maintenance and calibration deficiencies.","Officer failure to follow NHTSA SFST protocol.","Necessity or duress (rare but recognized when fleeing immediate harm)."}'
WHERE common_charge_slug = 'dui-first-offense' AND jurisdiction = 'SD';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"South Dakota maintains a centralized DUI tracking system through the Department of Public Safety, making prior convictions easy to prove.","Mandatory minimum jail time applies to repeat offenders, eliminating probation-only outcomes.","Permanent ignition interlock requirements apply for third+ offenses.","Felony classification enables longer probation tails and broader collateral consequences."}',
  defense_opportunities = '{"Challenge the validity of prior convictions on Boykin grounds (proper plea colloquy, knowing waiver of rights).","Out-of-state prior convictions must be substantially similar to SD DUI law to count as predicates — analyze each carefully.","Negotiate down to a non-DUI alcohol offense if the chemical test is suppressible.","24/7 Sobriety Program participation can mitigate sentencing exposure even for repeat offenders.","Challenge the 10-year lookback calculation when prior convictions are near the threshold."}',
  common_defenses = '{"Constitutional invalidity of prior convictions used for enhancement.","Double jeopardy challenges to administrative + criminal penalties.","Same defenses as first-offense DUI applied to current charge.","Statute of limitations on stale priors.","Identity dispute when prior convictions belong to a different person with similar identifiers."}'
WHERE common_charge_slug = 'dui-repeat-offense' AND jurisdiction = 'SD';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Drug Recognition Experts (DREs) trained under the IACP protocol provide expert testimony on impairment.","Blood testing for drugs is admissible without breath test challenges.","Prescription medications can support DUI-drugs charges even when lawfully prescribed.","The state need not specify which drug caused impairment — any controlled substance suffices."}',
  defense_opportunities = '{"Challenge per se metabolite rule when defendant has medical marijuana or prescription history showing residual metabolites without impairment.","Attack DRE protocol — the 12-step DRE evaluation has known scientific weaknesses.","Question chain of custody for blood samples through the State Health Lab."}',
  common_defenses = '{"Lack of impairment despite presence of metabolites (especially marijuana).","Prescription medication defense with valid prescription and no warning labels violated.","Improper blood draw procedures (untrained phlebotomist, contaminated swab, wrong vial).","Involuntary intoxication.","Polypharmacy confounding DRE conclusions."}'
WHERE common_charge_slug = 'dui-drugs' AND jurisdiction = 'SD';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Officer testimony alone often suffices for conviction; no scientific evidence required.","Often used as a fallback when DUI evidence is weak.","Court points and license suspension consequences create plea leverage.","Can be enhanced when combined with other moving violations on the same incident."}',
  defense_opportunities = '{"''Wilful or wanton'' is a high mens rea standard — mere negligence or carelessness is insufficient.","Challenge officer''s vantage point and ability to observe alleged conduct.","Dashcam evidence frequently contradicts officer narratives about driving behavior.","Weather, road conditions, and emergency circumstances are mitigating factors."}',
  common_defenses = '{"Insufficient evidence of wilful or wanton conduct.","Mistake of fact regarding road conditions or traffic.","Necessity (avoiding a greater harm).","Mechanical failure of the vehicle.","Officer misidentification of driver."}'
WHERE common_charge_slug = 'reckless-driving' AND jurisdiction = 'SD';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Class 6 Felony classification (injury) and Class 5 Felony (death) make this a serious felony with significant exposure.","Vehicle damage and witness IDs frequently link defendants conclusively.","Knowledge of the accident can be inferred from circumstances (impact, debris, vehicle damage).","Surveillance cameras and license plate readers increasingly identify fleeing vehicles."}',
  defense_opportunities = '{"Attack the knowledge element — defendant must have known an accident occurred involving injury.","Identification defenses are common when only the vehicle is identified, not the driver.","Defendant returning to the scene within a reasonable time may negate intent.","Question whether the alleged ''accident'' actually involved another vehicle or person.","Medical emergency exception when defendant left to seek aid."}',
  common_defenses = '{"Lack of knowledge that an accident occurred.","Mistaken identity of the driver.","Necessity (medical emergency, threat to safety at scene).","Defendant did stop and provide information adequately.","No injury occurred (downgrade to misdemeanor leaving scene)."}'
WHERE common_charge_slug = 'hit-and-run' AND jurisdiction = 'SD';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Class 3 Felony with significant prison exposure (up to 15 years).","Medical examiner testimony establishing cause of death is typically uncontested.","Accident reconstruction experts provide compelling visual evidence.","BAC evidence carries enormous weight when paired with a fatality."}',
  defense_opportunities = '{"Causation is often the strongest defense — was the DUI actually the cause, or were other factors (other driver''s actions, road conditions, mechanical failure) responsible?","Challenge BAC results aggressively given the stakes.","Independent accident reconstruction may show alternative causes.","Victim''s contributory conduct (failure to wear seatbelt, sudden lane change) can mitigate or eliminate causation.","Negotiate to vehicular manslaughter (Class 4 Felony) when DUI evidence is borderline."}',
  common_defenses = '{"Lack of causation (intervening cause).","Insufficient proof of impairment at time of crash.","Constitutional challenges to blood draw without warrant.","Mechanical failure of the vehicle.","Sudden medical emergency (involuntary intoxication, seizure)."}'
WHERE common_charge_slug = 'vehicular-homicide' AND jurisdiction = 'SD';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Lower mens rea standard than vehicular homicide makes conviction easier.","Class 4 Felony exposure still significant (up to 10 years).","Frequently charged as a fallback to vehicular homicide when DUI cannot be proven.","Eyewitness testimony about driving behavior is typically admissible without scientific foundation."}',
  defense_opportunities = '{"Criminal negligence requires gross deviation from reasonable care — argue the conduct was at most ordinary negligence (civil, not criminal).","Causation defenses are equally strong here as in vehicular homicide.","Accident reconstruction can show intervening or superseding causes.","Mechanical failure or unexpected medical event defenses.","Victim conduct contributing to the accident."}',
  common_defenses = '{"Conduct did not rise to criminal negligence.","Intervening superseding cause.","Mechanical failure.","Sudden unexpected medical emergency.","Victim''s own negligence as the proximate cause."}'
WHERE common_charge_slug = 'vehicular-manslaughter' AND jurisdiction = 'SD';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"DPS records easily prove the suspended status at the time of stop.","Class 2 Misdemeanor classification allows quick disposition.","Often charged alongside the original offense that caused the suspension, compounding penalties.","Subsequent offenses escalate to Class 1 Misdemeanor with mandatory jail time."}',
  defense_opportunities = '{"Challenge whether the defendant received proper notice of suspension under SD Department of Public Safety procedures.","Verify the underlying suspension was actually valid and not procedurally defective.","Mistake of fact regarding the date the suspension took effect or ended.","Hardship license eligibility may have been valid at time of stop.","Reinstatement may have technically occurred but not yet processed in DPS database."}',
  common_defenses = '{"Lack of notice of suspension.","Necessity (medical emergency, fleeing harm).","Mistake of fact regarding license status.","Defective underlying suspension order.","Identity defense (someone else was driving)."}'
WHERE common_charge_slug = 'driving-on-suspended' AND jurisdiction = 'SD';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Class 5 Felony enhancement when fleeing creates substantial risk of injury or death.","Dashcam and bodycam evidence makes the elements easy to prove.","Officer testimony about lights, sirens, and visual contact is generally credible to juries.","Often paired with traffic offenses, DUI, or drug charges — significant charging leverage."}',
  defense_opportunities = '{"''Willful'' element requires defendant know an officer was attempting to stop the vehicle.","Lighting conditions, music volume, and distance can negate awareness of police signals.","Defendant pulling over at the next safe location is not necessarily fleeing.","Challenge the substantial risk enhancement — speed alone may not suffice.","GPS and event data recorder (EDR) evidence may contradict officer''s claims about pursuit conditions."}',
  common_defenses = '{"Lack of willful intent (didn''t know police were signaling).","Necessity (fleeing actual or perceived threat).","Defendant was looking for a safe location to stop.","Mistaken identity of the vehicle.","Officer signals were inadequate or non-conforming."}'
WHERE common_charge_slug = 'fleeing-eluding' AND jurisdiction = 'SD';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Constructive possession doctrine allows charges based on proximity and dominion over an area where drugs are found.","South Dakota''s ''internal possession'' statute allows charging based on metabolites in urine alone — unique to SD.","Lab testing of substances is generally uncontested in routine cases.","Schedule I/II covers virtually all street drugs (meth, cocaine, heroin, fentanyl)."}',
  defense_opportunities = '{"Challenge constructive possession — mere proximity is insufficient; dominion and control must be proven.","Fourth Amendment suppression for unlawful searches is the most powerful defense.","Challenge the internal possession statute under privacy and equal protection grounds (constitutional challenges have had mixed success).","Contest the lab analysis — substance identification, weight, and chain of custody."}',
  common_defenses = '{"Unlawful search and seizure (Fourth Amendment).","Lack of knowing possession.","Substance was not actually a controlled substance (lab error).","Constructive possession insufficient (drugs belonged to another).","Entrapment by law enforcement informant."}'
WHERE common_charge_slug = 'drug-possession' AND jurisdiction = 'SD';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Internal possession via blood/urine testing is enforceable for marijuana.","Field testing kits provide presumptive identification at scene.","Visible smoke or odor remains valid probable cause in most contexts.","Felony enhancement at 2 oz makes even modest amounts felonies."}',
  defense_opportunities = '{"Medical marijuana cardholders under IM 26 have an affirmative defense for compliant possession.","Hemp and CBD products can produce false positives with field tests — demand lab confirmation.","Odor-based searches face increasing scrutiny in jurisdictions with legal medical marijuana.","Challenge weight calculations, especially when drying or stem inclusion affects classification.","Negotiate to paraphernalia or attempted possession to avoid felony exposure."}',
  common_defenses = '{"Valid medical marijuana card and compliant amount.","Substance was lawful hemp or CBD.","Unlawful search.","Lack of knowing possession.","Insufficient quantity for the alleged classification."}'
WHERE common_charge_slug = 'drug-possession-marijuana' AND jurisdiction = 'SD';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Cocaine is unmistakable in lab testing with high reliability.","Internal possession statute applies to cocaine metabolites.","Possession with intent to distribute can be inferred from packaging, scales, or cash.","Schedule II classification removes any defense based on medical use."}',
  defense_opportunities = '{"Suppression of evidence based on illegal search is the strongest defense.","Constructive possession challenges in vehicle/shared residence cases.","Demand independent lab testing of the substance.","Negotiate to attempted possession to reduce felony class."}',
