UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Methamphetamine is a Schedule II controlled substance — Class 5 Felony for any amount.","Internal possession by metabolites in urine is also a felony in SD.","Meth indicia (pipes, baggies, scales) are commonly found and admissible.","Confidential informants often provide controlled buy evidence.","Meth possession often paired with manufacturing or trafficking charges."}',
  defense_opportunities = '{"Internal possession charges are vulnerable to constitutional privacy challenges and chain of custody attacks on urine samples.","Suppress searches that lacked clear probable cause (odor of meth is harder to establish than alcohol).","Challenge substance identification — over-the-counter decongestants can produce false positives in field tests.","Constructive possession defenses in shared environments."}',
  common_defenses = '{"Unlawful search and seizure.","Lack of knowing possession.","Lab misidentification.","Constructive possession insufficient."}'
