UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Threshold quantities create automatic trafficking charges regardless of intent.","Wiretap evidence, controlled buys, and informant testimony build strong cases.","Conspiracy charges can sweep in peripheral participants."}',
  defense_opportunities = '{"Challenge quantity calculations — packaging weight versus pure substance weight.","Attack informant credibility and prior cooperation deals.","Suppress wiretap evidence on minimization and necessity grounds.","Entrapment when informants instigated otherwise non-existent transactions.","Conspiracy requires actual agreement — mere presence or association is insufficient."}',
