UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Quantity-based escalation: 1/2 lb of marijuana triggers Class 3 Felony.","Hand-to-hand controlled buys provide compelling evidence.","Cell phone records of drug-related communications are routinely admitted."}',
  defense_opportunities = '{"Distinguish distribution from possession — was there an actual transfer?","Personal use defense when quantity is borderline.","Challenge informant testimony with prior inconsistent statements.","Suppress searches and seizures that produced the underlying drugs.","Negotiate to simple possession when transfer evidence is weak."}',
