UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Pseudoephedrine purchase tracking under NPLEx provides direct evidence of meth manufacturing.","Lab equipment, precursors, and chemicals create strong circumstantial cases.","Photographs of grow operations are powerful jury evidence.","Marijuana cultivation of any plant count is a felony under SD law."}',
  defense_opportunities = '{"Challenge the existence of an actual manufacturing operation versus possession of items with legal uses.","Pseudoephedrine purchases must connect to manufacturing activity, not personal cold/allergy use.","Suppress searches based on inadequate warrants for residential grow operations.","Medical marijuana defense for compliant cultivation under IM 26.","Challenge plant counts and weight calculations."}',
