UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Death penalty eligibility for Class A Felony creates enormous plea leverage.","DNA, ballistic, and forensic evidence carry enormous weight.","South Dakota allows capital aggravating factors that broaden death-eligible cases."}',
  defense_opportunities = '{"Challenge premeditation — heat of passion or impulse defenses can reduce to second-degree.","Mental state defenses (insanity, diminished capacity, intoxication) may negate premeditation.","Challenge identification through eyewitness reliability research.","Forensic challenges to DNA contamination, ballistic match certainty."}',
