UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Class C Felony with significant exposure (up to life).","Often used as a fallback when murder charges face self-defense issues.","Provocation can be physical or verbal in some circumstances.","Plea negotiations frequently land here from initial murder charges."}',
  defense_opportunities = '{"Self-defense remains a complete defense and can result in acquittal.","Challenge whether the provocation was ''adequate'' — words alone are generally insufficient.","Cooling-off period analysis — too much time between provocation and act negates the charge.","Imperfect self-defense in some scenarios.","Causation challenges in attenuated cases."}',
