UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Class 4 Felony with up to 10 years exposure.","Lower mens rea standard makes conviction easier than higher homicide charges.","Frequently charged in DUI fatalities, child endangerment deaths, and weapon accidents.","Misdemeanor manslaughter rule allows charges where death results from any unlawful act."}',
  defense_opportunities = '{"Argue conduct was at most ordinary negligence, not criminal.","Challenge causation — was the negligent act the proximate cause?","Intervening cause defenses are common.","Accident defense when no underlying unlawful act occurred.","Constitutional challenges to misdemeanor manslaughter rule."}',
