UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Class 3 Felony with up to 15 years exposure.","Photographic evidence of injuries is powerful jury evidence.","911 calls are admissible as excited utterances.","Domestic violence enhancement applies in many household contexts."}',
  defense_opportunities = '{"South Dakota recognizes ''stand your ground'' principles in some contexts.","Challenge ''serious bodily injury'' classification — temporary injuries may not qualify.","Mutual combat defense in bar fights and similar scenarios.","Challenge identification when assailant is not clearly identified."}',
