  prosecution_strengths = '{"Preponderance standard.","Hearsay generally admissible.","Original sentence remains as maximum.","Limited appellate review."}',
  defense_opportunities = '{"Challenge willfulness.","Mitigation evidence at disposition.","Treatment alternatives.","Negotiate with parole officer."}',
  common_defenses = '{"Procedural due process violation.","Lack of willful violation.","Inability to comply.","Substantial compliance.","Mitigation."}'
WHERE common_charge_slug = 'parole-violation' AND jurisdiction = 'UT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Same penalty as the underlying offense.","Knowledge of criminal purpose plus assistance suffices.","Conspiracy charges often pile on.","Co-defendant testimony commonly available."}',
  defense_opportunities = '{"Mere presence is not aiding and abetting.","Challenge knowledge of criminal purpose.","Withdrawal defense.","Lack of substantial assistance.","Mistaken identity."}',
  common_defenses = '{"Mere presence.","Lack of knowledge.","Withdrawal.","No substantial assistance.","Mistaken identity."}'
WHERE common_charge_slug = 'aiding-abetting' AND jurisdiction = 'UT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Substantial step toward commission suffices.","Specific intent often inferred from circumstances.","Renunciation must be voluntary and complete.","Often paired with the completed offense."}',
  defense_opportunities = '{"Challenge specific intent.","Mere preparation is not a substantial step.","Factual or legal impossibility.","Mistaken identity."}',
  common_defenses = '{"Lack of specific intent.","Mere preparation.","Renunciation.","Impossibility.","Mistaken identity."}'
WHERE common_charge_slug = 'attempt' AND jurisdiction = 'UT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Agreement plus overt act suffices.","Co-conspirator statements admissible against all members.","Pinkerton liability extends responsibility broadly.","Wiretap and surveillance evidence often available."}',
  defense_opportunities = '{"Challenge the existence of an actual agreement.","Withdrawal defense.","Challenge knowledge of conspiracy''s purpose.","Wharton''s Rule for offenses requiring multiple participants.","Mistaken identity in large conspiracy cases."}',
  common_defenses = '{"No agreement existed.","Withdrawal.","Lack of knowledge.","Wharton''s Rule.","Mistaken identity."}'
WHERE common_charge_slug = 'conspiracy' AND jurisdiction = 'UT';

-- VT enrichment
UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Implied consent law means refusal to submit to evidentiary testing creates a separate adverse inference and administrative penalties.","20-year lookback period for prior offenses is one of the longest in the nation, making prior convictions highly relevant."}',
  defense_opportunities = '{"Vermont requires proof the defendant operated the vehicle ''on a highway'' — operation on private property may not satisfy this element.","Challenge the accuracy of BAC testing equipment calibration and maintenance records, as Vermont mandates strict compliance with testing protocols.","Actual physical control doctrine in Vermont is narrowly construed — merely sitting in a parked vehicle may not meet the standard.","Rising blood alcohol defense: Vermont tests may be administered after a delay, allowing argument that BAC was below .08 at time of driving."}',
  common_defenses = '{"Lack of operation on a ''highway'' as defined under Vermont law.","Improper administration of field sobriety tests or failure to follow standardized protocols.","Fourth Amendment challenge to the initial traffic stop — no reasonable suspicion of violation.","Insufficient evidence of actual impairment where BAC is near the .08 threshold."}'
WHERE common_charge_slug = 'dui-dwi' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"90-day license suspension creates immediate collateral consequences that encourage plea deals.","Vermont''s $50 surcharge and mandatory alcohol/drug screening add financial pressure even for first offenders.","Enhanced penalties for BAC .16+ give prosecution leverage to negotiate down from the enhancement."}',
  defense_opportunities = '{"First offense carries no mandatory minimum jail time, making probation and alternative sentencing realistic outcomes.","Eligibility for ignition interlock restricted license provides incentive for negotiating favorable terms.","Challenge whether the BAC test was administered within the proper time window after operation.","Vermont''s lack of mandatory minimum for first offense allows defense to argue for full acquittal without catastrophic risk."}',
  common_defenses = '{"Improper stop — no reasonable articulable suspicion for the initial traffic stop.","Breath test machine calibration or certification defects.","Rising BAC defense — BAC was below .08 at the time of actual driving.","Medical conditions (GERD, diabetes) affecting breath test accuracy."}'
WHERE common_charge_slug = 'dui-first-offense' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Mandatory minimum incarceration for second and subsequent offenses (60 hours for second, 96 for third) limits judicial discretion.","Third offense within 20 years elevates to a felony with up to 5 years imprisonment.","Lifetime license revocation for third offense creates enormous collateral consequences."}',
  defense_opportunities = '{"Challenge the validity or constitutionality of prior out-of-state convictions used for enhancement under Vermont''s lookback period.","Verify that prior convictions were obtained with proper counsel representation — uncounseled priors may be excludable.","Second offense allows 200 hours community service as an alternative to 60 consecutive hours imprisonment.","Argue that the 20-year lookback window has expired for marginal-date prior convictions."}',
  common_defenses = '{"Invalid prior convictions — prior guilty pleas entered without effective assistance of counsel.","Challenge the sequence and timing of prior offenses relative to the 20-year lookback window.","Constitutional challenge to the stop, arrest, or testing procedures.","Negotiate for treatment-based alternatives where substance abuse disorder is documented."}'
WHERE common_charge_slug = 'dui-repeat-offense' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Vermont does not require a specific drug concentration threshold — prosecution can rely on observed impairment alone.","Drug Recognition Expert (DRE) protocol provides standardized evidence framework that juries find credible.","Blood test results showing presence of controlled substances create a factual foundation even without per se limits."}',
  defense_opportunities = '{"No per se limit for drugs means prosecution must prove actual impairment beyond a reasonable doubt — mere presence of metabolites is insufficient.","DRE protocol is subjective and susceptible to challenge on scientific reliability grounds.","Passive inhalation or residual metabolites from prior lawful use may explain positive test results.","Challenge the chain of custody and handling of blood samples used for toxicology."}',
  common_defenses = '{"Lawful prescription use — medication taken as prescribed by a physician.","Insufficient proof of impairment — drug metabolites in blood do not prove impairment at the time of driving.","Challenge the DRE officer''s qualifications, training, or adherence to the DRE protocol.","Fourth Amendment challenge to the blood draw warrant or consent."}'
WHERE common_charge_slug = 'dui-drugs' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Lower mens rea requirement of negligence rather than intentional conduct makes this easier to prove than assault charges.","Dashcam, bodycam, and witness testimony often provide strong objective evidence of driving behavior.","Prosecution can use accident reconstruction experts to establish that driving created unjustifiable risk."}',
  defense_opportunities = '{"Challenge the causal link between the defendant''s driving and any resulting injury or property damage.","Road conditions, weather, mechanical failure, or other drivers'' conduct may explain the driving behavior."}',
  common_defenses = '{"Emergency doctrine — driving behavior was a reasonable response to a sudden emergency.","Mechanical failure of the vehicle beyond the driver''s control.","Contributory negligence of another driver or road hazard.","Insufficient evidence that driving behavior created an ''unjustifiable risk'' to persons or property."}'
WHERE common_charge_slug = 'reckless-driving' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Surveillance cameras, cell phone location data, and vehicle damage evidence often establish identity.","Up to 15 years imprisonment when the accident involves death makes this a high-stakes charge.","Vermont law requires stopping, identifying, and rendering aid — failure on any prong supports the charge."}',
  defense_opportunities = '{"Argue the defendant was genuinely unaware an accident occurred, particularly in low-impact or multi-vehicle scenarios.","Challenge identification evidence — witness descriptions at night or from a distance are unreliable.","The defendant stopped nearby or returned shortly after leaving, demonstrating no intent to evade.","Vehicle damage consistent with the accident may have alternative explanations."}',
  common_defenses = '{"Lack of knowledge — defendant did not know or have reason to know the accident occurred.","Misidentification — the vehicle or driver was not correctly identified.","The defendant left to seek help or ensure personal safety before returning.","Duress or emergency — the defendant left due to fear for personal safety."}'
WHERE common_charge_slug = 'hit-and-run' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"If DUI-related, the intoxication itself may satisfy the gross negligence standard.","Vermont allows the jury to infer negligence from the manner of driving and the resulting death.","Expert testimony from accident reconstructionists and medical examiners establishes causation effectively."}',
  defense_opportunities = '{"Challenge the causal link between the defendant''s driving and the death — intervening causes or the victim''s own conduct may be factors.","Gross negligence is a high standard — ordinary negligence or momentary inattention may not meet it.","If DUI-related, all DUI defenses apply in addition to causation challenges.","Independent expert reconstruction may dispute the prosecution''s theory of the accident."}',
  common_defenses = '{"Intervening cause — the victim''s or a third party''s conduct was the proximate cause of death.","The defendant''s conduct was negligent but did not rise to gross negligence.","Challenge the medical examiner''s determination of cause of death.","Accident reconstruction disputing the prosecution''s theory of the collision."}'
WHERE common_charge_slug = 'vehicular-homicide' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Prosecution can bootstrap DUI or reckless driving charges to establish the predicate unlawful act.","Maximum sentence of 15 years provides significant leverage for plea negotiations.","Relatively straightforward causation in single-vehicle fatality cases."}',
  defense_opportunities = '{"Challenge whether the defendant''s conduct constituted criminal negligence versus civil negligence.","If based on an underlying unlawful act, the unlawful act itself may be defensible.","Medical causation may be disputed — pre-existing conditions or delayed medical treatment could be factors.","Accident reconstruction challenging the prosecution''s speed or trajectory analysis."}',
  common_defenses = '{"Conduct did not rise to criminal negligence — ordinary negligence at most.","Superseding cause of death not attributable to the defendant''s driving.","The underlying alleged unlawful act was not proven.","Self-defense or emergency doctrine if evasive driving contributed to the accident."}'
WHERE common_charge_slug = 'vehicular-manslaughter' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"DMV records provide straightforward documentary evidence of suspension status.","Notice of suspension is typically sent by mail — prosecution can establish constructive notice even without proof of actual receipt.","Repeat violations carry escalating penalties including mandatory jail time."}',
  defense_opportunities = '{"Challenge whether the defendant received actual notice of the suspension — mail notice may have failed.","If the suspension was based on unpaid fines, argue the suspension itself was constitutionally deficient (inability to pay).","The license may have been reinstated or the suspension expired before the date of the alleged offense.","Administrative errors in DMV records may show the license was not actually suspended at the time."}',
  common_defenses = '{"Lack of knowledge — the defendant was not aware their license was suspended.","Administrative error — DMV records incorrectly reflected suspension status.","Necessity defense — the defendant was driving due to a genuine emergency.","The license had been reinstated or the suspension had expired before the date of driving."}'
WHERE common_charge_slug = 'driving-on-suspended' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"The act of fleeing itself is strong evidence of consciousness of guilt for any underlying offense.","Vermont penalties escalate significantly if the eluding creates a risk to public safety.","Testimony from the pursuing officer about activated lights and sirens is typically straightforward."}',
  defense_opportunities = '{"Argue the defendant did not see or hear the police signals due to road noise, weather, or vehicle conditions.","Challenge whether the officer properly identified themselves — unmarked vehicles or plainclothes officers raise issues.","The defendant was pulling over to a safe location and was not fleeing.","GPS and speed data may contradict the officer''s characterization of the defendant''s driving."}',
  common_defenses = '{"Lack of awareness — the defendant did not know police were attempting to stop them.","The police vehicle was unmarked or the officer did not use proper signals.","The defendant was seeking a safe location to stop.","Duress — the defendant feared for their safety (e.g., impersonation concerns)."}'
WHERE common_charge_slug = 'fleeing-eluding' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Constructive possession doctrine allows prosecution even when drugs are found in a shared space if linked to the defendant.","Laboratory analysis confirming the identity of the substance is strong scientific evidence.","Vermont''s broad definition of ''regulated drugs'' covers a wide range of substances."}',
  defense_opportunities = '{"Challenge constructive possession where drugs were found in a shared vehicle, residence, or common area.","Vermont has made personal possession a health-focused issue — diversion programs may be available.","Argue the substance was not a controlled substance or was misidentified by field tests.","Fourth Amendment challenge to the search that discovered the drugs — warrant deficiencies, lack of consent, or improper stop."}',
  common_defenses = '{"Unlawful search and seizure — the drugs were discovered during an unconstitutional search.","Lack of knowledge — the defendant did not know the substance was present or that it was controlled.","The substance was not a controlled substance (lab testing error or misidentification).","Constructive possession challenge — the defendant did not have dominion or control over the area where drugs were found."}'
WHERE common_charge_slug = 'drug-possession' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Odor of marijuana can provide probable cause for a search in certain circumstances.","Quantities significantly exceeding 1 ounce raise inference of intent to distribute.","Packaging, scales, or large amounts of cash found alongside marijuana bolster prosecution."}',
  defense_opportunities = '{"Vermont legalized personal possession of up to 1 ounce — possession at or below this threshold is not criminal.","Challenge weight measurements — moisture content, packaging weight, and testing methodology can reduce the net weight below the threshold.","Home cultivation of up to 2 mature and 4 immature plants is legal for personal use in Vermont.","Argue the marijuana belonged to another person, particularly in shared living situations."}',
  common_defenses = '{"Legal possession — amount was within Vermont''s legal limit of 1 ounce or fewer.","Unlawful search — the discovery was the result of an unconstitutional search or seizure.","The marijuana was part of a legal home cultivation (2 mature / 4 immature plants).","Constructive possession challenge in shared spaces."}'
WHERE common_charge_slug = 'drug-possession-marijuana' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Cocaine is a Schedule II substance in Vermont, triggering enhanced statutory penalties.","Laboratory confirmation of cocaine identity through forensic testing is highly reliable evidence.","Sentencing of up to 1 year (first offense) and up to 3 years (subsequent) provides significant plea leverage."}',
  defense_opportunities = '{"Challenge the quantity — trace or residue amounts may be argued as insufficient for possession.","Fourth Amendment challenges to vehicle or home searches are frequently viable.","Vermont''s approach to substance abuse treatment may support diversion or deferred sentencing arguments.","Chain of custody issues — the substance may have been contaminated, mislabeled, or improperly stored."}',
  common_defenses = '{"Unlawful search and seizure — suppression of evidence obtained without proper warrant or exception.","Lack of knowledge that the substance was cocaine.","Constructive possession challenge where the cocaine was found in a shared location.","Trace amounts insufficient to constitute ''possession'' under the statute."}'
WHERE common_charge_slug = 'drug-possession-cocaine' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Lab testing for methamphetamine is highly accurate, making substance identity rarely disputable.","Presence of meth paraphernalia (pipes, syringes) alongside the substance strengthens the case.","Vermont law treats meth as a serious public safety concern, and juries tend to view meth cases seriously."}',
  defense_opportunities = '{"Challenge the search warrant or consent that led to discovery of the methamphetamine.","Argue that residue or trace amounts do not constitute a usable quantity for possession purposes.","Vermont''s treatment-oriented approach may support arguments for diversion rather than incarceration.","If found in a shared space, contest whether the defendant had knowledge and dominion over the substance."}',
  common_defenses = '{"Unlawful search and seizure — Fourth Amendment challenge to how the drugs were discovered.","Lack of knowledge — the defendant did not know the substance was methamphetamine.","Constructive possession — the defendant did not control the area where the meth was found.","Entrapment — law enforcement induced the defendant to possess a substance they would not otherwise have possessed."}'
WHERE common_charge_slug = 'drug-possession-meth' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Controlled buys with confidential informants wearing recording devices provide strong direct evidence.","Large quantities, packaging materials, and financial records establish trafficking beyond personal use.","Mandatory minimum sentences for certain drug quantities limit judicial discretion at sentencing."}',
  defense_opportunities = '{"Challenge the reliability and credibility of confidential informants, particularly those with pending charges or compensation.","Entrapment defense if law enforcement provided the opportunity, means, or inducement for the sale.","Argue the quantity was consistent with personal use, not trafficking or distribution.","Challenge electronic surveillance — wiretaps and recordings must comply with Vermont and federal constitutional requirements."}',
  common_defenses = '{"Entrapment — the defendant was induced by law enforcement to commit a crime they were not predisposed to commit.","Insufficient evidence of sale or distribution — possession alone does not prove trafficking.","Unlawful surveillance — wiretaps or recordings obtained without proper authorization.","Challenge the weight and identity of the controlled substance through independent lab testing."}'
WHERE common_charge_slug = 'drug-trafficking' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Controlled purchases recorded by law enforcement provide compelling evidence of distribution activity.","Text messages, phone records, and social media communications corroborate distribution networks.","Proximity to schools or public housing triggers enhanced penalties."}',
  defense_opportunities = '{"Challenge the controlled buy procedures — failure to search the informant pre- and post-buy undermines evidence integrity.","Argue the defendant was merely a user who shared drugs, not a distributor operating for profit.","Informant credibility challenges — many informants have significant incentives to fabricate or exaggerate.","Attack the audio or video quality of recorded transactions as ambiguous or unreliable."}',
  common_defenses = '{"Entrapment — law enforcement or an informant induced the defendant to distribute.","The defendant was a user sharing drugs with friends, not engaged in commercial distribution.","Unlawful search and seizure — evidence obtained without proper warrant or exception to the warrant requirement.","Mistaken identity — the defendant was not the person involved in the transaction."}'
WHERE common_charge_slug = 'drug-distribution' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Physical evidence of manufacturing equipment (lab apparatus, precursor chemicals) is highly incriminating.","Environmental contamination from drug labs creates additional charges and public safety narrative for prosecution.","Expert testimony from trained clandestine lab investigators educates juries on manufacturing indicators."}',
  defense_opportunities = '{"Challenge whether the evidence establishes actual manufacturing versus mere possession of equipment with a lawful purpose.","Argue the defendant''s presence at a manufacturing location does not prove participation in manufacturing.","Scientific challenge to the prosecution''s claim that the equipment was capable of producing the alleged substance.","Fourth Amendment challenges to the search of the premises where the lab was allegedly found."}',
  common_defenses = '{"Lack of knowledge — the defendant did not know manufacturing was occurring at the location.","The equipment had lawful uses and was not being used for drug manufacturing.","Unlawful search and seizure — the search warrant was deficient or the warrantless search was not justified.","Mere presence — the defendant was at the location but was not involved in the manufacturing operation."}'
WHERE common_charge_slug = 'drug-manufacturing' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Residue testing on paraphernalia items can confirm the presence of controlled substances.","Proximity of paraphernalia to drugs strengthens both the paraphernalia charge and the possession charge.","Expert testimony on how common household items are used as paraphernalia educates juries."}',
  defense_opportunities = '{"Many items classified as paraphernalia have legitimate uses — the item''s primary purpose may be lawful.","Vermont has been moving toward harm reduction policies, which may support leniency arguments.","Challenge whether the item was actually used for or intended for drug use.","If no drug residue is found on the item, argue it was not paraphernalia."}',
  common_defenses = '{"The item had a legitimate, non-drug-related purpose.","Lack of knowledge — the defendant did not know the item was drug paraphernalia or was associated with drugs.","Unlawful search — the paraphernalia was discovered through an unconstitutional search.","The item belonged to another person and the defendant had no knowledge of or control over it."}'
WHERE common_charge_slug = 'drug-paraphernalia' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Expert testimony from narcotics officers on ''indicators of distribution'' is routinely admitted.","Text messages discussing drug transactions provide powerful direct evidence of intent.","Even without an observed sale, circumstantial evidence of intent can be sufficient for conviction."}',
  defense_opportunities = '{"Argue the quantity was consistent with personal use — challenge the prosecution''s dosage unit calculations.","The presence of scales, bags, or cash has innocent explanations that should be explored.","No observed sale or exchange undermines the inference of distribution intent.","Expert testimony on ''distribution indicators'' is subjective and can be challenged through cross-examination."}',
  common_defenses = '{"Personal use — the quantity and circumstances are consistent with personal consumption, not distribution.","Unlawful search and seizure — suppression of the drugs and distribution evidence.","Lack of intent — no direct evidence of sales, no communications about distribution.","Constructive possession — the defendant did not control the area where the drugs and distribution materials were found."}'
WHERE common_charge_slug = 'drug-possession-with-intent' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Evidence of planning, motive, and prior threats establishes premeditation.","Vermont''s felony murder rule applies when death occurs during commission of specified felonies.","DNA, ballistics, and digital forensic evidence provide strong identification and circumstantial proof."}',
  defense_opportunities = '{"Challenge premeditation — argue the killing was impulsive rather than planned, supporting reduction to second-degree murder.","Self-defense or defense of others if the defendant reasonably believed deadly force was necessary.","Diminished capacity or mental illness affecting the defendant''s ability to form the specific intent required for first-degree murder.","Challenge the reliability of eyewitness identification, which research shows is frequently unreliable."}',
  common_defenses = '{"Self-defense — the defendant used force in response to a reasonable belief of imminent deadly harm.","Lack of premeditation — the killing was not willful, deliberate, and premeditated.","Insanity defense under Vermont law — the defendant was unable to appreciate the wrongfulness of their conduct.","Mistaken identity — the defendant was not the person who committed the killing."}'
WHERE common_charge_slug = 'murder-first-degree' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Intent to kill can be inferred from the nature of the attack (use of a deadly weapon, multiple blows).","Depraved indifference to human life can establish second-degree murder without proving specific intent to kill.","Lesser burden than first-degree murder makes second-degree murder a strong fallback charge."}',
  defense_opportunities = '{"Argue provocation sufficient to reduce the charge to voluntary manslaughter — ''heat of passion'' defense.","Self-defense or defense of others with a reasonable belief that force was necessary.","Challenge the intent element — argue the defendant did not intend to kill or act with depraved indifference.","Diminished capacity due to intoxication or mental health issues may negate intent."}',
  common_defenses = '{"Heat of passion / adequate provocation reducing murder to manslaughter.","Self-defense — reasonable belief that deadly force was necessary to prevent imminent harm.","Intoxication negating the specific intent to kill.","Accidental killing — the death was unintended and not the result of reckless conduct."}'
WHERE common_charge_slug = 'murder-second-degree' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Prosecution often uses this as a lesser included charge of murder, giving juries a compromise verdict option.","Evidence of the defendant''s violent act causing death is typically straightforward in manslaughter cases.","Vermont does not require extensive proof of premeditation, only that the killing was intentional."}',
  defense_opportunities = '{"Adequate provocation may further reduce culpability — argue the provocation was severe enough to make a reasonable person lose self-control.","Self-defense with excessive force may mitigate from murder but the force analysis is fact-intensive.","Challenge the intent element if the death was truly accidental or the result of negligence rather than intentional conduct.","Mental health evidence may support a diminished capacity argument."}',
  common_defenses = '{"Self-defense — the initial use of force was justified even if excessive in degree.","Accident — the death was not the result of intentional conduct.","Diminished capacity — mental illness or extreme emotional disturbance reduced the defendant''s culpability.","Adequate provocation — the defendant''s emotional state was caused by the victim''s extreme conduct."}'
WHERE common_charge_slug = 'voluntary-manslaughter' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Lower mens rea than murder — prosecution need only prove criminal negligence, not intent to kill.","Expert testimony on the standard of care and how the defendant''s conduct fell below it.","Often arises from DUI deaths, workplace incidents, or firearm negligence where the facts are clear."}',
  defense_opportunities = '{"Argue the defendant''s conduct was merely negligent (civil standard) rather than criminally negligent.","Challenge causation — the death may have resulted from an intervening cause or the victim''s own actions.","If based on an underlying unlawful act, defeating the unlawful act defeats the manslaughter charge.","Medical evidence that the death was caused by a pre-existing condition rather than the defendant''s conduct."}',
  common_defenses = '{"Ordinary negligence — the conduct was careless but did not rise to criminal negligence.","Intervening cause — a third party''s actions or an unexpected event caused the death.","Accident — the death was a tragic accident not caused by criminal conduct.","The underlying unlawful act was not committed by the defendant."}'
WHERE common_charge_slug = 'involuntary-manslaughter' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Medical records documenting serious bodily injury provide compelling evidence of the severity of the assault.","Intent to cause serious bodily injury can be inferred from the nature of the attack.","Vermont''s broad definition of ''deadly weapon'' includes many common objects used in assaults."}',
  defense_opportunities = '{"Self-defense — the defendant used force in response to an imminent threat of serious bodily harm.","Challenge the severity classification — argue the injury was not ''serious bodily injury'' as defined under Vermont law.","Mutual combat or consent may reduce culpability in certain contexts.","Mistaken identity or conflicting witness accounts about who initiated the violence."}',
  common_defenses = '{"Self-defense — the force used was proportionate to the threat faced.","Defense of others — the defendant acted to protect a third person from imminent harm.","The injuries did not constitute ''serious bodily injury'' under Vermont law.","Lack of intent — the injury was accidental or the result of negligence, not intentional conduct."}'
WHERE common_charge_slug = 'aggravated-assault' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Low threshold for bodily injury — even minor bruising or pain can satisfy the element.","Victim and witness testimony typically provides sufficient evidence for conviction.","Even attempted harmful contact without actual injury can constitute simple assault."}',
  defense_opportunities = '{"Self-defense is a complete defense if the force was reasonable and proportionate.","Challenge the credibility of the complainant, particularly in cases involving interpersonal disputes.","Argue the contact was accidental and not intentional, knowing, or reckless.","The alleged injury was too trivial to constitute ''bodily injury'' under the statute."}',
  common_defenses = '{"Self-defense — the defendant acted to protect themselves from harm.","Consent — the physical contact occurred in a context where both parties consented (e.g., sports, mutual pushing).","Accidental contact — no intent or recklessness was involved.","De minimis injury — the alleged injury was too slight to constitute a criminal offense."}'
WHERE common_charge_slug = 'simple-assault' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Physical evidence of injury (photographs, medical records) corroborates the victim''s testimony.","Prosecution can proceed even if the victim recants, using other evidence and testimony.","Offensive touching need not cause injury — unwanted physical contact can suffice."}',
  defense_opportunities = '{"Self-defense remains the primary affirmative defense for battery allegations.","Challenge whether the touching was truly offensive or harmful in the given context.","Consent defense — the physical contact was consensual or occurred in a context implying consent.","Credibility challenges where the allegation arises from a personal dispute with motive to fabricate."}',
  common_defenses = '{"Self-defense — the defendant was responding to an imminent physical threat.","Consent — the alleged victim consented to the physical contact.","Accidental contact — no intentional or reckless conduct occurred.","Fabrication — the complaint was motivated by a personal grudge or other motive."}'
WHERE common_charge_slug = 'battery' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"The combination of force/threat and theft makes this a serious charge with strong jury appeal for prosecution.","Surveillance video from stores, ATMs, and security cameras frequently identifies the perpetrator.","Victim testimony about the use of force or threat creates an emotional impact on juries."}',
  defense_opportunities = '{"Challenge identification — many robberies occur quickly, in stressful conditions that impair witness accuracy.","Argue the taking was without force or threat, reducing the charge to theft.","Alibi defense — the defendant was not present at the location of the robbery.","Duress — the defendant was compelled to participate in the robbery by threats from a co-defendant."}',
  common_defenses = '{"Mistaken identification — the victim or witnesses identified the wrong person.","No force or threat was used — the taking was a theft, not a robbery.","Alibi — the defendant was elsewhere when the robbery occurred.","Claim of right — the defendant genuinely believed they had a right to the property taken."}'
WHERE common_charge_slug = 'robbery' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Presence of a weapon dramatically increases the severity of the offense and jury hostility.","Forensic evidence linking a weapon to the defendant (DNA, fingerprints, ballistics) is strong.","Witness testimony about the presence of a weapon is typically vivid and memorable."}',
  defense_opportunities = '{"Challenge whether the weapon was real — toy or replica weapons may not satisfy the ''dangerous weapon'' element.","Misidentification defense, particularly when the perpetrator was masked or disguised.","The weapon belonged to a co-defendant and the defendant did not know it would be used.","Duress — the defendant was forced to participate under threat of harm."}',
  common_defenses = '{"Mistaken identification — the defendant was not the person who committed the armed robbery.","The weapon was not a dangerous weapon as defined by statute.","Duress — the defendant acted under the compulsion of a co-defendant or other person.","Lack of intent to permanently deprive — the defendant intended to return the property."}'
WHERE common_charge_slug = 'armed-robbery' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Victim testimony about confinement and fear is inherently compelling to juries.","Electronic evidence (cell phone locations, surveillance) can track movement and confinement.","The sustained nature of the offense creates multiple witnesses and evidence opportunities."}',
  defense_opportunities = '{"Challenge whether the movement or confinement was involuntary — argue the alleged victim consented.","Argue the confinement was incidental to another offense and did not constitute a separate kidnapping.","Custodial disputes may create factual contexts where the defendant had a good-faith belief in their legal right.","Challenge the duration and nature of the alleged confinement — brief or incidental restriction may not meet the threshold."}',
  common_defenses = '{"Consent — the alleged victim voluntarily accompanied the defendant.","Parental rights — in custody disputes, the defendant believed they had legal authority.","The movement or confinement was incidental to another offense and does not constitute kidnapping.","Mistaken identity — the defendant was not the person who committed the kidnapping."}'
WHERE common_charge_slug = 'kidnapping' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Fire investigators and accelerant detection provide strong forensic evidence.","Insurance records, financial motive, and prior threats establish motive and intent.","The destruction of property and danger to life create strong jury sympathy for the prosecution."}',
  defense_opportunities = '{"Challenge the fire investigation methodology — not all fires are intentionally set; accidental causes must be ruled out.","Argue the defendant was not present at or connected to the fire''s origin.","Challenge accelerant evidence — common household products can produce false positive results.","Lack of motive may undermine the prosecution''s theory of intentional fire-setting."}',
  common_defenses = '{"Accidental fire — the fire was caused by electrical malfunction, natural causes, or accident.","Alibi — the defendant was not present when the fire started.","Insufficient forensic evidence of intentional fire-setting.","Misidentification — someone else set the fire."}'
WHERE common_charge_slug = 'arson' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"The nature of the attack (weapon used, location of wounds, statements made) can establish intent to kill.","Victim survival allows for direct testimony about the attack and the defendant''s words and actions.","Medical testimony about the severity of injuries and likelihood of death supports the intent element."}',
  defense_opportunities = '{"Challenge the intent to kill — argue the defendant intended only to injure, not to kill.","Self-defense — the defendant acted in response to an imminent threat of serious harm.","The substantial step requirement means mere preparation or planning is insufficient for conviction.","Voluntary abandonment — if the defendant abandoned the attempt before completion."}',
  common_defenses = '{"Lack of intent to kill — the defendant did not intend to cause death.","Self-defense — the use of force was a response to an imminent deadly threat.","Abandonment — the defendant voluntarily abandoned the attempt.","Insufficient evidence of a ''substantial step'' toward the completion of the crime."}'
WHERE common_charge_slug = 'attempted-murder' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"The weapon itself is physical evidence that can be presented to the jury.","Medical evidence of injuries consistent with the weapon establishes the connection between the weapon and the harm.","Vermont''s broad definition of ''deadly weapon'' includes firearms, knives, and objects used as weapons."}',
  defense_opportunities = '{"Self-defense — the defendant used the weapon in response to an imminent threat.","The object used was not a ''deadly weapon'' as defined by law — challenge the classification.","The assault was accidental — the defendant did not intentionally use the object as a weapon.","Mutual combat where both parties were armed and engaged voluntarily."}',
  common_defenses = '{"Self-defense — the defendant was justified in using force due to an imminent threat.","The object was not a ''deadly weapon'' under Vermont law.","Accidental injury — the defendant did not intentionally wield the object as a weapon.","Defense of others — the defendant acted to protect a third person."}'
WHERE common_charge_slug = 'assault-with-deadly-weapon' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Surveillance footage, receipt records, and witness testimony establish the taking.","Possession of the stolen property shortly after the theft creates an inference of guilt.","Vermont''s relatively low grand larceny threshold of $900 captures many theft offenses as felonies."}',
  defense_opportunities = '{"Challenge the valuation of the stolen property — if below $900, the offense is reduced to petit larceny.","Claim of right — the defendant genuinely believed they had a legal right to the property.","Argue the defendant intended to return the property (negating intent to permanently deprive).","Mistaken identity — particularly in retail or public settings with limited identification evidence."}',
  common_defenses = '{"Claim of right — the defendant had a good-faith belief they were entitled to the property.","Lack of intent to permanently deprive the owner of the property.","Mistaken identity — the defendant was not the person who took the property.","The property value was below the grand larceny threshold."}'
WHERE common_charge_slug = 'theft-larceny' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Documentary evidence (receipts, appraisals, inventory records) establishes the property value.","Physical recovery of stolen property in the defendant''s possession is powerful evidence.","Financial records and surveillance footage often create a clear evidentiary trail."}',
  defense_opportunities = '{"Challenge the prosecution''s valuation of the property — independent appraisal may show value below $900.","Claim of right defense where the defendant believed they were the lawful owner.","The taking was a mistake or misunderstanding rather than intentional theft.","Return of property and restitution may support favorable plea negotiations."}',
  common_defenses = '{"Property valuation dispute — the fair market value was below the $900 grand larceny threshold.","Claim of right — genuine belief in ownership or entitlement.","Lack of intent — the taking was accidental or based on a misunderstanding.","Mistaken identity — the defendant was not the person who committed the theft."}'
WHERE common_charge_slug = 'grand-theft' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Often caught on camera or by store loss prevention, providing direct evidence.","The simplicity of the charge makes it easy for prosecution to prove the elements.","Prior theft convictions can be used to enhance sentencing."}',
  defense_opportunities = '{"First-time offenders may qualify for diversion or deferred sentencing programs.","Argue the defendant forgot to pay or made an honest mistake — negating intent.","Value disputes may reduce the charge to a lower level or support dismissal.","Community service and restitution agreements may be negotiated pre-trial."}',
  common_defenses = '{"Mistake — the defendant inadvertently took the item without intent to steal.","Claim of right — the defendant believed the property was theirs.","De minimis value — the property taken was of negligible worth.","Diversion eligibility — first-time offender programs as an alternative to prosecution."}'
WHERE common_charge_slug = 'petty-theft' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Store surveillance systems, loss prevention officers, and electronic article surveillance provide strong evidence.","The element of concealment can be proven even before the defendant leaves the store.","Civil recovery provisions allow the store to pursue additional damages beyond criminal penalties."}',
  defense_opportunities = '{"Argue the defendant intended to pay and had not left the store — no completed taking occurred.","Challenge loss prevention''s observations — partial or obstructed views may create reasonable doubt.","The item was accidentally concealed (fell into a bag, covered by other merchandise).","First-time offenders often qualify for diversion programs in Vermont."}',
  common_defenses = '{"No intent to steal — the defendant intended to pay for the item.","Accidental concealment — the item ended up concealed without the defendant''s knowledge.","Mistaken identity — store security identified the wrong person.","The defendant had not left the store, so no completed theft occurred."}'
WHERE common_charge_slug = 'shoplifting' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Physical evidence of forced entry (broken windows, pry marks, tool marks) establishes the unlawful entry element.","Items stolen from the premises link the defendant to the scene and establish intent.","Fingerprints, DNA, and surveillance footage at the point of entry are common forms of identification evidence."}',
  defense_opportunities = '{"Challenge the intent element — the defendant may have entered without intending to commit a crime.","Consent or authorization to enter — the defendant had permission to be on the premises.","Mistaken identity — physical evidence linking the defendant to the scene may be circumstantial.","The building was not an ''occupied dwelling,'' which significantly reduces the potential penalty."}',
  common_defenses = '{"Lack of intent — the defendant entered without the intent to commit a felony therein.","Authorization — the defendant had permission to enter the building.","Mistaken identity — the physical evidence does not conclusively identify the defendant.","Intoxication negating the specific intent to commit a felony inside the building."}'
WHERE common_charge_slug = 'burglary' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"The ''occupied dwelling'' enhancement reflects the heightened danger and resonates strongly with juries.","Physical evidence of entry and items taken from the residence establishes both elements efficiently.","Victim testimony about the emotional impact of a home invasion is powerful at sentencing."}',
  defense_opportunities = '{"Challenge whether the dwelling was ''occupied'' at the time of entry — this is a specific enhancement element.","Argue the defendant had authorization or a good-faith belief in permission to enter.","Challenge the timeline — if the defendant did not enter the dwelling, or the items were obtained elsewhere.","Negotiate for reduced charges where the dwelling was not occupied or no confrontation occurred."}',
  common_defenses = '{"The dwelling was not occupied at the time of entry, reducing the severity of the charge.","Permission to enter — the defendant had consent from an occupant.","Mistaken identity — forensic evidence does not conclusively tie the defendant to the scene.","Lack of intent to commit a felony inside the dwelling."}'
WHERE common_charge_slug = 'residential-burglary' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Vehicle identification numbers (VIN), registration records, and GPS tracking provide strong identification evidence.","Being found driving or in possession of a stolen vehicle creates a strong inference of guilt.","Surveillance cameras at parking lots, toll booths, and intersections often capture the theft."}',
  defense_opportunities = '{"Argue the defendant had permission or a good-faith belief in permission to use the vehicle.","Challenge whether the defendant knew the vehicle was stolen — particularly in cases involving third-party transfers.","Temporary use without intent to permanently deprive may negate the larceny element.","Mistaken identity where the vehicle was found abandoned and the defendant was not observed operating it."}',
  common_defenses = '{"Permission — the defendant believed they had the owner''s consent to use the vehicle.","Lack of knowledge — the defendant did not know the vehicle was stolen.","Temporary use — no intent to permanently deprive the owner.","Mistaken identity — the defendant was not the person who took the vehicle."}'
WHERE common_charge_slug = 'motor-vehicle-theft' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Possession of recently stolen property combined with inability to explain how it was obtained supports an inference of knowledge.","Below-market purchase price, no receipt, and suspicious circumstances demonstrate knowledge.","Electronic communications discussing the stolen nature of the goods are direct evidence."}',
  defense_opportunities = '{"Challenge the ''knowledge'' element — the defendant genuinely did not know the property was stolen.","The property was obtained through a legitimate transaction with no red flags.","Argue the defendant was an innocent purchaser who paid fair market value.","The property was not actually stolen, or the true owner consented to the transfer."}',
  common_defenses = '{"Lack of knowledge — the defendant did not know or have reason to know the property was stolen.","Legitimate purchase — the defendant acquired the property through a normal commercial transaction.","The property was not stolen — the alleged theft did not occur.","Mistaken identification of the property — the item in the defendant''s possession was not the stolen item."}'
WHERE common_charge_slug = 'receiving-stolen-property' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Physical evidence of damage and cost estimates from property owners establish the elements.","Surveillance footage, witness testimony, and social media posts often identify the perpetrator.","Damage exceeding $1,000 elevates the charge to a felony level."}',
  defense_opportunities = '{"Challenge the valuation of damages — lower estimates may reduce the charge severity.","Argue the damage was accidental, not intentional or reckless.","Mistaken identity — particularly for graffiti or overnight damage incidents.","Claim of right or property ownership — the defendant damaged their own property."}',
  common_defenses = '{"Accident — the damage was not intentional or reckless.","Mistaken identity — the defendant was not the person who caused the damage.","The defendant owned the property or had a claim of right to it.","The damage value was below the threshold for the charged level of offense."}'
WHERE common_charge_slug = 'vandalism' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Posted ''No Trespassing'' signs or prior written notice creates documentary evidence of the prohibition.","Property owner testimony about forbidding entry is straightforward evidence.","Repeat offenses carry enhanced penalties."}',
  defense_opportunities = '{"Challenge whether adequate notice was given — the prohibition must be clearly communicated.","Argue the defendant had a good-faith belief they had permission to be on the property.","The defendant entered for a legitimate purpose (delivering items, seeking help in an emergency).","The posted signs were not visible or the property boundaries were unclear."}',
  common_defenses = '{"Lack of notice — the defendant was not aware the property was off-limits.","Permission — the defendant had consent from someone with authority over the property.","Necessity — the defendant entered the property due to an emergency.","The property boundaries were unclear and the defendant did not realize they were trespassing."}'
WHERE common_charge_slug = 'trespassing' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Damage estimates from property owners and repair professionals establish the financial harm.","Intent can be inferred from the circumstances — deliberate acts of destruction are self-evident.","Felony charges apply when damage exceeds $1,000."}',
  defense_opportunities = '{"Argue the damage was accidental — spilling, dropping, or unintentional contact.","Challenge the damage valuation to keep the offense at misdemeanor level.","Consent — the property owner authorized the alteration or the defendant had a good-faith belief in authorization.","Mistaken identity where the damage occurred without direct witnesses."}',
  common_defenses = '{"Accident — the damage was unintentional.","Mistaken identity — the defendant was not responsible for the damage.","Consent — the property owner authorized the conduct that caused the damage.","Damage valuation dispute — the actual damage was less than alleged."}'
WHERE common_charge_slug = 'criminal-mischief' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Vermont allows prosecution to proceed without victim cooperation using other evidence (911 calls, photos, officer observations).","Excited utterances and present sense impressions are admissible hearsay exceptions frequently used in DV cases.","No-contact orders issued at arraignment prevent the defendant from influencing the victim''s testimony."}',
  defense_opportunities = '{"Self-defense — the defendant was defending themselves from the alleged victim''s aggression.","Challenge the reliability of 911 call statements and officer observations made in a chaotic environment.","Mutual combat — both parties were aggressors, and the defendant was not the primary aggressor.","Recanting victim testimony combined with lack of physical evidence may create reasonable doubt."}',
  common_defenses = '{"Self-defense — the defendant used force to protect themselves from the alleged victim''s attack.","Fabrication — the allegation was motivated by custody disputes, divorce, or personal animosity.","Mutual combat — both parties were engaged in a physical altercation.","Insufficient evidence — no independent witnesses or physical evidence corroborating the allegation."}'
WHERE common_charge_slug = 'domestic-violence' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Photographs of injuries taken by responding officers provide contemporaneous evidence.","Vermont''s mandatory arrest policy for domestic violence means officers must arrest the primary aggressor.","Prior domestic violence history is admissible to show pattern behavior."}',
  defense_opportunities = '{"Self-defense remains available — the defendant responded to the alleged victim''s physical aggression.","Challenge the ''family or household member'' relationship element if the parties'' relationship does not qualify.","Argue the physical contact was accidental or incidental, not intentional.","Cross-examine the alleged victim on inconsistencies and potential bias."}',
  common_defenses = '{"Self-defense — the defendant was protecting themselves from physical harm.","Accidental contact — the physical contact was unintentional.","The parties are not ''family or household members'' under the statute''s definition.","Fabrication motivated by a custody dispute, divorce proceedings, or desire for an advantage in court."}'
WHERE common_charge_slug = 'domestic-battery' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Vermont''s Department for Children and Families (DCF) investigations generate documented evidence that prosecution can use.","Medical evidence of neglect or harm to the child is compelling and difficult to challenge.","Mandatory reporting requirements mean that professionals (teachers, doctors) provide independent corroboration."}',
  defense_opportunities = '{"Challenge whether the defendant''s conduct actually created a risk of harm to the child.","Parenting practices vary widely — argue the conduct falls within the range of reasonable parental discipline.","The harm or risk was caused by someone else, not the defendant.","DCF investigation procedures may have been flawed, leading to inaccurate conclusions."}',
  common_defenses = '{"Reasonable parental discipline — the conduct was within the bounds of acceptable parenting.","Lack of knowledge — the defendant was not aware of the dangerous condition.","Another person caused the harm or created the risk.","The risk alleged was speculative and did not actually endanger the child."}'
WHERE common_charge_slug = 'child-endangerment' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Medical evidence of injuries (X-rays showing fractures, documented bruising patterns) provides objective proof.","Expert testimony on child abuse recognition patterns educates juries on non-accidental injuries.","Statements by the child victim, even if young, may be admissible under hearsay exceptions."}',
  defense_opportunities = '{"Challenge the medical evidence — some injuries attributed to abuse can have accidental or medical explanations.","The injuries were caused by an accident, fall, or rough play consistent with a child''s age.","Another caretaker or family member was responsible for the injuries.","Expert testimony challenging the prosecution''s medical opinions on causation."}',
  common_defenses = '{"Accidental injury — the child was injured through normal childhood activity.","Another person caused the injuries when the defendant was not present.","Medical condition causing bruising or injuries that mimic abuse.","Reasonable parental discipline — the conduct was within acceptable limits."}'
WHERE common_charge_slug = 'child-abuse' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"The protective order itself and proof of service establish the defendant''s knowledge of its terms.","GPS data, cell phone records, and surveillance footage can prove the defendant was at a prohibited location.","The violation is often documented by the protected party or law enforcement in real time."}',
  defense_opportunities = '{"Challenge whether the defendant was properly served with the protective order.","Argue the contact was accidental — the defendant did not know the protected party would be at the location.","The terms of the order are ambiguous as to what conduct is prohibited.","The protected party initiated the contact, and the defendant''s response was reasonable."}',
  common_defenses = '{"Lack of service — the defendant was never properly served with the protective order.","Accidental contact — the defendant did not know the protected party was present.","The protected party invited or initiated the contact.","The defendant''s conduct did not violate the specific terms of the order."}'
WHERE common_charge_slug = 'violation-protective-order' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Documentation of repeated contacts, messages, and surveillance provides the pattern element.","GPS tracking data, social media activity, and cell phone records corroborate the victim''s account.","Vermont''s stalking statute covers electronic communications and cyberstalking."}',
  defense_opportunities = '{"Challenge whether the conduct constitutes a ''pattern'' — isolated incidents may not meet the statutory threshold.","The defendant''s contact was for a legitimate purpose (shared children, business relationship).","The alleged victim''s fear was not reasonable under the circumstances.","First Amendment protections for speech and expression may limit what conduct qualifies as stalking."}',
  common_defenses = '{"No pattern — the contacts were isolated incidents, not a course of conduct.","Legitimate purpose — the contacts were related to shared responsibilities (custody, business).","The alleged victim''s fear was unreasonable given the nature of the communications.","Constitutional challenge — the defendant''s conduct was protected speech or expression."}'
WHERE common_charge_slug = 'stalking' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Electronic records (texts, emails, social media messages) provide clear evidence of the communications.","The pattern and content of communications are objectively verifiable.","Victim testimony about the impact of the harassment creates emotional weight."}',
  defense_opportunities = '{"First Amendment defense — the communications, while unwelcome, were protected speech.","The communications had a legitimate purpose and were not intended to harass.","Challenge whether the communications were actually sent by the defendant.","The alleged victim''s reaction was not reasonable given the content of the communications."}',
  common_defenses = '{"Protected speech — the communications were expressions of opinion or legitimate grievance.","Legitimate purpose — the communications were related to an ongoing dispute or shared responsibility.","The defendant did not send the communications — someone else used their device or account.","The frequency and content of the communications did not rise to the level of harassment."}'
WHERE common_charge_slug = 'harassment' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Medical evidence of neglect (malnutrition, untreated medical conditions, bedsores) is powerful.","Financial exploitation is often traceable through bank records and transaction histories.","Vermont''s Adult Protective Services investigations provide documented evidence."}',
  defense_opportunities = '{"Challenge the ''vulnerable adult'' designation — the alleged victim may not meet the statutory definition.","The care provided was adequate under the circumstances, even if not ideal.","Financial transactions were authorized by the adult when they were competent.","Another caretaker was responsible for the neglect or abuse."}',
  common_defenses = '{"Adequate care — the defendant provided appropriate care given the available resources.","Authorization — financial transactions were approved by the vulnerable adult.","Another person was responsible for the abuse or neglect.","The alleged victim is not a ''vulnerable adult'' under the statutory definition."}'
WHERE common_charge_slug = 'elder-abuse' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Physical recovery of the weapon provides tangible evidence.","Vermont, while generally permissive on firearms, prohibits carry during criminal activity.","Forensic evidence linking the weapon to the defendant (DNA, fingerprints) strengthens identification."}',
  defense_opportunities = '{"Vermont has permissive firearms laws — mere possession without criminal activity may not be an offense.","Challenge whether the item qualifies as a ''dangerous weapon'' under the statute.","The weapon was not in the defendant''s possession or control during the alleged crime.","The underlying crime was not committed, so the enhancement does not apply."}',
  common_defenses = '{"Lawful possession — the defendant was legally permitted to carry the weapon.","The defendant was not committing a crime when the weapon was in their possession.","The item was not a ''dangerous weapon'' under the statutory definition.","The weapon belonged to another person and was not in the defendant''s control."}'
WHERE common_charge_slug = 'weapons-possession' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Prior felony conviction is provable through court records.","Physical recovery of the firearm combined with the defendant''s fingerprints or DNA establishes possession.","Constructive possession doctrine applies when the firearm is found in the defendant''s home or vehicle."}',
  defense_opportunities = '{"Challenge constructive possession — the firearm was in a shared residence and belonged to another occupant.","The prior conviction may have been expunged, pardoned, or the rights may have been restored.","The defendant did not know the firearm was present in the location where it was found.","Challenge whether the item is a ''firearm'' under the statutory definition."}',
  common_defenses = '{"The firearm belonged to another person in the household, not the defendant.","Rights restored — the defendant''s firearm rights were restored after the felony conviction.","Lack of knowledge — the defendant did not know the firearm was present.","Temporary and innocent possession — the defendant briefly handled the firearm for a lawful purpose (e.g., safety)."}'
WHERE common_charge_slug = 'felon-in-possession' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Security screening at courthouses and government buildings often catches violations on entry.","The offense is straightforward — weapon in prohibited location is the entire charge.","Vermont restricts carry in courthouses even though it has constitutional carry elsewhere."}',
  defense_opportunities = '{"Vermont is a constitutional carry state — the defendant may not have known about the courthouse/government building exception.","Argue the defendant forgot the weapon was in their bag or on their person.","The ''state building'' designation may not have been clearly posted or communicated.","The weapon was discovered during an unlawful search, and the courthouse exception does not apply."}',
  common_defenses = '{"Lack of knowledge — the defendant did not realize they were carrying the weapon into a prohibited location.","The location was not clearly marked as a prohibited zone.","The weapon was non-functional or was not a weapon under the statutory definition.","Unlawful search — the weapon was discovered through an unconstitutional search."}'
WHERE common_charge_slug = 'concealed-carry-violation' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Ballistic evidence, spent casings, and damage from projectiles establish the discharge.","Witness testimony about hearing gunfire and seeing the defendant with a firearm is compelling.","The charge focuses on the reckless conduct, not the intent to harm, making it easier to prove."}',
  defense_opportunities = '{"The discharge was accidental — the firearm malfunctioned or was handled negligently rather than recklessly.","The discharge occurred on the defendant''s own rural property with no people nearby.","Self-defense — the discharge was in response to an imminent threat.","Challenge whether the discharge actually occurred or whether the defendant was the person who fired."}',
  common_defenses = '{"Accidental discharge — the firearm went off unintentionally.","Self-defense — the discharge was a justified response to an imminent threat.","No endangerment — the discharge occurred in a safe location with no risk to others.","Misidentification — the defendant was not the person who fired the weapon."}'
WHERE common_charge_slug = 'illegal-discharge' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Digital evidence (IP addresses, login records, financial transaction records) traces the fraud to the defendant.","Victim impact statements about the damage to credit and personal life resonate with juries.","Federal coordination is possible, adding pressure for cooperation or plea."}',
  defense_opportunities = '{"Challenge the digital evidence linking the defendant to the fraudulent activity — IP addresses and devices can be shared or spoofed.","The defendant used the information with authorization or based on a good-faith belief in permission.","Identity theft may have been committed by someone else using the defendant''s devices or accounts.","The information used was not ''personal identifying information'' as defined by the statute."}',
  common_defenses = '{"Authorization — the defendant had permission to use the personal information.","Mistaken identity — someone else used the defendant''s device or internet connection.","Lack of intent — the defendant did not intend to defraud or harm the victim.","The information used does not meet the statutory definition of ''personal identifying information.''"}'
WHERE common_charge_slug = 'identity-theft' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Financial records, bank statements, and audit trails provide clear documentary evidence.","Expert forensic accountant testimony can trace the misappropriation in detail.","The defendant''s position of trust makes the betrayal particularly impactful to juries."}',
  defense_opportunities = '{"Argue the funds were used for an authorized purpose or with the owner''s knowledge.","Challenge the accounting — errors in record-keeping may explain apparent discrepancies.","The defendant intended to return the funds and did not have the intent to permanently deprive.","The prosecution''s forensic accounting methodology may contain errors or assumptions."}',
  common_defenses = '{"Authorization — the defendant had permission to use the funds in the manner they did.","Accounting error — the discrepancy is the result of bookkeeping mistakes, not theft.","Intent to return — the defendant intended to repay the funds and did not intend permanent deprivation.","Good faith — the defendant genuinely believed their use of the funds was authorized."}'
WHERE common_charge_slug = 'embezzlement' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Forensic document examination can identify the forged handwriting, printing, or alterations.","The forged document itself is physical evidence that can be examined by the jury.","Digital forgery leaves metadata and editing trails that forensic analysts can detect."}',
  defense_opportunities = '{"Authorization — the defendant had permission to sign or alter the document on behalf of another.","The document was not ''forged'' — no intent to defraud existed.","Challenge the forensic document examiner''s conclusions — handwriting analysis has known reliability limitations.","The document was not used to defraud anyone or obtain anything of value."}',
  common_defenses = '{"Authorization — the defendant was permitted to sign or execute the document.","Lack of intent to defraud — the alteration was not made with fraudulent intent.","Challenge the reliability of handwriting or document analysis.","The document was not material — it could not have been used to defraud anyone."}'
WHERE common_charge_slug = 'forgery' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Federal Secret Service involvement brings significant investigative resources.","Physical evidence of counterfeiting equipment and materials is highly incriminating.","Passing counterfeit currency is often captured on surveillance cameras."}',
  defense_opportunities = '{"The defendant did not know the currency or document was counterfeit when they used it.","Challenge the chain of custody — the counterfeit items may have been introduced by another party.","The defendant received the counterfeit items innocently through a normal transaction.","No intent to defraud — the defendant possessed the items as novelties or for study."}',
  common_defenses = '{"Lack of knowledge — the defendant did not know the items were counterfeit.","Innocent receipt — the defendant received the counterfeit items unknowingly through a legitimate transaction.","No intent to defraud — the items were possessed for a non-fraudulent purpose.","Misidentification — the defendant was not the person who passed the counterfeit items."}'
WHERE common_charge_slug = 'counterfeiting' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Bank records prove the account balance at the time the check was issued.","The check itself is physical evidence, and the defendant''s signature establishes authorship.","Pattern of issuing bad checks demonstrates intent rather than accident."}',
  defense_opportunities = '{"The defendant genuinely believed there were sufficient funds when the check was written.","The funds were deposited before the check was presented but a bank error caused the failure.","Post-dating or conditional delivery of the check negates the intent element.","The check was issued based on a good-faith expectation of incoming funds."}',
  common_defenses = '{"Good faith — the defendant believed sufficient funds were available.","Bank error — the insufficient funds were the result of a bank processing mistake.","The check was post-dated or conditional, and the recipient agreed to hold it.","Restitution — the defendant made the check good promptly, negating criminal intent."}'
WHERE common_charge_slug = 'bad-checks' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Insurance company Special Investigation Units (SIUs) compile detailed evidence before referring cases.","Digital evidence, surveillance footage, and social media posts contradicting injury claims are devastating.","Expert testimony from medical professionals and accident reconstructionists exposes fabricated claims."}',
  defense_opportunities = '{"The claim was legitimate — the defendant genuinely suffered the loss or injury claimed.","Errors in the claim were inadvertent mistakes, not intentional misrepresentations.","Challenge the insurance company''s investigation methodology and potential bias.","The defendant relied on advice from a professional (attorney, adjuster) when filing the claim."}',
  common_defenses = '{"Legitimate claim — the loss or injury was real and accurately reported.","Inadvertent error — discrepancies in the claim were honest mistakes.","Reliance on professional advice — the defendant followed their advisor''s guidance.","The insurance company''s investigation was biased or incomplete."}'
WHERE common_charge_slug = 'insurance-fraud' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Transaction records, timestamps, and location data tie the fraud to the defendant.","Surveillance footage at the point of sale identifies the person using the card.","The victim''s testimony about not authorizing the transactions is straightforward."}',
  defense_opportunities = '{"Authorization — the defendant had permission to use the card from the cardholder.","Mistaken identity — the defendant''s identity was stolen and someone else used the card.","The transactions were authorized family or household purchases.","Challenge the identification evidence — surveillance quality and witness reliability."}',
  common_defenses = '{"Authorization — the cardholder gave the defendant permission to use the card.","Mistaken identity — the defendant was not the person who made the unauthorized transactions.","Shared account — the defendant believed they were authorized to make purchases on a shared account.","Lack of intent to defraud — the defendant intended to repay the cardholder."}'
WHERE common_charge_slug = 'credit-card-fraud' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Financial records, bank statements, and transaction patterns provide a documentary trail.","Federal coordination under the Bank Secrecy Act and anti-money laundering regulations adds investigative resources.","Expert testimony from financial investigators explains complex transaction patterns to juries."}',
  defense_opportunities = '{"Challenge the connection between the financial transactions and alleged criminal proceeds.","The defendant did not know the funds were derived from criminal activity.","The transactions had a legitimate business purpose unrelated to criminal activity.","Complex financial evidence may be difficult for juries to follow, creating reasonable doubt."}',
  common_defenses = '{"Lack of knowledge — the defendant did not know the funds were proceeds of criminal activity.","Legitimate business purpose — the transactions were part of normal commercial activity.","No underlying criminal activity — the predicate offense was not committed.","The defendant''s role was minimal and they did not knowingly participate in laundering."}'
WHERE common_charge_slug = 'money-laundering' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Documentary evidence of the misrepresentation (emails, letters, advertisements) is objective proof.","Victim testimony about reliance on the false statements establishes the causal connection.","Pattern evidence showing multiple victims strengthens the prosecution''s case."}',
  defense_opportunities = '{"The statements were opinions, puffery, or predictions — not actionable misrepresentations of fact.","The defendant genuinely believed the statements were true when made.","The victim did not actually rely on the defendant''s statements.","Challenge whether the defendant obtained anything of value through the alleged misrepresentation."}',
  common_defenses = '{"Good faith — the defendant believed their statements were true.","No reliance — the alleged victim did not rely on the defendant''s statements.","Puffery or opinion — the statements were not misrepresentations of material fact.","No intent to defraud — the defendant did not intend to deceive or harm the victim."}'
WHERE common_charge_slug = 'fraud-general' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Forensic evidence (DNA, rape kit results) provides scientific proof of contact.","Vermont''s trained forensic interviewers and SANE nurses ensure evidence is properly collected.","Prior bad act evidence may be admissible in sexual assault cases under Vermont Rules of Evidence."}',
  defense_opportunities = '{"Consent — the sexual contact was consensual between adults.","Challenge the forensic evidence — DNA proves contact but does not disprove consent.","Delayed reporting and inconsistencies in the complainant''s account may create reasonable doubt.","Challenge the investigation — were other suspects investigated, and was the investigation thorough?"}',
  common_defenses = '{"Consent — the sexual contact was voluntary and consensual.","Mistaken identity — the defendant was not the person involved.","Insufficient evidence — no physical evidence corroborates the allegation.","False accusation — the complaint is fabricated based on motive (revenge, custody dispute)."}'
WHERE common_charge_slug = 'sexual-assault' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Aggravating factors (weapon, serious bodily injury, multiple perpetrators) elevate the charge and penalties.","Medical evidence from SANE examinations and trauma documentation.","Vermont''s comprehensive approach to evidence collection (rape kits, forensic interviews) strengthens cases."}',
  defense_opportunities = '{"Consent defense where no aggravating factors are present.","Challenge the identification — cross-racial identification and stranger rape cases have high misidentification rates.","Alibi defense supported by independent evidence (surveillance footage, electronic records).","Constitutional challenges to the investigation procedures."}',
  common_defenses = '{"Consent — the sexual contact was consensual.","Alibi — the defendant was elsewhere when the assault allegedly occurred.","Mistaken identity — the complainant identified the wrong person.","False accusation motivated by personal animus or secondary gain."}'
WHERE common_charge_slug = 'rape' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Witness testimony about the exposure provides direct evidence.","Pattern evidence of repeated incidents strengthens the prosecution''s case.","Proximity to schools or children enhances the severity and jury reaction."}',
  defense_opportunities = '{"The exposure was accidental — wardrobe malfunction, changing clothes in what was believed to be a private area.","Challenge the witnesses'' ability to identify the defendant, especially at a distance or in low light.","The conduct did not rise to ''lewd and lascivious'' — it was not done for sexual gratification.","Mental health issues that explain the behavior may support treatment-based alternatives."}',
  common_defenses = '{"Accidental exposure — the defendant did not intentionally expose themselves.","Not lewd or lascivious — the exposure was not for sexual gratification.","Mistaken identity — the witnesses misidentified the defendant.","Privacy — the defendant believed they were in a private location."}'
WHERE common_charge_slug = 'indecent-exposure' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Undercover sting operations with recorded conversations provide direct evidence.","Electronic records (texts, emails, online ads) create a clear trail of the solicitation.","Financial transactions linked to the solicitation corroborate the intent."}',
  defense_opportunities = '{"Entrapment — law enforcement initiated and encouraged the solicitation.","The communications were misinterpreted — no actual agreement to exchange money for sexual services was reached.","The defendant withdrew from the solicitation before any overt act occurred.","First Amendment defense where the communications were protected speech."}',
  common_defenses = '{"Entrapment — the defendant was induced by law enforcement to solicit.","No agreement — the communications did not constitute an actual solicitation.","Withdrawal — the defendant abandoned the solicitation before completion.","Misunderstanding — the communications were misinterpreted by law enforcement."}'
WHERE common_charge_slug = 'solicitation-prostitution' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Digital forensics can recover deleted files, browser history, and download records.","IP address tracing and ISP records identify the subscriber associated with the download activity.","Federal coordination through ICAC task forces brings extensive resources."}',
  defense_opportunities = '{"Challenge the identification of the person who downloaded or viewed the material — shared computers and networks.","Malware or virus infection may have placed the files on the defendant''s device without their knowledge.","The defendant did not know the individuals in the images were minors.","Fourth Amendment challenge to the search warrant for the defendant''s electronic devices."}',
  common_defenses = '{"Unauthorized access — someone else used the defendant''s computer or account.","Malware — the files were placed on the device by malicious software.","Lack of knowledge — the defendant did not know the content depicted minors.","Unlawful search — the search warrant was deficient or the search exceeded its scope."}'
WHERE common_charge_slug = 'child-exploitation' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"The registration requirement, address, and deadline are documented in court records.","The defendant''s failure to appear at the registry within the required timeframe is objectively verifiable.","Enhanced penalties for repeat failures to register."}',
  defense_opportunities = '{"The defendant made a good-faith effort to register but was prevented by circumstances (homelessness, incapacity).","Challenge whether the defendant received proper notice of the registration requirement.","Administrative errors by the registry may have caused the apparent failure.","The underlying conviction requiring registration may be constitutionally deficient."}',
  common_defenses = '{"Lack of notice — the defendant was not properly informed of the registration requirement.","Good faith effort — the defendant attempted to register but was unable to do so.","Administrative error — the registry''s records are incorrect.","Challenge the constitutionality of the sex offender registration requirement as applied."}'
WHERE common_charge_slug = 'failure-to-register' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Birth certificates and school records establish the victim''s age conclusively.","The age of the victim eliminates consent as a defense.","Vermont law provides no mistake-of-age defense for sexual contact with minors below the age of consent."}',
  defense_opportunities = '{"Challenge whether sexual contact actually occurred — deny the actus reus.","Alibi defense — the defendant was not present at the time and location alleged.","Challenge the investigation for suggestibility in forensic interviews of the minor.","Fabrication by the complainant or a parent motivated by custody disputes or other conflicts."}',
  common_defenses = '{"No sexual contact occurred — the allegation is false.","Alibi — the defendant was elsewhere at the relevant time.","Fabrication — the complaint was manufactured by a parent or the minor for ulterior motives.","Insufficient evidence — no physical evidence or credible testimony supports the allegation."}'
WHERE common_charge_slug = 'statutory-rape' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Officer testimony about the defendant''s behavior is typically the primary evidence and is given deference.","Body camera footage provides objective documentation of the disorderly conduct.","The low threshold for conviction makes this an easy charge to establish."}',
  defense_opportunities = '{"First Amendment — the defendant''s speech or expression was constitutionally protected.","The behavior did not rise to the level of ''tumultuous'' or ''disorderly'' under the statute.","The defendant''s behavior was a reasonable response to provocation by others.","Challenge the officer''s characterization of events through body camera footage or witness testimony."}',
  common_defenses = '{"Constitutionally protected speech or expression.","The conduct was not ''disorderly'' as defined by the statute.","Provocation by another person led to the defendant''s response.","Selective enforcement — others engaged in similar conduct were not charged."}'
WHERE common_charge_slug = 'disorderly-conduct' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Officer testimony about the defendant''s physical resistance is given weight by courts.","Body camera footage often captures the resistance in real time.","Injuries to the officer during the arrest corroborate the resistance allegation."}',
  defense_opportunities = '{"The arrest itself was unlawful — if the underlying arrest was without probable cause, resistance may be justified.","The defendant''s conduct was passive non-compliance (going limp, verbal protests) rather than active resistance.","Excessive force by the officer provoked the defendant''s physical reaction.","The defendant did not know they were being arrested by law enforcement."}',
  common_defenses = '{"Unlawful arrest — the officer lacked probable cause, making the arrest unlawful.","Excessive force — the officer used unreasonable force, provoking the defendant''s physical response.","Passive resistance only — the defendant did not actively resist.","The defendant did not know the person was a law enforcement officer."}'
WHERE common_charge_slug = 'resisting-arrest' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Officer testimony about the defendant''s obstructive conduct is compelling evidence.","Electronic evidence (deleted messages, destroyed documents) can establish obstruction.","Body camera footage documents the obstruction in real time."}',
  defense_opportunities = '{"The defendant exercised their constitutional rights (remaining silent, refusing consent to search) — not obstruction.","The defendant''s conduct did not actually obstruct or interfere with a proceeding or investigation.","Lack of intent — the defendant did not knowingly or intentionally obstruct justice.","First Amendment protections for criticism of law enforcement versus actual obstruction."}',
  common_defenses = '{"Exercise of constitutional rights — silence, refusal to consent, requesting an attorney.","No actual obstruction — the defendant''s conduct did not impede the investigation or proceeding.","Lack of intent — the defendant did not intentionally obstruct.","Protected speech — verbal criticism of officers is not obstruction."}'
WHERE common_charge_slug = 'obstruction-justice' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"The court order and proof of violation are typically straightforward documentary evidence.","The judge who was ''contempted'' often has firsthand knowledge of the violation.","Both civil and criminal contempt are available — civil for compliance, criminal for punishment."}',
  defense_opportunities = '{"Inability to comply — the defendant was unable to meet the court''s requirements through no fault of their own.","The court order was ambiguous, and the defendant''s interpretation was reasonable.","Challenge whether the defendant had proper notice of the order''s requirements.","Purge conditions in civil contempt — the defendant can comply and be released."}',
  common_defenses = '{"Inability to comply — the defendant could not meet the order''s requirements despite good-faith efforts.","Ambiguity — the order was unclear and the defendant''s interpretation was reasonable.","Lack of notice — the defendant was not properly served with or informed of the order.","Due process violations in the contempt proceeding itself."}'
WHERE common_charge_slug = 'contempt-of-court' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Officer observations of signs of intoxication (slurred speech, unsteadiness, odor of alcohol) are standard evidence.","The defendant''s behavior in public provides the disorderly element beyond mere intoxication.","Repeat offenses demonstrate a pattern that courts treat with increasing severity."}',
  defense_opportunities = '{"Vermont has moved toward treating public intoxication as a public health issue rather than a criminal one.","Challenge whether the defendant''s behavior was actually ''disorderly'' beyond simply being intoxicated.","Medical conditions (diabetes, stroke, medication reactions) can mimic signs of intoxication.","The defendant was on private property or was not in a public place as defined by the statute."}',
  common_defenses = '{"Medical condition — the symptoms were caused by a medical issue, not intoxication.","Not disorderly — being intoxicated alone is not criminal without disorderly behavior.","Private property — the defendant was not in a public place.","Treatment-based alternative — diversion to substance abuse treatment."}'
WHERE common_charge_slug = 'public-intoxication' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"The conditions of release signed by the defendant document their obligation to appear.","Bail revocation upon failure to appear creates immediate incarceration consequences.","The charge is an additional criminal offense on top of the underlying case."}',
  defense_opportunities = '{"Argue the defendant had a valid reason for missing the court date (medical emergency, accident, miscommunication).","Challenge whether the defendant received adequate notice of the court date.","The defendant appeared voluntarily shortly after the missed date, showing no intent to flee.","Administrative error in the court''s scheduling or notification process."}',
  common_defenses = '{"Valid reason — medical emergency, hospitalization, or unavoidable circumstance.","Lack of notice — the defendant was not properly notified of the court date.","Good faith — the defendant appeared as soon as possible after the missed date.","Administrative error — the court''s records or notification system failed."}'
WHERE common_charge_slug = 'failure-to-appear' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"The defendant''s own statements in the report are documented and can be compared against evidence.","Witness testimony and physical evidence contradicting the report establish falsity.","Motive evidence (insurance fraud, retaliation, alibi creation) strengthens the case."}',
  defense_opportunities = '{"The report was based on the defendant''s genuine belief, even if ultimately incorrect.","Challenge whether the defendant knew the report was false at the time it was made.","The report contained some true information mixed with inaccuracies — not wholly fabricated.","The defendant retracted the report before law enforcement relied on it."}',
  common_defenses = '{"Good faith belief — the defendant genuinely believed the report was accurate when filed.","Mistake — the inaccuracies in the report were honest errors, not intentional fabrications.","Retraction — the defendant corrected the report before any harm resulted.","The report was substantially true, with only minor inaccuracies."}'
WHERE common_charge_slug = 'false-report' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Text messages, voicemails, and social media posts provide documentary evidence of the threat.","Victim testimony about the fear caused by the threat is compelling.","Context evidence (prior conflicts, domestic violence history) supports the seriousness of the threat."}',
  defense_opportunities = '{"First Amendment — the statement was hyperbole, venting, or political speech, not a true threat.","The statement was conditional or hypothetical and did not place a reasonable person in fear.","Context shows the statement was made in jest and was not taken seriously by the recipient.","The defendant did not intend the statement to be threatening."}',
  common_defenses = '{"Not a ''true threat'' — the statement was protected speech, hyperbole, or rhetorical.","No intent to threaten — the defendant did not mean the statement as a threat.","The alleged victim''s fear was unreasonable given the context.","The statement was conditional and not an imminent threat of violence."}'
WHERE common_charge_slug = 'criminal-threat' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Transcript evidence and prior sworn statements provide direct proof of the false testimony.","Contradictory evidence showing the truth of the matter establishes the falsity.","The ''material matter'' element is broadly interpreted by courts."}',
  defense_opportunities = '{"The statement was literally true, even if misleading — perjury requires a false statement of fact.","The defendant genuinely believed the statement was true when made.","The statement was not ''material'' to the proceeding — it concerned an insignificant detail.","Ambiguity in the question asked led to a misunderstanding, not intentional falsehood."}',
  common_defenses = '{"Good faith belief — the defendant believed the statement was true.","Literally true — the statement, while misleading, was technically accurate.","Immaterial — the false statement did not relate to a material issue.","Ambiguity — the question was unclear and the answer was reasonable given its phrasing."}'
WHERE common_charge_slug = 'perjury' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Financial records tracing payments between the defendant and the official provide direct evidence.","Electronic communications discussing the exchange are powerful proof.","Cooperating witnesses (often the official or an intermediary) provide testimony."}',
  defense_opportunities = '{"The payment was a lawful campaign contribution or gift within legal limits.","No quid pro quo — there was no agreement linking the payment to any official action.","The defendant did not know the recipient was a public official or that the payment was improper.","Entrapment — law enforcement solicited the bribe."}',
  common_defenses = '{"Lawful contribution — the payment was a legitimate campaign donation or gift.","No quid pro quo — no agreement linked the payment to official action.","Lack of intent — the defendant did not intend to influence official conduct.","Entrapment — law enforcement induced the defendant to offer the bribe."}'
WHERE common_charge_slug = 'bribery' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Custody records, facility logs, and officer testimony establish the defendant was in lawful custody.","The escape itself is typically documented through surveillance, roll calls, and incident reports.","Additional charges often accompany escape (assault on officers, property damage)."}',
  defense_opportunities = '{"Duress — the defendant escaped due to imminent threats to their safety within the facility.","The custody was unlawful — if the underlying detention was without authority, escape may be justified.","The defendant was released by error and did not affirmatively escape.","Voluntary return shortly after the escape may mitigate penalties."}',
  common_defenses = '{"Duress — conditions in custody created a threat of serious bodily harm.","Unlawful custody — the underlying detention or arrest was without legal authority.","Administrative error — the defendant was mistakenly released and did not escape.","Voluntary return — the defendant returned to custody voluntarily."}'
WHERE common_charge_slug = 'escape-custody' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Veterinary evidence of the animal''s condition and injuries provides expert testimony.","Photographs and video of the animal''s condition are emotionally impactful evidence.","Vermont has strong animal welfare laws and public sympathy for animal cruelty cases is high."}',
  defense_opportunities = '{"The defendant provided reasonable care given their resources and knowledge.","The animal''s condition was caused by illness or injury, not neglect or cruelty.","Agricultural or husbandry practices that are standard in the industry may not constitute cruelty.","Another person was responsible for the animal''s care and caused the neglect."}',
  common_defenses = '{"Adequate care — the defendant provided reasonable care for the animal.","Medical condition — the animal''s condition was caused by illness, not cruelty.","Agricultural exemption — the practices were standard animal husbandry.","Another caretaker was responsible for the animal."}'
WHERE common_charge_slug = 'animal-cruelty' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Probation officer testimony and supervision records document the violation.","Drug test results, missed appointments, and police reports provide objective evidence.","The original sentence can be imposed in full upon revocation."}',
  defense_opportunities = '{"Argue the violation was technical and minor, warranting a sanction short of revocation.","The defendant made substantial efforts to comply despite the violation.","Challenge the accuracy of the evidence (drug test false positive, incorrect reporting dates).","Present mitigating circumstances explaining the violation (job loss, homelessness, medical issues)."}',
  common_defenses = '{"Substantial compliance — the defendant made genuine efforts to follow probation conditions.","Mitigating circumstances — external factors beyond the defendant''s control caused the violation.","Challenge the evidence — false positive drug test, incorrect records.","The violation was technical and minor, not warranting revocation."}'
WHERE common_charge_slug = 'probation-violation' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Parole officers closely monitor parolees, generating detailed records of compliance.","GPS monitoring, drug testing, and regular check-ins provide objective evidence of violations.","The remaining sentence can be reinstated upon revocation."}',
  defense_opportunities = '{"Argue the violation was technical and should be addressed with graduated sanctions.","Present evidence of rehabilitation and compliance in other areas of parole conditions.","Challenge the evidence of the violation — GPS errors, testing inaccuracies.","Mitigating circumstances explain the violation without excusing it."}',
  common_defenses = '{"Technical violation — the violation was minor and does not warrant re-incarceration.","Rehabilitation — the parolee has made significant progress and the violation was an aberration.","Challenge the evidence — GPS tracking errors, false positive drug tests.","Mitigating circumstances — circumstances beyond the parolee''s control contributed to the violation."}'
WHERE common_charge_slug = 'parole-violation' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Any assistance, encouragement, or facilitation of the crime can establish liability.","Electronic communications showing planning or coordination are powerful evidence.","Accomplice liability casts a wide net — the defendant need not have been physically present."}',
  defense_opportunities = '{"The defendant did not know a crime was being planned or committed.","Mere presence at the scene is insufficient — the defendant must have actively assisted.","The defendant withdrew from the criminal plan before the crime was committed.","The defendant''s assistance was too minimal or attenuated to constitute aiding and abetting."}',
  common_defenses = '{"Lack of knowledge — the defendant did not know a crime was being committed.","Mere presence — the defendant was present but did not actively participate.","Withdrawal — the defendant withdrew from the plan before the crime occurred.","The defendant''s alleged assistance was too minor to establish accomplice liability."}'
WHERE common_charge_slug = 'aiding-abetting' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Preparation evidence (acquiring weapons, casing a location, purchasing materials) establishes the substantial step.","Confessions or statements of intent are direct evidence of the defendant''s plan.","The maximum penalty is the same as the completed offense, providing strong plea leverage."}',
  defense_opportunities = '{"Argue the defendant''s actions were mere preparation and did not constitute a ''substantial step.''","Voluntary abandonment — the defendant chose not to complete the crime.","Legal impossibility — the crime could not have been completed under the circumstances.","The defendant''s statements were aspirational or hypothetical, not indicative of genuine intent."}',
  common_defenses = '{"Mere preparation — the defendant''s actions did not go beyond planning.","Voluntary abandonment — the defendant voluntarily stopped before completing the crime.","Impossibility — the crime could not have been completed.","Lack of intent — the defendant did not genuinely intend to commit the crime."}'
WHERE common_charge_slug = 'attempt' AND jurisdiction = 'VT';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Electronic communications (texts, calls, emails) documenting the agreement are powerful evidence.","Co-conspirator testimony — one participant cooperating with prosecution can establish the agreement.","Each member is liable for all acts committed in furtherance of the conspiracy."}',
  defense_opportunities = '{"Challenge the existence of an agreement — mere association or conversation is not conspiracy.","The defendant withdrew from the conspiracy before any overt act was committed.","The alleged co-conspirators were government agents — no genuine agreement with a private party.","The defendant''s statements were hypothetical or joking, not an actual agreement to commit a crime."}',
  common_defenses = '{"No agreement — there was no meeting of the minds to commit a crime.","Withdrawal — the defendant withdrew from the conspiracy before completion.","Government agent — the sole co-conspirator was a government agent (no genuine conspiracy).","Lack of intent — the defendant did not intend to participate in criminal activity."}'
WHERE common_charge_slug = 'conspiracy' AND jurisdiction = 'VT';

-- VA enrichment
UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Mandatory minimum penalties for elevated BAC tiers (0.15-0.20 and 0.20+) limit judicial discretion.","Virginia Alcohol Safety Action Program (VASAP) enrollment is mandatory for all DWI convictions."}',
  defense_opportunities = '{"Challenge the accuracy and calibration of the breath testing device under Virginia''s strict testing protocols.","Attack the legality of the initial traffic stop — Virginia courts strictly enforce Fourth Amendment protections.","Challenge whether the officer had probable cause to administer field sobriety tests.","Rising BAC defense — Virginia''s tests are typically administered after a delay, allowing argument that BAC was below 0.08 while driving."}',
  common_defenses = '{"Improper stop — no reasonable suspicion or probable cause for the traffic stop.","Field sobriety tests improperly administered or scored.","Breath test machine calibration or maintenance defects.","Medical conditions (GERD, diabetes, dental work) affecting breath test accuracy."}'
WHERE common_charge_slug = 'dui-dwi' AND jurisdiction = 'VA';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Mandatory minimum $250 fine and license revocation for one year creates immediate consequences.","Per se BAC of 0.08 eliminates the need to prove actual impairment.","VASAP enrollment is mandatory and creates additional pressure for plea agreements.","Enhanced penalties for BAC 0.15+ create leverage for prosecutors to negotiate down."}',
  defense_opportunities = '{"First offense carries no mandatory jail time absent BAC enhancement, allowing room for restricted licenses and probation.","Restricted license available for VASAP completion provides incentive for negotiating favorable terms.","Challenge whether the BAC test was administered within the statutory time window after operation.","Virginia''s courts give weight to challenges to officer training and certification on field sobriety tests."}',
  common_defenses = '{"Unlawful traffic stop — no reasonable articulable suspicion.","Faulty breath test results — calibration, observation period violations, or operator error.","Rising BAC defense — BAC was below 0.08 at the time of actual operation.","Necessity — driving was a response to a genuine emergency."}'
WHERE common_charge_slug = 'dui-first-offense' AND jurisdiction = 'VA';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Different mandatory minimums for second offense within 5 years versus 5-10 years gives prosecutors leverage.","Third offense within 10 years is a Class 6 Felony with up to 5 years imprisonment.","Indefinite license revocation for third or subsequent offenses creates severe collateral consequences."}',
  defense_opportunities = '{"Challenge the validity of out-of-state prior convictions used for enhancement.","Verify proper representation by counsel at prior pleas — uncounseled priors may be excludable.","The lookback period varies (5 years vs. 10 years) — argue prior conviction falls outside the relevant window.","Constitutional challenges to prior convictions where due process was denied."}',
  common_defenses = '{"Invalid prior conviction — entered without effective assistance of counsel.","Prior conviction outside the applicable lookback window.","Constitutional challenge to current stop, arrest, or testing.","Treatment-based alternatives where substance abuse disorder is documented."}'
WHERE common_charge_slug = 'dui-repeat-offense' AND jurisdiction = 'VA';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Blood test results showing presence of controlled substances provide scientific foundation.","Combined influence of alcohol and drugs broadens the scope of conduct that can be prosecuted.","Same penalty structure as alcohol DWI gives no leniency for drug-only impairment."}',
  defense_opportunities = '{"No per se limit for drugs — prosecution must prove actual impairment beyond a reasonable doubt.","Mere presence of drug metabolites in blood does not prove impairment at the time of driving.","DRE protocol is subjective and challengeable on scientific reliability grounds.","Challenge the chain of custody and handling of blood samples used for toxicology."}',
  common_defenses = '{"Lawful prescription use — medication taken as prescribed.","Insufficient proof of impairment — only metabolites detected, not impairment.","Challenge the DRE officer''s qualifications and adherence to protocol.","Fourth Amendment challenge to the blood draw warrant or consent."}'
WHERE common_charge_slug = 'dui-drugs' AND jurisdiction = 'VA';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Second refusal becomes a Class 2 Misdemeanor; third becomes a Class 1 Misdemeanor.","Police testimony about reading the implied consent warning is typically straightforward.","Refusal can be used as evidence of consciousness of guilt at the underlying DWI trial."}',
  defense_opportunities = '{"Challenge whether the implied consent warning was properly read in full.","The defendant did not ''unreasonably'' refuse — confusion, intoxication itself, or medical issues may explain the refusal.","Argue the underlying DWI arrest was unlawful, making the implied consent inapplicable.","The defendant requested an attorney, and refusal was based on this constitutional right."}',
  common_defenses = '{"Improper administration of implied consent warning.","Unlawful arrest — the underlying DWI stop was without probable cause.","Medical condition prevented compliance with the test.","Confusion about the consequences of refusal (especially relevant for non-English speakers)."}'
WHERE common_charge_slug = 'refusing-breath-test' AND jurisdiction = 'VA';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Virginia is one of the few states where reckless driving is a criminal misdemeanor (Class 1) rather than a traffic infraction.","Radar and lidar evidence is typically straightforward and difficult to challenge.","Class 1 Misdemeanor classification creates serious collateral consequences (criminal record, employment impact)."}',
  defense_opportunities = '{"Challenge the accuracy of radar/lidar measurements — calibration, certification, and operator training requirements.","Speed measurement may have captured another vehicle, not the defendant''s.","Necessity defense for genuine emergencies (medical, safety).","Plea negotiation for improper driving (a non-criminal infraction) is common in Virginia."}',
  common_defenses = '{"Necessity — driving was a response to a genuine emergency.","Speedometer error — the speedometer was inaccurate due to non-standard tire size or calibration issues.","Radar/lidar challenges — improper calibration, operator error, or wrong target identification.","Mistaken identification — the speed reading captured a different vehicle."}'
WHERE common_charge_slug = 'reckless-driving' AND jurisdiction = 'VA';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"DMV records establish suspension status and provide constructive notice through mailed notification.","Virginia treats this as a misdemeanor with potential jail time and additional license suspension.","Subsequent offenses carry mandatory jail time."}',
  defense_opportunities = '{"Challenge whether the defendant received actual notice of the suspension.","Administrative errors in DMV records may show the license was actually valid at the time.","Necessity defense for genuine emergencies."}',
  common_defenses = '{"Lack of knowledge — the defendant was not aware of the suspension.","Administrative error — DMV records incorrectly reflected suspension status.","Necessity — driving was a response to an emergency.","The license was reinstated before the date of driving."}'
WHERE common_charge_slug = 'driving-on-suspended' AND jurisdiction = 'VA';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Surveillance cameras, witness identifications, and vehicle damage evidence are common.","Virginia law requires stopping, providing identifying information, and rendering aid.","Failure on any element of the duty to stop supports conviction."}',
  defense_opportunities = '{"Argue the defendant was unaware an accident occurred, particularly in low-speed or minor-impact scenarios.","Challenge identification evidence — witnesses at night or under stress are unreliable.","The defendant returned to the scene shortly after leaving, demonstrating no intent to evade.","Vehicle damage may have alternative explanations unrelated to the alleged accident."}',
  common_defenses = '{"Lack of knowledge — the defendant did not know an accident occurred.","Misidentification — the vehicle or driver was incorrectly identified.","The defendant left to seek help or for personal safety reasons.","Duress — leaving was due to fear for personal safety."}'
WHERE common_charge_slug = 'hit-and-run' AND jurisdiction = 'VA';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Virginia retains the death penalty for capital murder under aggravating circumstances.","Premeditation can be inferred from the manner of the killing, weapons used, and prior conduct.","Felony murder rule applies when death occurs during enumerated felonies."}',
  defense_opportunities = '{"Challenge premeditation — argue the killing was impulsive, supporting reduction to second-degree murder.","Self-defense or defense of others where the use of deadly force was reasonable.","Challenge the underlying felony if the case is based on felony murder.","Diminished capacity due to mental illness or intoxication may negate the specific intent."}',
  common_defenses = '{"Self-defense — reasonable belief that deadly force was necessary to prevent imminent harm.","Lack of premeditation — the killing was not willful, deliberate, and premeditated.","Insanity — the defendant could not appreciate the wrongfulness of their conduct.","Mistaken identity — the defendant was not the killer."}'
