-- WI enrichment
UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Lifetime lookback for prior OWI offenses means decades-old convictions elevate current charges to felony level","Per se BAC threshold of .08 eliminates the need to prove actual impairment when chemical test results are available"}',
  defense_opportunities = '{"Challenge the calibration records and maintenance logs of the Intoxilyzer device, as Wisconsin courts have suppressed results from improperly maintained instruments","Contest the legality of the traffic stop under the Fourth Amendment — Wisconsin requires reasonable suspicion, and field sobriety test administration errors can undermine probable cause","For drug OWI, challenge whether the restricted controlled substance was pharmacologically active at the time of driving, since THC metabolites persist in blood long after impairment ends"}',
  common_defenses = '{"Improper stop — officer lacked reasonable suspicion for initial traffic stop","Rising blood alcohol defense — BAC was below .08 at time of driving but rose between the stop and the chemical test","Involuntary intoxication — medication interaction or unknowing consumption of alcohol","Challenge to field sobriety testing — non-standardized administration or medical conditions affecting performance"}'
WHERE common_charge_slug = 'dui-dwi' AND jurisdiction = 'WI';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Chemical test refusal under implied consent triggers automatic 12-month license revocation and may be used as evidence of consciousness of guilt","Even as a civil forfeiture, conviction triggers mandatory 6-9 month license revocation and alcohol assessment"}',
  defense_opportunities = '{"Non-criminal civil forfeiture status means no jail time, no criminal record, and lower standard of proof arguments available","Challenge the 20-minute observation period required before breath testing — failure to observe is grounds for suppression","Negotiate for reduced charges such as inattentive driving or absolute sobriety violation to avoid OWI-related license consequences"}',
  common_defenses = '{"Mouth alcohol contamination — recent use of mouthwash, GERD, or dental work affecting breath test accuracy","Improper observation period before chemical testing","Medical condition mimicking impairment (diabetes, neurological conditions)","Rising BAC — defendant was below .08 while actually operating the vehicle"}'
WHERE common_charge_slug = 'dui-first-offense' AND jurisdiction = 'WI';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Wisconsin''s lifetime lookback means any prior OWI from any state, at any time, counts toward the repeat offense level","Mandatory minimum incarceration increases sharply: 5 days (2nd), 45 days (3rd), 60 days (4th), 18 months (5th/6th)","Fourth offense is automatically a Class H Felony regardless of when prior offenses occurred"}',
  defense_opportunities = '{"Challenge the validity of prior OWI convictions — if a prior was obtained without proper counsel or constitutional protections, it may not count for enhancement","Seek placement in the drug court or OWI treatment court program as an alternative to mandatory incarceration","Negotiate for extended supervision or electronic monitoring in lieu of a portion of mandatory jail time where statutes allow judicial discretion","Contest the accuracy of the prior offense record, particularly out-of-state convictions with incomplete documentation"}',
  common_defenses = '{"Invalid prior convictions — prior plea taken without counsel or without understanding of rights","Constitutional challenge to the traffic stop or arrest procedure","Chemical test reliability — challenge instrument calibration, operator certification, or chain of custody","Necessity defense — driving was required to prevent greater harm"}'
WHERE common_charge_slug = 'dui-repeat-offense' AND jurisdiction = 'WI';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Blood tests for restricted substances are highly sensitive and can detect presence well below pharmacologically active levels","Prosecution can rely on Drug Recognition Expert (DRE) protocol testimony to establish impairment beyond chemical test results"}',
  defense_opportunities = '{"Challenge whether a detected substance was at a pharmacologically active level at the time of driving versus mere residual presence","Contest the DRE evaluation protocol — DRE conclusions are subjective and the 12-step protocol has documented error rates","For prescription medications, argue lawful use under valid prescription and that the substance was taken as directed","Challenge the blood draw procedure — improper venipuncture, contamination of sample, or lack of proper preservative in blood vial"}',
  common_defenses = '{"Lawful prescription use — medication taken as directed by physician","No actual impairment — chemical presence alone does not prove impairment for non-per-se substances","Blood sample contamination or improper storage affecting test reliability","Involuntary intoxication — unknowing ingestion of controlled substance"}'
WHERE common_charge_slug = 'dui-drugs' AND jurisdiction = 'WI';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Broad statutory language (''endangered the safety of any person or property'') gives prosecution wide latitude in charging","Dashcam, body cam, and surveillance footage frequently provide compelling evidence of driving behavior","Often paired with other charges (OWI, fleeing) creating cumulative sentencing exposure"}',
  defense_opportunities = '{"Challenge whether the driving behavior actually rose to ''wanton disregard for safety'' versus mere negligence or carelessness","Negotiate reckless driving as a plea reduction from OWI to avoid OWI-specific consequences (license revocation, ignition interlock, insurance surcharges)","Present evidence of road conditions, mechanical failure, or emergency circumstances that explain the driving behavior"}',
  common_defenses = '{"Emergency circumstances — defendant was responding to a genuine emergency","Mechanical failure — vehicle malfunction caused the erratic driving","Insufficient evidence — driving behavior did not rise to statutory ''wanton disregard'' standard","Misidentification of the driver"}'
WHERE common_charge_slug = 'reckless-driving' AND jurisdiction = 'WI';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Surveillance camera networks and modern vehicle identification technology make identification of the vehicle highly likely","Consciousness of guilt inference from fleeing the scene is powerful before a jury","Hit-and-run involving death is a Class D Felony (up to 25 years), creating significant sentencing exposure"}',
  defense_opportunities = '{"Challenge whether the defendant had actual knowledge that an accident occurred — noise, road conditions, or vehicle size may prevent awareness","Present evidence that the defendant left the scene due to fear for personal safety and reported the accident shortly after"}',
  common_defenses = '{"Lack of knowledge — defendant was unaware a collision occurred","Fear of harm — defendant left due to reasonable fear of violence at the scene and promptly reported the accident","Misidentification of the vehicle or driver","Duress — defendant fled under threat from passengers or others"}'
WHERE common_charge_slug = 'hit-and-run' AND jurisdiction = 'WI';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"OWI homicide only requires proof that defendant was intoxicated and caused the death — no need to prove recklessness beyond the intoxication itself","Chemical test results establishing BAC above .08 combined with the fatal collision create a straightforward prosecution theory","Juries are typically sympathetic to victims in fatality cases, creating strong emotional weight"}',
  defense_opportunities = '{"Challenge the causal link between intoxication and the fatal collision — argue that an independent intervening cause (other driver, road defect, mechanical failure) caused the death","Contest the BAC test results through chain of custody challenges, instrument reliability, or timing between accident and blood draw","Argue that the victim''s own conduct (failure to wear seatbelt, their own impairment, traffic violations) was the proximate cause of death"}',
  common_defenses = '{"Intervening cause — another driver''s negligence or external factor caused the fatal collision","Challenge to causation — intoxication was not the proximate cause of death","Chemical test unreliability — blood draw timing, contamination, or instrument error","Victim''s contributory conduct as proximate cause of the fatal injury"}'
WHERE common_charge_slug = 'vehicular-homicide' AND jurisdiction = 'WI';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Physical evidence at the crash scene (skid marks, vehicle data recorders, speed calculations) often establishes negligence clearly","Does not require proof of intoxication, making this easier to prove than OWI homicide"}',
  defense_opportunities = '{"Distinguish between ordinary negligence (civil liability) and criminal negligence (criminal liability) — the conduct must be a gross deviation from the standard of care","Present evidence of sudden mechanical failure, unforeseeable road conditions, or medical emergency to negate criminal negligence","Negotiate from OWI homicide down to negligent homicide to avoid the 5-year mandatory minimum"}',
  common_defenses = '{"Ordinary negligence versus criminal negligence — conduct did not rise to the criminal standard","Sudden emergency doctrine — unforeseeable circumstance caused the accident","Mechanical failure — vehicle defect was the actual cause","Victim''s conduct contributed to or caused the fatal outcome"}'
WHERE common_charge_slug = 'vehicular-manslaughter' AND jurisdiction = 'WI';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"DMV records provide straightforward documentary proof of suspension status","Notice of suspension sent by certified mail creates a presumption of knowledge under Wisconsin law","OWI-related suspensions carry enhanced penalties, creating additional sentencing leverage"}',
  defense_opportunities = '{"Challenge whether the defendant had actual knowledge of the suspension — mail delivery failures, address changes, or administrative errors in notification","Seek occupational license reinstatement as part of a resolution to reduce ongoing exposure","Argue that the underlying suspension was improperly imposed, which may invalidate the driving-on-suspended charge"}',
  common_defenses = '{"Lack of knowledge — defendant never received notice of suspension","Invalid underlying suspension — administrative error in the suspension process","Necessity — driving was required for an emergency situation","Occupational license covered the driving at issue"}'
WHERE common_charge_slug = 'driving-on-suspended' AND jurisdiction = 'WI';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Fleeing is always a felony in Wisconsin (minimum Class I), creating serious exposure even for basic flight","Police dashcam and body cam footage typically provides clear evidence of the pursuit","If death results during the pursuit, the charge escalates to a Class F Felony (up to 12.5 years)","Prosecution can charge fleeing alongside the underlying offense, creating cumulative sentencing"}',
  defense_opportunities = '{"Challenge whether the officer''s signal to stop was clearly visible or audible to the defendant — tinted windows, road noise, music may prevent perception","Argue the defendant was attempting to reach a safe, well-lit location before stopping rather than attempting to evade","Contest the ''knowingly'' element — if defendant did not realize police were signaling them specifically"}',
  common_defenses = '{"Lack of awareness — defendant did not see or hear the officer''s signal to stop","Seeking a safe location — defendant was driving to a well-lit, populated area before stopping","Mistaken identity — officer pursued the wrong vehicle","Duress — defendant fled due to threats from passengers"}'
WHERE common_charge_slug = 'fleeing-eluding' AND jurisdiction = 'WI';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Physical possession or constructive possession (drugs found in defendant''s vehicle, home, or personal effects) is often supported by strong physical evidence"}',
  defense_opportunities = '{"First-offense simple possession is a misdemeanor — drug court and deferred prosecution programs may result in dismissal upon completion","Challenge constructive possession — proximity to contraband alone does not establish knowing possession, especially in shared spaces","Contest the legality of the search that produced the drugs — Fourth Amendment violations require suppression of evidence"}',
  common_defenses = '{"Illegal search and seizure — drugs obtained through warrantless search without valid exception","Lack of knowledge — defendant did not know the substance was present or was a controlled substance","Lack of possession — drugs belonged to another person in a shared space","Entrapment — law enforcement induced the defendant to possess drugs they would not otherwise have possessed"}'
