UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Wisconsin has not legalized recreational or medical marijuana, so any amount is criminal","Second THC possession offense is automatically a Class I Felony (up to 3.5 years)","Field testing kits provide rapid presumptive identification, giving officers probable cause for arrest"}',
  defense_opportunities = '{"First-offense THC possession is a misdemeanor with a maximum of 6 months — diversion and deferred prosecution are commonly available","Some Wisconsin municipalities (Milwaukee, Madison) have local ordinances with lesser penalties for small amounts, potentially providing alternative charging","Challenge the substance identification — field test kits produce false positives, and lab confirmation may show a different substance or hemp (legal CBD)"}',
  common_defenses = '{"Legal hemp — substance was CBD/hemp product with THC below the legal threshold","Illegal search and seizure — odor of marijuana alone may be insufficient for a warrantless vehicle search in evolving case law","Lack of knowledge — defendant did not know the substance contained THC","Misidentification of the substance by field test"}'
