  prosecution_strengths = '{"Cocaine as a Schedule II substance carries higher baseline penalties than marijuana possession","Laboratory confirmation of cocaine is highly reliable and difficult to challenge on scientific grounds","Second offense automatically becomes a Class I Felony"}',
  defense_opportunities = '{"Challenge the search that produced the cocaine — consent searches, vehicle searches, and stop-and-frisk encounters each have constitutional requirements","Contest constructive possession when cocaine was found in a shared vehicle or residence","First-offense possession is still a misdemeanor — seek deferred prosecution or drug court diversion"}',
  common_defenses = '{"Illegal search and seizure — the search violated the Fourth Amendment","Lack of knowledge — defendant did not know cocaine was present","Constructive possession challenge — insufficient nexus between defendant and the contraband","Entrapment by law enforcement"}'
