  common_defenses = '{"Illegal search and seizure — warrantless search without valid exception","Lack of knowledge — defendant did not know the substance was methamphetamine","Constructive possession — insufficient evidence linking defendant to the substance in a shared space","Unwitting possession — substance was planted or left by another person"}'
