UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Wisconsin''s weight-based penalty tiers create escalating felony exposure: Class F (1-5g), Class E (5-15g), Class D (15-40g), Class C (40g+) for cocaine/heroin/meth","Mandatory minimums of 3-10 years apply at higher weight thresholds, limiting judicial discretion","Wiretap and surveillance evidence in trafficking investigations is typically extensive and difficult to challenge"}',
  defense_opportunities = '{"Challenge the drug weight calculations — prosecution must prove the actual weight of the controlled substance, not the total mixture weight, for certain penalty thresholds","Contest the school zone measurement — the 1,000-foot zone must be measured correctly, and errors in measurement can eliminate the enhancement","Argue the defendant''s role was minimal (courier, user-dealer) to seek lower sentencing within the guideline range","Challenge the reliability of confidential informant testimony — informants often have motives to exaggerate or fabricate"}',
  common_defenses = '{"Illegal search and seizure — suppression of evidence obtained through constitutional violations","Entrapment — government agent induced the defendant to engage in trafficking they would not otherwise have pursued","Insufficient evidence of intent to deliver — possession was for personal use, not distribution","Challenge to confidential informant reliability and credibility"}'
