UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Delivery of non-narcotic Schedule I-IV substances is a Class H Felony (up to 6 years), still carrying significant prison time","Controlled buys with audio/video recording provide strong direct evidence of delivery","THC (marijuana) delivery over 10,000g is a Class F Felony with substantial sentencing exposure"}',
  defense_opportunities = '{"Challenge the ''delivery'' element — sharing or joint possession may not constitute delivery under Wisconsin law","Contest the identification of the substance — field tests are presumptive only, and lab analysis may show a different substance or concentration","Negotiate reduction from delivery to simple possession where the evidence of distribution is circumstantial"}',
