UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Intent to deliver is proven through circumstantial evidence: quantity, packaging, scales, large cash, multiple phones, and distribution paraphernalia","Penalties mirror delivery statutes, so possession with intent carries the same serious exposure as actual distribution","School zone enhancement doubles the sentence and applies broadly in Wisconsin"}',
  defense_opportunities = '{"Challenge the inference of intent — argue the quantity, cash, or packaging is consistent with personal use rather than distribution","Contest the school zone measurement or applicability of the enhancement","Negotiate a reduction to simple possession if the evidence of intent is primarily circumstantial"}',
