UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"First-degree intentional homicide is Wisconsin''s only Class A Felony — mandatory life sentence with minimum 20 years before extended supervision eligibility","Prosecution only needs to prove intent to kill plus causation — no requirement to prove motive","Wisconsin does not have the death penalty, which may make juries less hesitant to convict than in capital jurisdictions","Court can deny extended supervision eligibility entirely, imposing life without parole"}',
  defense_opportunities = '{"Challenge the intent element — reckless conduct may support reckless homicide charges rather than intentional homicide","Contest forensic evidence (DNA, ballistics, blood spatter) through expert testimony"}',
  common_defenses = '{"Self-defense — reasonable belief that deadly force was necessary to prevent imminent death or great bodily harm","Defense of others — protecting a third person from imminent harm","Adequate provocation — heat of passion reducing the charge to a Class B Felony","Insanity or mental disease/defect — defendant lacked the capacity to form intent to kill","Misidentification — defendant was not the person who committed the killing"}'
WHERE common_charge_slug = 'murder-first-degree' AND jurisdiction = 'WI';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"The ''utter disregard for human life'' standard, while higher than ordinary recklessness, is still a conduct-based standard rather than intent-based","Prosecution can present the reckless homicide theory as an alternative to intentional homicide, giving the jury multiple conviction options"}',
  defense_opportunities = '{"Distinguish between ordinary recklessness (second-degree reckless homicide, Class D Felony, max 25 years) and ''utter disregard'' (first-degree, Class B Felony, max 60 years)","Contest whether the defendant''s conduct actually demonstrated ''utter disregard for human life'' versus ordinary recklessness"}',
  common_defenses = '{"Ordinary recklessness — conduct did not rise to ''utter disregard for human life,'' supporting a lesser charge","Self-defense — defendant''s reckless conduct was in response to an imminent threat","Accident — the death resulted from an unforeseeable accident, not criminal recklessness","Misidentification of the defendant"}'
