UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Even mitigated to Class B Felony, the maximum penalty is 60 years imprisonment","Prosecution can argue provocation was not ''adequate'' under the law, keeping the charge at first-degree intentional homicide","The prosecution can challenge the cooling-off period — if sufficient time passed for passion to subside, provocation fails"}',
  defense_opportunities = '{"Adequate provocation mitigates from Class A Felony (life) to Class B Felony (60 years), providing a massive sentencing reduction","Present evidence of the provocative conduct and the defendant''s emotional state to support the heat-of-passion element","Wisconsin''s provocation framework is an affirmative defense that the defense raises, allowing strategic presentation to the jury"}',
  common_defenses = '{"Heat of passion — killing occurred in the heat of passion after adequate provocation","Self-defense — partial self-defense may support a manslaughter verdict","Imperfect self-defense — defendant honestly but unreasonably believed deadly force was necessary","Mental health evidence supporting diminished capacity"}'
WHERE common_charge_slug = 'voluntary-manslaughter' AND jurisdiction = 'WI';

UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Criminal recklessness standard is lower than ''utter disregard'' — ordinary recklessness is sufficient","Dangerous weapon enhancer adds 5 additional years"}',
  defense_opportunities = '{"Distinguish between criminal recklessness and ordinary negligence — negligent conduct does not support a criminal conviction","Present evidence of unforeseeable circumstances that contributed to the death beyond the defendant''s control"}',
  common_defenses = '{"Ordinary negligence — defendant''s conduct was careless but not criminally reckless","Accident — the death resulted from an unforeseeable event","Intervening cause — an independent event or the victim''s own conduct caused the death","Lawful activity — defendant was engaged in a lawful activity that unexpectedly resulted in death"}'
