UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Class E Felony carrying up to 15 years, even without a weapon","Force or threat of force is a low threshold — snatching property forcibly from a person''s hand qualifies","Victim identification testimony combined with physical evidence (surveillance, recovered property) is often compelling"}',
  defense_opportunities = '{"Distinguish between robbery (force against person) and theft (no force) — if the taking did not involve force or threat, the robbery charge fails","Challenge the identification of the defendant through alibi evidence or witness reliability issues","Negotiate a reduction to theft charges where the force element is weak"}',
  common_defenses = '{"No force or threat — the taking was a theft, not a robbery","Misidentification — defendant was not the person who committed the robbery","Alibi — defendant was elsewhere when the robbery occurred","Claim of right — defendant believed they had a legal right to the property"}'
