UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Class F Felony (up to 12.5 years) for basic burglary — no requirement of nighttime entry or dwelling","Armed burglary or burglary with battery elevates to Class E Felony (up to 15 years)","Physical evidence (tool marks, fingerprints, DNA, surveillance) frequently links defendants to the entry"}',
