UPDATE jurisdiction_statutes SET
  prosecution_strengths = '{"Wyoming uses ''actual physical control'' standard, allowing prosecution even when the vehicle is parked or the defendant is sleeping behind the wheel","Per se BAC of .08 eliminates the need to prove actual impairment when chemical test results are available","Wyoming''s wide-open rural geography makes traffic stops on long stretches of I-80 and I-25 a major source of DWUI prosecutions"}',
